INSERT INTO public.query VALUES ('\x3a12fb0990389a1c770841883cbff95d01baf954d7cd4c66d127ad463fb23cd2', 50, '{"lib/type":"mbql/query","database":2,"stages":[{"lib/type":"mbql.stage/native","native":"SELECT\n  -- `periode_bulan` AS `periode_bulan`,\n  -- `vendor_otd_pct` AS `vendor_otd_pct`\n  *\nFROM\n  `kba_gold`.`gold_budget_adherence_vendor_otd`\n-- WHERE {{bulan}}\nWHERE `periode_bulan` <= \nCOALESCE(\n    [[ toStartOfMonth(toDate({{bulan}})) , ]] \n    toStartOfMonth(now())\n  ) AND `periode_bulan` >= \n    COALESCE(\n      [[ addMonths(toStartOfMonth(toDate({{bulan}})), -11) , ]] \n      addMonths(toStartOfMonth(now()), -11)\n    )\nORDER BY `periode_bulan` ASC\n\n-- select date(now())","template-tags":{"bulan":{"name":"bulan","id":"24ad855b-b71e-4c8c-835d-45291c9163f9","type":"date","display-name":"Bulan","default":null}}}],"parameters":[{"id":"24ad855b-b71e-4c8c-835d-45291c9163f9","type":"date/single","value":null,"target":["variable",["template-tag","bulan"]]}],"middleware":{"js-int-to-string?":true,"userland-query?":true,"add-default-userland-constraints?":true}}');
