INSERT INTO public.query VALUES ('\xd6ded670e7bf639f48731ad1ad2932642b93fb132fbb949c58c2a38d1726f28a', 29, '{"lib/type":"mbql/query","stages":[{"lib/type":"mbql.stage/native","native":"SELECT\n  `kba_gold`.`gold_sales_achievement_conversion`.`periode_bulan` AS `periode_bulan`,\n  `kba_gold`.`gold_sales_achievement_conversion`.`aktual_penjualan` AS `aktual_penjualan`,\n  `kba_gold`.`gold_sales_achievement_conversion`.`target_penjualan` AS `target_penjualan`\nFROM\n  `kba_gold`.`gold_sales_achievement_conversion`\nWHERE {{bulan}}","template-tags":{"bulan":{"default":"2026-04","id":"74cd5962-2978-4cc9-99e6-5f9972afe321","dimension":["field",{"lib/uuid":"b5d67383-0b01-4275-b6c4-4830752e3573"},405],"type":"dimension","widget-type":"date/month-year","name":"bulan","display-name":"Bulan","required":true}}}],"database":2,"parameters":[{"id":"74cd5962-2978-4cc9-99e6-5f9972afe321","type":"date/month-year","value":"2026-04","target":["dimension",["template-tag","bulan"]]}],"middleware":{"js-int-to-string?":true,"userland-query?":true,"add-default-userland-constraints?":true}}');
INSERT INTO public.query VALUES ('\x99e2d2b0298ca0b38c9633891444f433df91b92dc3528efecbb5117444991372', 19, '{"lib/type":"mbql/query","database":2,"stages":[{"native":"SELECT\n  `periode_bulanan`,\n  `source`.`is_slow_moving` AS `is_slow_moving`,\n  `source`.`count` AS `count`,\n  `source`.`count` AS `Jumlah Produk`\nFROM\n  (\n    SELECT\n\t  `periode_bulanan`,\n      FLOOR(\n        (\n          `kba_gold`.`gold_slow_moving`.`is_slow_moving` / 0.125\n        )\n      ) * 0.125 AS `is_slow_moving`,\n      COUNT(*) AS `count`\n    FROM\n      `kba_gold`.`gold_slow_moving`\n    GROUP BY\n\t  `periode_bulanan`,\n      FLOOR(\n        (\n          `kba_gold`.`gold_slow_moving`.`is_slow_moving` / 0.125\n        )\n      ) * 0.125\n    ORDER BY\n      FLOOR(\n        (\n          `kba_gold`.`gold_slow_moving`.`is_slow_moving` / 0.125\n        )\n      ) * 0.125 ASC\n  ) AS `source`\nWHERE `periode_bulanan` = \nCOALESCE(\n    [[ toStartOfMonth(toDate({{bulan}})) , ]] \n    toStartOfMonth(now())\n  )","lib/type":"mbql.stage/native","template-tags":{"bulan":{"display-name":"Bulan","name":"bulan","id":"48db9bbd-7275-44f0-8540-56ef79f4ea38","type":"date","default":null}}}],"parameters":[{"id":"48db9bbd-7275-44f0-8540-56ef79f4ea38","type":"date/single","value":null,"target":["variable",["template-tag","bulan"]]}],"middleware":{"js-int-to-string?":true,"userland-query?":true,"add-default-userland-constraints?":true}}');
