INSERT INTO public.query VALUES ('\x483e9c8b03791b7cbd942bf276fa9610af5001c8ecff5e93f34f620b8ad2e903', 18, '{"lib/type":"mbql/query","stages":[{"lib/type":"mbql.stage/native","native":"SELECT\n  FLOOR(\n    (\n      `kba_gold`.`gold_slow_moving`.`is_slow_moving` / 0.125\n    )\n  ) * 0.125 AS `is_slow_moving`,\n  COUNT(*) AS `count`\nFROM\n  `kba_gold`.`gold_slow_moving`\nGROUP BY\n  FLOOR(\n    (\n      `kba_gold`.`gold_slow_moving`.`is_slow_moving` / 0.125\n    )\n  ) * 0.125\nORDER BY\n  FLOOR(\n    (\n      `kba_gold`.`gold_slow_moving`.`is_slow_moving` / 0.125\n    )\n  ) * 0.125 ASC"}],"database":2,"middleware":{"js-int-to-string?":true,"userland-query?":true,"add-default-userland-constraints?":true}}');
