INSERT INTO public.query VALUES ('\x0aaa2a5989e62abbaea1163357d2ef78720f51ae12d5566cc999566bbb9910d9', 38, '{"lib/type":"mbql/query","stages":[{"lib/type":"mbql.stage/native","native":"SELECT\n  `kba_gold`.`gold_top_spending`.`periode_bulan` AS `periode_bulan`,\n  `kba_gold`.`gold_top_spending`.`id_produk` AS `id_produk`,\n  `kba_gold`.`gold_top_spending`.`nama_produk` AS `nama_produk`,\n  `kba_gold`.`gold_top_spending`.`total_pengeluaran_produk` AS `total_pengeluaran_produk`,\n  `kba_gold`.`gold_top_spending`.`rank_pengeluaran` AS `rank_pengeluaran`\nFROM\n  `kba_gold`.`gold_top_spending`\nWHERE\n  (\n    `kba_gold`.`gold_top_spending`.`periode_bulan` >= `toStartOfMonth`((`now64`(9) + INTERVAL -1 month))\n  )\n  AND (\n    `kba_gold`.`gold_top_spending`.`periode_bulan` < `toStartOfMonth`(`now64`(9))\n  )\nORDER BY\n  `kba_gold`.`gold_top_spending`.`rank_pengeluaran` ASC\nLIMIT\n  1048575"}],"database":2,"middleware":{"js-int-to-string?":true,"userland-query?":true,"add-default-userland-constraints?":true}}');
INSERT INTO public.query VALUES ('\xba0f6c0ad4d82cefe105db0587d7a2f32cacbe2f90008d9dc99de30744296839', 128, '{"constraints":{"max-results":10000,"max-results-bare-rows":2000},"lib/type":"mbql/query","lib/metadata":null,"stages":[{"lib/type":"mbql.stage/native","native":"SELECT\n  `periode_bulanan`,\n  `source`.`is_slow_moving` AS `is_slow_moving`,\n  `source`.`count` AS `count`,\n  `source`.`count` AS `Jumlah Produk`\nFROM\n  (\n    SELECT\n\t  `periode_bulanan`,\n      FLOOR(\n        (\n          `kba_gold`.`gold_slow_moving`.`is_slow_moving` / 0.125\n        )\n      ) * 0.125 AS `is_slow_moving`,\n      COUNT(*) AS `count`\n    FROM\n      `kba_gold`.`gold_slow_moving`\n    GROUP BY\n\t  `periode_bulanan`,\n      FLOOR(\n        (\n          `kba_gold`.`gold_slow_moving`.`is_slow_moving` / 0.125\n        )\n      ) * 0.125\n    ORDER BY\n      FLOOR(\n        (\n          `kba_gold`.`gold_slow_moving`.`is_slow_moving` / 0.125\n        )\n      ) * 0.125 ASC\n  ) AS `source`\nWHERE `periode_bulanan` = \nCOALESCE(\n    [[ toStartOfMonth(toDate({{bulan}})) , ]] \n    toStartOfMonth(now())\n  )","template-tags":{"bulan":{"id":"48db9bbd-7275-44f0-8540-56ef79f4ea38","type":"date","display-name":"Bulan","name":"bulan","default":"2026-03-30"}}}],"middleware":{"js-int-to-string?":true,"ignore-cached-results?":false,"process-viz-settings?":false,"userland-query?":true},"cache-strategy":null,"viz-settings":{"pie.rows":[{"key":"1","name":"Slow Moving","originalName":"1","color":"#F7C41F","defaultColor":false,"enabled":true,"hidden":false,"isOther":false},{"key":"0","name":"Non Slow Moving","originalName":"0","color":"#227FD2","defaultColor":false,"enabled":true,"hidden":false,"isOther":false},{"isOther":false,"hidden":true,"enabled":false,"defaultColor":true,"color":"#509EE3","originalName":"Three-Seat Sofa","name":"Three-Seat Sofa","key":"Three-Seat Sofa"},{"key":"Office Chair","name":"Office Chair","originalName":"Office Chair","color":"#87BCEC","defaultColor":true,"enabl