INSERT INTO public.query VALUES ('\x560773d7b045a3f3c7f8800ebd2b8901281d4aacd5b909b21069620abbb5c8d8', 27, '{"constraints":{"max-results":10000,"max-results-bare-rows":2000},"lib/type":"mbql/query","lib/metadata":null,"stages":[{"lib/type":"mbql.stage/native","native":"-- SELECT\n--   `periode_bulan` AS `periode_bulan`,\n--   `vendor_otd_pct` AS `vendor_otd_pct`\n-- FROM\n--   `kba_gold`.`gold_budget_adherence_vendor_otd`\n-- WHERE\n--   (\n--     `periode_bulan` >= `toStartOfMonth`((`now64`(9) + INTERVAL -1 month))\n--   )\n\n\nSELECT\n  -- `periode_bulan` AS `periode_bulan`,\n  -- `vendor_otd_pct` AS `vendor_otd_pct`\n  *\nFROM\n  `kba_gold`.`gold_budget_adherence_vendor_otd`\n-- WHERE {{bulan}}\nWHERE `periode_bulan` <= toStartOfMonth(toDate({{bulan}}))\nORDER BY `periode_bulan` ASC\n\n-- select date(now())","template-tags":{"bulan":{"type":"date","name":"bulan","default":"2026-04-27","id":"c75bcbee-606d-4fa8-a41a-13ba983bae2f","display-name":"Bulan","required":true}}}],"middleware":{"js-int-to-string?":true,"ignore-cached-results?":false,"userland-query?":true},"cache-strategy":null,"viz-settings":{"table.pivot_column":"periode_bulan","table.cell_column":"vendor_otd_pct","progress.goal":90,"progress.color":"#689636","gauge.segments":[{"min":0,"max":50,"color":"#E3595E","label":"Jauh dari Target"},{"min":50,"max":90,"color":"#E8B921","label":"Hampir Tercapai"},{"min":90,"max":100,"color":"#689735","label":"Target Tercapai"}],"scalar.field":"vendor_otd_pct","scalar.comparisons":[{"id":"7dcd18ad-52db-979e-bde0-08256e452ac9","type":"staticNumber","label":"Target Vendor OTD","value":90},{"id":"bbcc1092-784c-0f5d-96e0-d282b9413c1c","type":"previousPeriod"}],"column_settings":{"[\"name\",\"vendor_otd_pct\"]":{"suffix":"%"}}},"database":2}');
INSERT INTO public.query VALUES ('\xf41d7471426b8a1ea088e4e4093e94b4bd4972b8c92e7d7cc9d2e9fc420f0d3d', 23, '{"lib/type":"mbql/query","stages":[{"native":"SELECT\n  `kba_gold`.`gold_vendor`.`periode_bulan` AS `periode_bulan`,\n  `kba_gold`.`gold_vendor`.`id_vendor` AS `id_vendor`,\n  `kba_gold`.`gold_vendor`.`nama_vendor` AS `nama_vendor`,\n  `kba_gold`.`gold_vendor`.`total_pengiriman` AS `total_pengiriman`,\n  `kba_gold`.`gold_vendor`.`tepat_waktu` AS `tepat_waktu`,\n  `kba_gold`.`gold_vendor`.`otd_pct` AS `otd_pct`\nFROM\n  `kba_gold`.`gold_vendor`\nWHERE `periode_bulan` = \nCOALESCE(\n    [[ toStartOfMonth(toDate({{bulan}})) , ]] \n    toStartOfMonth(now())\n  )\norder by otd_pct desc","lib/type":"mbql.stage/native","template-tags":{"bulan":{"type":"date","name":"bulan","display-name":"Bulan","id":"fd5402b5-cb4a-4a5f-9f24-2ed362ee20f3","default":"2026-04-02"}}}],"database":2,"parameters":[{"id":"fd5402b5-cb4a-4a5f-9f24-2ed362ee20f3","type":"date/single","value":"2026-04-02","target":["variable",["template-tag","bulan"]]}],"middleware":{"js-int-to-string?":true,"userland-query?":true,"add-default-userland-constraints?":true}}');
