INSERT INTO public.query VALUES ('\x9f5c07c375325caca1529b015c666a26d62dd9de3b8ce75083444cd66b49e3cf', 22, '{"lib/type":"mbql/query","database":2,"stages":[{"native":"SELECT\n  `kba_gold`.`gold_slow_moving`.`periode_bulanan` AS `Periode Bulan`,\n  `kba_gold`.`gold_slow_moving`.`id_produk` AS `ID Produk`,\n  `kba_gold`.`gold_slow_moving`.`nama_produk` AS `Nama Produk`,\n  `kba_gold`.`gold_slow_moving`.`nilai_stok` AS `Nilai Stok`,\n  `kba_gold`.`gold_slow_moving`.`demand_segment` AS `demand_segment`,\n  `kba_gold`.`gold_slow_moving`.`is_slow_moving` AS `is_slow_moving`,\n  `kba_gold`.`gold_slow_moving`.`slow_moving_reason` AS `slow_moving_reason`\nFROM\n  `kba_gold`.`gold_slow_moving`\nWHERE `periode_bulanan` = \nCOALESCE(\n    [[ toStartOfMonth(toDate({{bulan}})) , ]] \n    toStartOfMonth(now())\n  ) AND `is_slow_moving` = 1\nORDER BY is_slow_moving desc, nilai_stok desc","lib/type":"mbql.stage/native","template-tags":{"bulan":{"id":"1fd9c625-2306-44ff-8e1d-3e60000472f0","display-name":"Bulan","type":"date","name":"bulan","default":"2026-04-02"}}}],"parameters":[{"id":"1fd9c625-2306-44ff-8e1d-3e60000472f0","type":"date/single","value":"2026-04-02","target":["variable",["template-tag","bulan"]]}],"middleware":{"js-int-to-string?":true,"userland-query?":true,"add-default-userland-constraints?":true}}');
