INSERT INTO public.query VALUES ('\xf8bf9b32698fdc7fe84080821ef171978db873fc4342b4d6eff49149207912d9', 27, '{"lib/type":"mbql/query","stages":[{"native":"SELECT\n  `source`.`nama_produk` AS `nama_produk`,\n  `source`.`sum` AS `sum`,\n  `source`.`Total Sales` AS `Total Sales`\nFROM\n  (\n    SELECT\n      `source`.`nama_produk` AS `nama_produk`,\n      `source`.`sum` AS `sum`,\n      `source`.`sum` AS `Total Sales`\n    FROM\n      (\n        SELECT\n\t\t  `kba_gold`.`gold_product_performance`.`periode_bulan` AS `periode_bulan`,\n          `kba_gold`.`gold_product_performance`.`nama_produk` AS `nama_produk`,\n          SUM(\n            `kba_gold`.`gold_product_performance`.`total_sales`\n          ) AS `sum`\n        FROM\n          `kba_gold`.`gold_product_performance`\n        GROUP BY\n          `kba_gold`.`gold_product_performance`.`nama_produk`\n        ORDER BY\n          `kba_gold`.`gold_product_performance`.`nama_produk` ASC\n      ) AS `source`\n  ) AS `source`\nORDER BY\n  `source`.`Total Sales` DESC\nLIMIT\n  1048575","lib/type":"mbql.stage/native","template-tags":{}}],"database":2,"middleware":{"js-int-to-string?":true,"userland-query?":true,"add-default-userland-constraints?":true}}');
INSERT INTO public.query VALUES ('\x82d4ce7aef772bfaca99701c0f3c042cce504d20078916eb2f211a7b5ff796f1', 17, '{"lib/type":"mbql/query","database":2,"stages":[{"lib/type":"mbql.stage/native","native":"SELECT\n  `kba_gold`.`gold_vendor`.`id_vendor` AS `id_vendor`,\n  `kba_gold`.`gold_vendor`.`nama_vendor` AS `nama_vendor`,\n  `kba_gold`.`gold_vendor`.`periode_bulan` AS `periode_bulan`,\n  `kba_gold`.`gold_vendor`.`total_pengiriman` AS `total_pengiriman`,\n  `kba_gold`.`gold_vendor`.`tepat_waktu` AS `tepat_waktu`,\n  `kba_gold`.`gold_vendor`.`terlambat` AS `terlambat`,\n  `kba_gold`.`gold_vendor`.`otd_pct` AS `otd_pct`,\n  `kba_gold`.`gold_vendor`.`avg_delay_days` AS `avg_delay_days`,\n  `kba_gold`.`gold_vendor`.`max_delay_days` AS `max_delay_days`,\n  `kba_gold`.`gold_vendor`.`internal_scheduling_gap` AS `internal_scheduling_gap`\nFROM\n  `kba_gold`.`gold_vendor`\nWHERE `periode_bulan` = \nCOALESCE(\n    [[ toStartOfMonth(toDate({{bulan}})) , ]] \n    toStartOfMonth(now())\n  )","template-tags":{"bulan":{"id":"95bbe1ac-580d-4a03-b034-5fddaa5daba7","type":"date","display-name":"Bulan","name":"bulan","default":null}}}],"parameters":[{"id":"95bbe1ac-580d-4a03-b034-5fddaa5daba7","type":"date/single","value":null,"target":["variable",["template-tag","bulan"]]}],"middleware":{"js-int-to-string?":true,"userland-query?":true,"add-default-userland-constraints?":true}}');
INSERT INTO public.query VALUES ('\xfc1ba6f5a1072b2121aa08c9653aa6cf241b8db3b0625c39bbc042cf45d572cb', 29, '{"constraints":{"max-results":10000,"max-results-bare-rows":2000},"lib/type":"mbql/query","lib/metadata":null,"stages":[{"lib/type":"mbql.stage/native","native":"SELECT\n-- `kba_gold`.`gold_budget_adherence_vendor_otd`.`budget_usage_pct` AS `budget_usage_pct`\n*\nFROM\n  `kba_gold`.`gold_budget_adherence_vendor_otd`\nWHERE `periode_bulan` <= \nCOALESCE(\n    [[ toStartOfMonth(toDate({{bulan}})) , ]] \n    toStartOfMonth(now())\n  )\n  AND (\n    SELECT count(*) \n    FROM `kba_gold`.`gold_budget_adherence_vendor_otd` \n    WHERE `periode_bulan` = \n\tCOALESCE(\n    [[ toStartOfMonth(toDate({{bulan}})) , ]] \n    toStartOfMonth(now())\n  ) \n  ) > 0\nORDER BY `periode_bulan` ASC","template-tags":{"bulan":{"id":"63ec009d-9950-498c-bfd5-b69b769aaccf","type":"date","display-name":"Bulan","name":"bulan","default":"2026-01-02"}}}],"middleware":{"js-int-to-string?":true,"ignore-cached-results?":false,"userland-query?":true},"cache-strategy":null,"viz-settings":{"gauge.segments":[{"min":0,"max":90,"color":"#689735","label":"Aman"},{"min":90,"max":95,"color":"#E8B921","label":"Beresiko"},{"min":95,"max":100,"color":"#E3595E","label":"Melebihi Batas"}],"table.pivot_column":"periode_bulan","table.cell_column":"total_pengeluaran_po","scalar.field":"budget_usage_pct","scalar.comparisons":[{"id":"e90f3a91-ecfe-5326-a698-20a3c7cac6b3","type":"staticNumber","label":"Maximum Usage","value":90},{"id":"a63dcca3-f5fc-3e6a-7494-896bfcf8dc7f","type":"previousPeriod"}],"scalar.switch_positive_negative":true,"column_settings":{"[\"name\",\"budget_usage_pct\"]":{"suffix":"%"}}},"database":2,"parameters":[{"type":"date/single","value":"2026-02-03","id":"695f1b78","target":["variable",["template-tag","bulan"]]}]}');
