INSERT INTO public.query VALUES ('\x8945dcf0aa9bc9000232262ffd3b6733ff19fc6a4a36a614c31fbdcc5f9fb810', 52, '{"lib/type":"mbql/query","stages":[{"native":"SELECT\n  `source`.`nama_produk` AS `nama_produk`,\n  `source`.`sum` AS `sum`,\n  `source`.`Total Sales` AS `Total Sales`\nFROM\n  (\n    SELECT\n      `source`.`nama_produk` AS `nama_produk`,\n      `source`.`sum` AS `sum`,\n      `source`.`sum` AS `Total Sales`\n    FROM\n      (\n        SELECT\n          `kba_gold`.`gold_product_performance`.`nama_produk` AS `nama_produk`,\n          SUM(\n            `kba_gold`.`gold_product_performance`.`total_sales`\n          ) AS `sum`\n        FROM\n          `kba_gold`.`gold_product_performance`\n        GROUP BY\n          `kba_gold`.`gold_product_performance`.`nama_produk`\n        ORDER BY\n          `kba_gold`.`gold_product_performance`.`nama_produk` ASC\n      ) AS `source`\n  ) AS `source`\nWHERE `periode_bulan` <= \nCOALESCE(\n    [[ toStartOfMonth(toDate({{bulan}})) , ]] \n    toStartOfMonth(now())\n  )\nORDER BY\n  `source`.`Total Sales` DESC\nLIMIT\n  1048575","lib/type":"mbql.stage/native","template-tags":{"bulan":{"name":"bulan","id":"4b499759-330c-4c01-8450-7fae9ef6fa3b","type":"date","display-name":"Bulan"}}}],"database":2,"parameters":[{"id":"4b499759-330c-4c01-8450-7fae9ef6fa3b","type":"date/single","value":null,"target":["variable",["template-tag","bulan"]]}],"middleware":{"js-int-to-string?":true,"userland-query?":true,"add-default-userland-constraints?":true}}');
