INSERT INTO public.query VALUES ('\xed593510ace6645393d41fba9136200d4d64e27d4b7f6fb42141d1923cf444f8', 26, '{"lib/type":"mbql/query","database":2,"stages":[{"native":"SELECT\n*,\n  SUM(CASE WHEN is_slow_moving = 1 THEN nilai_stok ELSE 0 END) AS total_stok_slow_moving,\n  SUM(nilai_stok) AS total_seluruh_stok,\n  SUM(CASE WHEN is_slow_moving = 1 THEN nilai_stok ELSE 0 END) * 100 / SUM(nilai_stok) AS rasio_slow_moving\nFROM\n  `kba_gold`.`gold_slow_moving`\n","lib/type":"mbql.stage/native","template-tags":{}}],"middleware":{"js-int-to-string?":true,"userland-query?":true,"add-default-userland-constraints?":true}}');
