INSERT INTO public.query VALUES ('\xe3421264d48d7987d50358422054c0b9f68743fbc2908adf8a18f5bdc4d193a3', 24, '{"constraints":{"max-results":10000,"max-results-bare-rows":2000},"lib/type":"mbql/query","lib/metadata":null,"stages":[{"lib/type":"mbql.stage/native","native":"SELECT\n-- `kba_gold`.`gold_budget_adherence_vendor_otd`.`budget_usage_pct` AS `budget_usage_pct`\n*\nFROM\n  `kba_gold`.`gold_budget_adherence_vendor_otd`\nWHERE `periode_bulan` <= \nCOALESCE(\n    [[ toStartOfMonth(toDate({{bulan}})) , ]] \n    toStartOfMonth(now())\n  )\n  AND (\n    SELECT count(*) \n    FROM `kba_gold`.`gold_budget_adherence_vendor_otd` \n    WHERE `periode_bulan` = \n\tCOALESCE(\n    [[ toStartOfMonth(toDate({{bulan}})) , ]] \n    toStartOfMonth(now())\n  ) \n  ) > 0\nORDER BY `periode_bulan` ASC","template-tags":{"bulan":{"id":"63ec009d-9950-498c-bfd5-b69b769aaccf","type":"date","display-name":"Bulan","name":"bulan","default":"2026-01-02"}}}],"middleware":{"js-int-to-string?":true,"ignore-cached-results?":false,"userland-query?":true},"cache-strategy":null,"viz-settings":{"gauge.segments":[{"min":0,"max":90,"color":"#689735","label":"Aman"},{"min":90,"max":95,"color":"#E8B921","label":"Beresiko"},{"min":95,"max":100,"color":"#E3595E","label":"Melebihi Batas"}],"table.pivot_column":"periode_bulan","table.cell_column":"total_pengeluaran_po","scalar.field":"budget_usage_pct","scalar.comparisons":[{"id":"e90f3a91-ecfe-5326-a698-20a3c7cac6b3","type":"staticNumber","label":"Maximum Usage","value":90},{"id":"a63dcca3-f5fc-3e6a-7494-896bfcf8dc7f","type":"previousPeriod"}],"scalar.switch_positive_negative":true,"column_settings":{"[\"name\",\"budget_usage_pct\"]":{"suffix":"%"}}},"database":2,"parameters":[{"type":"date/single","value":"2026-04-28","id":"695f1b78","target":["variable",["template-tag","bulan"]]}]}');
INSERT INTO public.query VALUES ('\x5a3da096e78c253474961406fc62c9a9f4027fa659772f3d2d32daf7b3f3f3f4', 23, '{"constraints":{"max-results":10000,"max-results-bare-rows":2000},"lib/type":"mbql/query","lib/metadata":null,"stages":[{"lib/type":"mbql.stage/native","native":"SELECT\n  -- `periode_bulan` AS `periode_bulan`,\n  -- `vendor_otd_pct` AS `vendor_otd_pct`\n  *\nFROM\n  `kba_gold`.`gold_budget_adherence_vendor_otd`\n-- WHERE {{bulan}}\nWHERE `periode_bulan` <= \nCOALESCE(\n    [[ toStartOfMonth(toDate({{bulan}})) , ]] \n    toStartOfMonth(now())\n  ) \n  AND (\n    SELECT count(*) \n    FROM `kba_gold`.`gold_budget_adherence_vendor_otd` \n    WHERE `periode_bulan` = \n\tCOALESCE(\n    [[ toStartOfMonth(toDate({{bulan}})) , ]] \n    toStartOfMonth(now())\n  ) \n  ) > 0\nORDER BY `periode_bulan` ASC\n\n-- select date(now())","template-tags":{"bulan":{"name":"bulan","id":"24ad855b-b71e-4c8c-835d-45291c9163f9","type":"date","display-name":"Bulan","default":"2025-12-28"}}}],"middleware":{"js-int-to-string?":true,"ignore-cached-results?":false,"userland-query?":true},"cache-strategy":null,"viz-settings":{"table.pivot_column":"periode_bulan","table.cell_column":"vendor_otd_pct","progress.goal":90,"progress.color":"#689636","gauge.segments":[{"min":0,"max":50,"color":"#E3595E","label":"Jauh dari Target"},{"min":50,"max":90,"color":"#E8B921","label":"Hampir Tercapai"},{"min":90,"max":100,"color":"#689735","label":"Target Tercapai"}],"scalar.field":"vendor_otd_pct","scalar.comparisons":[{"id":"7dcd18ad-52db-979e-bde0-08256e452ac9","type":"staticNumber","label":"Target Vendor OTD","value":90},{"id":"bbcc1092-784c-0f5d-96e0-d282b9413c1c","type":"previousPeriod"}],"column_settings":{"[\"name\",\"vendor_otd_pct\"]":{"suffix":"%"}}},"database":2,"parameters":[{"type":"date/single","value":"2026-04-28","id":"695f1b78","target":["variable",["template-tag","bulan"]]}]}');
INSERT INTO public.query VALUES ('\x8e5effda742f813afac4e9e466f5dc2fafdbcc41906c9a2c9acc7a16737d4e66', 19, '{"constraints":{"max-results":10000,"max-results-bare-rows":2000},"lib/type":"mbql/query","lib/metadata":null,"stages":[{"native":"SELECT\n  `kba_gold`.`gold_sales_achievement_conversion`.`periode_bulan` AS `periode_bulan`,\n  `kba_gold`.`gold_sales_achievement_conversion`.`total_quotation` AS `total_quotation`,\n  `kba_gold`.`gold_sales_achievement_conversion`.`aktual_penjualan` AS `aktual_penjualan`\nFROM\n  `kba_gold`.`gold_sales_achievement_conversion`\nWHERE `periode_bulan` = \nCOALESCE(\n    [[ toStartOfMonth(toDate({{bulan}})) , ]] \n    toStartOfMonth(now())\n  ) ","lib/type":"mbql.stage/native","template-tags":{"bulan":{"id":"4a2773aa-194a-4f04-ac4d-f87a2d681b8b","type":"date","name":"bulan","display-name":"Bulan","required":false}}}],"middleware":{"js-int-to-string?":true,"ignore-cached-results?":false,"userland-query?":true},"cache-strategy":null,"viz-settings":{"column_settings":{"[\"name\",\"periode_bulan\"]":{"column_title":"Periode Bulan","date_style":"D MMMM, YYYY"},"[\"name\",\"total_quotation\"]":{"column_title":"Total Quotation","number_separators":", ","prefix":"$"},"[\"name\",\"aktual_penjualan\"]":{"column_title":"Penjualan Aktual","number_separators":", ","prefix":"$"}}},"database":2,"parameters":[{"type":"date/single","value":null,"id":"29b9c635","target":["variable",["template-tag","bulan"]]}]}');
INSERT INTO public.query VALUES ('\x96dadcdd020cbc8a8dc51ba05e7595b937a7ee498c69233d2e13f5f132d59c4b', 20, '{"constraints":{"max-results":10000,"max-results-bare-rows":2000},"lib/type":"mbql/query","lib/metadata":null,"stages":[{"native":"SELECT\n  `periode_bulanan`,\n  SUM(CASE WHEN is_slow_moving = 1 THEN nilai_stok ELSE 0 END) AS total_stok_slow_moving,\n  SUM(nilai_stok) AS total_seluruh_stok,\n  SUM(CASE WHEN is_slow_moving = 1 THEN nilai_stok ELSE 0 END) * 100 / SUM(nilai_stok) AS rasio_slow_moving\nFROM\n  `kba_gold`.`gold_slow_moving`\nWHERE `periode_bulanan` <= \nCOALESCE(\n    [[ toStartOfMonth(toDate({{bulan}})) , ]] \n    toStartOfMonth(now())\n  )\nGROUP BY `periode_bulanan`","lib/type":"mbql.stage/native","template-tags":{"bulan":{"display-name":"Bulan","name":"bulan","id":"c27cea3d-ca3b-40f7-8533-8182000603b8","type":"date","default":null}}}],"middleware":{"js-int-to-string?":true,"ignore-cached-results?":false,"userland-query?":true},"cache-strategy":null,"viz-settings":{"scalar.field":"rasio_slow_moving","scalar.segments":[{"min":0,"max":24,"color":"#689735","label":"Aman"},{"min":25,"max":59,"color":"#E8B921","label":"Waspada"},{"min":60,"max":100,"color":"#E3595E","label":"Kritis"}],"column_settings":{"[\"name\",\"rasio_slow_moving\"]":{"suffix":"%"}}},"database":2,"parameters":[{"type":"date/single","value":"2026-04-28","id":"695f1b78","target":["variable",["template-tag","bulan"]]}]}');
INSERT INTO public.query VALUES ('\x1c8f22b8ae776ed8b66e0b657134d448d2ef02e6a2f366efbcde5587ff01d910', 23, '{"constraints":{"max-results":10000,"max-results-bare-rows":2000},"lib/type":"mbql/query","lib/metadata":null,"stages":[{"lib/type":"mbql.stage/native","native":"SELECT\n`kba_gold`.`gold_budget_adherence_vendor_otd`.`periode_bulan` AS `periode_bulan`,\n`kba_gold`.`gold_budget_adherence_vendor_otd`.`budget_usage_pct` AS `budget_usage_pct`\nFROM\n  `kba_gold`.`gold_budget_adherence_vendor_otd`\n-- WHERE {{bulan}}\nWHERE `periode_bulan` <= date(now())\nORDER BY `periode_bulan` ASC"}],"middleware":{"js-int-to-string?":true,"ignore-cached-results?":false,"process-viz-settings?":false,"userland-query?":true},"cache-strategy":null,"viz-settings":{"scalar.comparisons":[{"id":"e90f3a91-ecfe-5326-a698-20a3c7cac6b3","type":"staticNumber","label":"Maximum Usage","value":90},{"id":"a63dcca3-f5fc-3e6a-7494-896bfcf8dc7f","type":"previousPeriod"}],"graph.y_axis.title_text":"Value","table.cell_column":"total_pengeluaran_po","graph.x_axis.title_text":"Periode","gauge.segments":[{"min":0,"max":90,"color":"#689735","label":"Aman"},{"min":90,"max":95,"color":"#E8B921","label":"Beresiko"},{"min":95,"max":100,"color":"#E3595E","label":"Melebihi Batas"}],"graph.metrics":["budget_usage_pct"],"scalar.field":"budget_usage_pct","scalar.switch_positive_negative":true,"table.pivot_column":"periode_bulan","column_settings":{"[\"name\",\"budget_usage_pct\"]":{"suffix":"%"}},"series_settings":{"budget_usage_pct":{"color":"#227FD2"}},"graph.x_axis.scale":"timeseries","graph.dimensions":["periode_bulan"]},"database":2}');
INSERT INTO public.query VALUES ('\x948bc3fd2e7231c26fd1811006009a8ebee4562359a11c5da540756996dafcc0', 24, '{"constraints":{"max-results":10000,"max-results-bare-rows":2000},"lib/type":"mbql/query","lib/metadata":null,"stages":[{"lib/type":"mbql.stage/native","native":"SELECT\n  `periode_bulanan`,\n  `source`.`is_slow_moving` AS `is_slow_moving`,\n  `source`.`count` AS `count`,\n  `source`.`count` AS `Jumlah Produk`\nFROM\n  (\n    SELECT\n\t  `periode_bulanan`,\n      FLOOR(\n        (\n          `kba_gold`.`gold_slow_moving`.`is_slow_moving` / 0.125\n        )\n      ) * 0.125 AS `is_slow_moving`,\n      COUNT(*) AS `count`\n    FROM\n      `kba_gold`.`gold_slow_moving`\n    GROUP BY\n\t  `periode_bulanan`,\n      FLOOR(\n        (\n          `kba_gold`.`gold_slow_moving`.`is_slow_moving` / 0.125\n        )\n      ) * 0.125\n    ORDER BY\n      FLOOR(\n        (\n          `kba_gold`.`gold_slow_moving`.`is_slow_moving` / 0.125\n        )\n      ) * 0.125 ASC\n  ) AS `source`\nWHERE `periode_bulanan` = \nCOALESCE(\n    [[ toStartOfMonth(toDate({{bulan}})) , ]] \n    toStartOfMonth(now())\n  )","template-tags":{"bulan":{"id":"48db9bbd-7275-44f0-8540-56ef79f4ea38","type":"date","display-name":"Bulan","name":"bulan","default":"2026-03-30"}}}],"middleware":{"js-int-to-string?":true,"ignore-cached-results?":false,"userland-query?":true},"cache-strategy":null,"viz-settings":{"pie.rows":[{"key":"1","name":"Slow Moving","originalName":"1","color":"#F7C41F","defaultColor":false,"enabled":true,"hidden":false,"isOther":false},{"key":"0","name":"Non Slow Moving","originalName":"0","color":"#227FD2","defaultColor":false,"enabled":true,"hidden":false,"isOther":false},{"isOther":false,"hidden":true,"enabled":false,"defaultColor":true,"color":"#509EE3","originalName":"Three-Seat Sofa","name":"Three-Seat Sofa","key":"Three-Seat Sofa"},{"key":"Office Chair","name":"Office Chair","originalName":"Office Chair","color":"#87BCEC","defaultColor":true,"enabled":true,"hidden":true,"isOther