INSERT INTO public.query VALUES ('\x32be31854529590523bd1bd282e233716a271830c8d3060c17a6855b0849b3f6', 39, '{"constraints":{"max-results":10000,"max-results-bare-rows":2000},"lib/type":"mbql/query","lib/metadata":null,"stages":[{"lib/type":"mbql.stage/native","native":"SELECT\n  `periode_bulanan`,\n  `source`.`is_slow_moving` AS `is_slow_moving`,\n  `source`.`count` AS `count`,\n  `source`.`count` AS `Jumlah Produk`\nFROM\n  (\n    SELECT\n\t  `periode_bulanan`,\n      FLOOR(\n        (\n          `kba_gold`.`gold_slow_moving`.`is_slow_moving` / 0.125\n        )\n      ) * 0.125 AS `is_slow_moving`,\n      COUNT(*) AS `count`\n    FROM\n      `kba_gold`.`gold_slow_moving`\n    GROUP BY\n\t  `periode_bulanan`,\n      FLOOR(\n        (\n          `kba_gold`.`gold_slow_moving`.`is_slow_moving` / 0.125\n        )\n      ) * 0.125\n    ORDER BY\n      FLOOR(\n        (\n          `kba_gold`.`gold_slow_moving`.`is_slow_moving` / 0.125\n        )\n      ) * 0.125 ASC\n  ) AS `source`\nWHERE `periode_bulanan` = \nCOALESCE(\n    [[ toStartOfMonth(toDate({{bulan}})) , ]] \n    toStartOfMonth(now())\n  )","template-tags":{"bulan":{"id":"48db9bbd-7275-44f0-8540-56ef79f4ea38","type":"date","display-name":"Bulan","name":"bulan","default":"2026-03-30"}}}],"middleware":{"js-int-to-string?":true,"ignore-cached-results?":false,"userland-query?":true},"cache-strategy":null,"viz-settings":{"pie.rows":[{"key":"1","name":"Slow Moving","originalName":"1","color":"#F7C41F","defaultColor":false,"enabled":true,"hidden":false,"isOther":false},{"key":"0","name":"Non Slow Moving","originalName":"0","color":"#227FD2","defaultColor":false,"enabled":true,"hidden":false,"isOther":false},{"isOther":false,"hidden":true,"enabled":false,"defaultColor":true,"color":"#509EE3","originalName":"Three-Seat Sofa","name":"Three-Seat Sofa","key":"Three-Seat Sofa"},{"key":"Office Chair","name":"Office Chair","originalName":"Office Chair","color":"#87BCEC","defaultColor":true,"enabled":true,"hidden":true,"isOther":false},{"key":"Office Lamp","name":"Office Lamp","originalName":"Office Lamp","color":"#227FD2","defaultColor":true,"enabled":true,"hidden":true,"isOther":false},{"key":"Desk Combination","name":"Desk Combination","originalName":"Desk Combination","color":"#88BF4D","defaultColor":true,"enabled":true,"hidden":true,"isOther":false},{"key":"Storage Box","name":"Storage Box","originalName":"Storage Box","color":"#A7D07C","defaultColor":true,"enabled":true,"hidden":true,"isOther":false},{"key":"Large Desk","name":"Large Desk","originalName":"Large Desk","color":"#689636","defaultColor":true,"enabled":true,"hidden":true,"isOther":false},{"key":"Cabinet with Doors","name":"Cabinet with Doors","originalName":"Cabinet with Doors","color":"#A989C5","defaultColor":true,"enabled":true,"hidden":true,"isOther":false},{"key":"Office Chair Black","name":"Office Chair Black","originalName":"Office Chair Black","color":"#C8B4DA","defaultColor":true,"enabled":true,"hidden":true,"isOther":false},{"key":"Drawer Black","name":"Drawer Black","originalName":"Drawer Black","color":"#8A5EB0","defaultColor":true,"enabled":true,"hidden":true,"isOther":false},{"key":"Flipover","name":"Flipover","originalName":"Flipover","color":"#EF8C8C","defaultColor":true,"enabled":true,"hidden":true,"isOther":false},{"key":"Desk Stand with Screen","name":"Desk Stand with Screen","originalName":"Desk Stand with Screen","color":"#F7C4C4","defaultColor":true,"enabled":true,"hidden":true,"isOther":false},{"key":"Individual Workplace","name":"Individual Workplace","originalName":"Individual Workplace","color":"#E75454","defaultColor":true,"enabled":true,"hidden":true,"isOther":false},{"key":"Acoustic Bloc Screens","name":"Acoustic Bloc Screens","originalName":"Acoustic Bloc Screens","color":"#F9D45C","defaultColor":true,"enabled":true,"hidden":true,"isOther":false},{"key":"Drawer","name":"Drawer","originalName":"Drawer","color":"#FBE499","defaultColor":true,"enabled":true,"hidden":true,"isOther":false},{"key":"Large Meeting Table","name":"Large Meeting Table","originalName":"Large Meeting Table","color":"#F7C41F","defaultColor":true,"enabled":true,"hidden":true,"isOther":false},{"key":"Table","name":"Table","originalName":"Table","color":"#F2A86F","defaultColor":true,"enabled":true,"hidden":true,"isOther":false},{"key":"Table Top","name":"Table Top","originalName":"Table Top","color":"#F7CBA9","defaultColor":true,"enabled":true,"hidden":true,"isOther":false},{"key":"Table Leg","name":"Table Leg","originalName":"Table Leg","color":"#ED8535","defaultColor":true,"enabled":true,"hidden":true,"isOther":false},{"key":"Bolt","name":"Bolt","originalName":"Bolt","color":"#98D9D9","defaultColor":true,"enabled":true,"hidden":true,"isOther":false},{"key":"Screw","name":"Screw","originalName":"Screw","color":"#C7EAEA","defaultColor":true,"enabled":true,"hidden":true,"isOther":false},{"key":"Ply Layer","name":"Ply Layer","originalName":"Ply Layer","color":"#69C8C8","defaultColor":true,"enabled":true,"hidden":true,"isOther":false},{"key":"Wear Layer","name":"Wear Layer","originalName":"Wear Layer","color":"#7172AD","defaultColor":true,"enabled":true,"hidden":true,"isOther":false},{"key":"Ply Veneer","name":"Ply Veneer","originalName":"Ply Veneer","color":"#999AC4","defaultColor":true,"enabled":true,"hidden":true,"isOther":false},{"key":"Wood Panel","name":"Wood Panel","originalName":"Wood Panel","color":"#51528D","defaultColor":true,"enabled":true,"hidden":true,"isOther":false},{"key":"Plastic Laminate","name":"Plastic Laminate","originalName":"Plastic Laminate","color":"#509EE3","defaultColor":true,"enabled":true,"hidden":true,"isOther":false},{"key":"Drawer Case Black","name":"Drawer Case Black","originalName":"Drawer Case Black","color":"#87BCEC","defaultColor":true,"enabled":true,"hidden":true,"isOther":false}],"pie.dimension":["is_slow_moving"],"pie.show_total":false,"pie.show_legend":true,"pie.percent_visibility":"legend","pie.show_labels":false,"version":2,"pie.metric":"Jumlah Pr