INSERT INTO public.query VALUES ('\xe48ed9b0fcebbaa888e26643f6f285492dc06d6531aba3844bb27af05978c09a', 52, '{"constraints":{"max-results":10000,"max-results-bare-rows":2000},"lib/type":"mbql/query","lib/metadata":null,"stages":[{"lib/type":"mbql.stage/native","native":"SELECT\n-- `kba_gold`.`gold_budget_adherence_vendor_otd`.`budget_usage_pct` AS `budget_usage_pct`\n*\nFROM\n  `kba_gold`.`gold_budget_adherence_vendor_otd`\nWHERE `periode_bulan` <= \nCOALESCE(\n    [[ toStartOfMonth(toDate({{bulan}})) , ]] \n    toStartOfMonth(now())\n  )\n  AND (\n    SELECT count(*) \n    FROM `kba_gold`.`gold_budget_adherence_vendor_otd` \n    WHERE `periode_bulan` = \n\tCOALESCE(\n    [[ toStartOfMonth(toDate({{bulan}})) , ]] \n    toStartOfMonth(now())\n  ) \n  ) > 0\nORDER BY `periode_bulan` ASC","template-tags":{"bulan":{"id":"63ec009d-9950-498c-bfd5-b69b769aaccf","type":"date","display-name":"Bulan","name":"bulan","default":"2026-01-02"}}}],"middleware":{"js-int-to-string?":true,"ignore-cached-results?":false,"userland-query?":true},"cache-strategy":null,"viz-settings":{"gauge.segments":[{"min":0,"max":90,"color":"#689735","label":"Aman"},{"min":90,"max":95,"color":"#E8B921","label":"Beresiko"},{"min":95,"max":100,"color":"#E3595E","label":"Melebihi Batas"}],"table.pivot_column":"periode_bulan","table.cell_column":"total_pengeluaran_po","scalar.field":"budget_usage_pct","scalar.comparisons":[{"id":"e90f3a91-ecfe-5326-a698-20a3c7cac6b3","type":"staticNumber","label":"Maximum Usage","value":90},{"id":"a63dcca3-f5fc-3e6a-7494-896bfcf8dc7f","type":"previousPeriod"}],"scalar.switch_positive_negative":true,"column_settings":{"[\"name\",\"budget_usage_pct\"]":{"suffix":"%"}}},"database":2,"parameters":[{"type":"date/single","value":"2026-03-30","id":"695f1b78","target":["variable",["template-tag","bulan"]]}]}');
INSERT INTO public.query VALUES ('\xf4fb148b1f5ca44122a417a1ad0faa2f16e03f6b9d8784073a78311d9b38aab8', 35, '{"constraints":{"max-results":10000,"max-results-bare-rows":2000},"lib/type":"mbql/query","lib/metadata":null,"stages":[{"lib/type":"mbql.stage/native","native":"SELECT\n  -- `periode_bulan` AS `periode_bulan`,\n  -- `vendor_otd_pct` AS `vendor_otd_pct`\n  *\nFROM\n  `kba_gold`.`gold_budget_adherence_vendor_otd`\n-- WHERE {{bulan}}\nWHERE `periode_bulan` <= \nCOALESCE(\n    [[ toStartOfMonth(toDate({{bulan}})) , ]] \n    toStartOfMonth(now())\n  ) \n  AND (\n    SELECT count(*) \n    FROM `kba_gold`.`gold_budget_adherence_vendor_otd` \n    WHERE `periode_bulan` = \n\tCOALESCE(\n    [[ toStartOfMonth(toDate({{bulan}})) , ]] \n    toStartOfMonth(now())\n  ) \n  ) > 0\nORDER BY `periode_bulan` ASC\n\n-- select date(now())","template-tags":{"bulan":{"name":"bulan","id":"24ad855b-b71e-4c8c-835d-45291c9163f9","type":"date","display-name":"Bulan","default":"2025-12-28"}}}],"middleware":{"js-int-to-string?":true,"ignore-cached-results?":false,"userland-query?":true},"cache-strategy":null,"viz-settings":{"table.pivot_column":"periode_bulan","table.cell_column":"vendor_otd_pct","progress.goal":90,"progress.color":"#689636","gauge.segments":[{"min":0,"max":50,"color":"#E3595E","label":"Jauh dari Target"},{"min":50,"max":90,"color":"#E8B921","label":"Hampir Tercapai"},{"min":90,"max":100,"color":"#689735","label":"Target Tercapai"}],"scalar.field":"vendor_otd_pct","scalar.comparisons":[{"id":"7dcd18ad-52db-979e-bde0-08256e452ac9","type":"staticNumber","label":"Target Vendor OTD","value":90},{"id":"bbcc1092-784c-0f5d-96e0-d282b9413c1c","type":"previousPeriod"}],"column_settings":{"[\"name\",\"vendor_otd_pct\"]":{"suffix":"%"}}},"database":2,"parameters":[{"type":"date/single","value":"2026-04-03","id":"695f1b78","target":["variable",["template-tag","bulan"]]}]}');
