INSERT INTO public.query VALUES ('\xfa0fb93218b6d1fb942ecf900c7d3c69e0b2b1baecf1348a66e6597828caf4b2', 40, '{"constraints":{"max-results":10000,"max-results-bare-rows":2000},"lib/type":"mbql/query","lib/metadata":null,"stages":[{"lib/type":"mbql.stage/native","native":"SELECT\n  -- `periode_bulan` AS `periode_bulan`,\n  -- `vendor_otd_pct` AS `vendor_otd_pct`\n  *\nFROM\n  `kba_gold`.`gold_budget_adherence_vendor_otd`\n-- WHERE {{bulan}}\nWHERE `periode_bulan` <= \nCOALESCE(\n    [[ toStartOfMonth(toDate({{bulan}})) , ]] \n    toStartOfMonth(now())\n  ) \n  AND (\n    SELECT count(*) \n    FROM `kba_gold`.`gold_budget_adherence_vendor_otd` \n    WHERE `periode_bulan` = \n\tCOALESCE(\n    [[ toStartOfMonth(toDate({{bulan}})) , ]] \n    toStartOfMonth(now())\n  ) \n  ) > 0\nORDER BY `periode_bulan` ASC\n\n-- select date(now())","template-tags":{"bulan":{"name":"bulan","id":"24ad855b-b71e-4c8c-835d-45291c9163f9","type":"date","display-name":"Bulan","default":"2025-12-28"}}}],"middleware":{"js-int-to-string?":true,"ignore-cached-results?":false,"userland-query?":true},"cache-strategy":null,"viz-settings":{"table.pivot_column":"periode_bulan","table.cell_column":"vendor_otd_pct","progress.goal":90,"progress.color":"#689636","gauge.segments":[{"min":0,"max":50,"color":"#E3595E","label":"Jauh dari Target"},{"min":50,"max":90,"color":"#E8B921","label":"Hampir Tercapai"},{"min":90,"max":100,"color":"#689735","label":"Target Tercapai"}],"scalar.field":"vendor_otd_pct","scalar.comparisons":[{"id":"7dcd18ad-52db-979e-bde0-08256e452ac9","type":"staticNumber","label":"Target Vendor OTD","value":90},{"id":"bbcc1092-784c-0f5d-96e0-d282b9413c1c","type":"previousPeriod"}],"column_settings":{"[\"name\",\"vendor_otd_pct\"]":{"suffix":"%"}}},"database":2,"parameters":[{"type":"date/single","value":null,"id":"695f1b78","target":["variable",["template-tag","bulan"]]}]}');
INSERT INTO public.query VALUES ('\xad92c0fc5c42e6166f338b969c45609e729f8a631cb154a817780ca0de44a187', 34, '{"constraints":{"max-results":10000,"max-results-bare-rows":2000},"lib/type":"mbql/query","lib/metadata":null,"stages":[{"lib/type":"mbql.stage/native","native":"SELECT\n  `kba_gold`.`gold_budget_adherence_vendor_otd`.`periode_bulan` AS `periode_bulan`,\n  `kba_gold`.`gold_budget_adherence_vendor_otd`.`total_pengeluaran_po` AS `total_pengeluaran_po`,\n  `kba_gold`.`gold_budget_adherence_vendor_otd`.`jumlah_anggaran` AS `jumlah_anggaran`\nFROM\n  `kba_gold`.`gold_budget_adherence_vendor_otd`\nWHERE `periode_bulan` = \nCOALESCE(\n    [[ toStartOfMonth(toDate({{bulan}})) , ]] \n    toStartOfMonth(now())\n  )","template-tags":{"bulan":{"type":"date","display-name":"Bulan","name":"bulan","id":"6a2c41db-cd02-47ea-9f56-c56a7422f968","required":false}}}],"middleware":{"js-int-to-string?":true,"ignore-cached-results?":false,"userland-query?":true},"cache-strategy":null,"viz-settings":{"graph.show_trendline":false,"graph.y_axis.title_text":"pengeluaran","graph.show_values":false,"graph.x_axis.axis_enabled":true,"graph.x_axis.title_text":"periode bulan","graph.y_axis.scale":"linear","graph.metrics":["total_pengeluaran_po","jumlah_anggaran"],"graph.y_axis.axis_enabled":true,"graph.label_value_formatting":"auto","column_settings":{"[\"name\",\"periode_bulan\"]":{"column_title":"Periode Bulan","date_style":"D MMMM, YYYY","date_abbreviate":false},"[\"name\",\"total_pengeluaran_po\"]":{"prefix":"$","column_title":"Total Pengeluaran PO","number_separators":", "},"[\"name\",\"jumlah_anggaran\"]":{"prefix":"$","column_title":"Alokasi Anggaran","number_separators":", "}},"series_settings":{"jumlah_anggaran":{"color":"#87BCEC"},"total_pengeluaran_po":{"display":"area"}},"graph.x_axis.scale":"timeseries","graph.dimensions":["periode_bulan"],"stackable.stack_type":null},"database":2,"parameters":[{"type":"date/single","value":"2026-03-29","id":"b3ba716","target":["variable",["templa