INSERT INTO public.query VALUES ('\x4dda515d3d795f9f64000158879deea84839d6f66d578f5f892814a2cdecb38d', 16, '{"lib/type":"mbql/query","stages":[{"lib/type":"mbql.stage/native","native":"SELECT\n  `kba_gold`.`gold_product_conversion_rate`.`periode_bulan` AS `periode_bulan`,\n  `kba_gold`.`gold_product_conversion_rate`.`id_produk` AS `id_produk`,\n  `kba_gold`.`gold_product_conversion_rate`.`nama_produk` AS `nama_produk`,\n  `kba_gold`.`gold_product_conversion_rate`.`total_qty_quotation` AS `total_qty_quotation`,\n  `kba_gold`.`gold_product_conversion_rate`.`total_nilai_quotation` AS `total_nilai_quotation`,\n  `kba_gold`.`gold_product_conversion_rate`.`total_qty_aktual` AS `total_qty_aktual`,\n  `kba_gold`.`gold_product_conversion_rate`.`total_nilai_aktual` AS `total_nilai_aktual`,\n  `kba_gold`.`gold_product_conversion_rate`.`conversion_rate_qty` AS `conversion_rate_qty`,\n  `kba_gold`.`gold_product_conversion_rate`.`conversion_rate_value` AS `conversion_rate_value`\nFROM\n  `kba_gold`.`gold_product_conversion_rate`\nLIMIT\n  1048575"}],"database":2,"middleware":{"js-int-to-string?":true,"userland-query?":true,"add-default-userland-constraints?":true}}');
INSERT INTO public.query VALUES ('\x21bf477815afdb9556675d9d9ee6525aaddfa136058bc0cbd2f3a613792dc5e0', 30, '{"constraints":{"max-results":10000,"max-results-bare-rows":2000},"lib/type":"mbql/query","lib/metadata":null,"stages":[{"lib/type":"mbql.stage/native","native":"SELECT\n  `kba_gold`.`gold_vendor`.`id_vendor` AS `id_vendor`,\n  `kba_gold`.`gold_vendor`.`nama_vendor` AS `nama_vendor`,\n  `kba_gold`.`gold_vendor`.`periode_bulan` AS `periode_bulan`,\n  `kba_gold`.`gold_vendor`.`total_pengiriman` AS `total_pengiriman`,\n  `kba_gold`.`gold_vendor`.`tepat_waktu` AS `tepat_waktu`,\n  `kba_gold`.`gold_vendor`.`terlambat` AS `terlambat`,\n  `kba_gold`.`gold_vendor`.`otd_pct` AS `otd_pct`,\n  `kba_gold`.`gold_vendor`.`avg_delay_days` AS `avg_delay_days`,\n  `kba_gold`.`gold_vendor`.`max_delay_days` AS `max_delay_days`,\n  `kba_gold`.`gold_vendor`.`internal_scheduling_gap` AS `internal_scheduling_gap`\nFROM\n  `kba_gold`.`gold_vendor`\nWHERE `periode_bulan` = \nCOALESCE(\n    [[ toStartOfMonth(toDate({{bulan}})) , ]] \n    toStartOfMonth(now())\n  )","template-tags":{"bulan":{"display-name":"Bulan","name":"bulan","id":"95bbe1ac-580d-4a03-b034-5fddaa5daba7","type":"date","default":null}}}],"middleware":{"js-int-to-string?":true,"ignore-cached-results?":false,"userland-query?":true},"cache-strategy":null,"viz-settings":{"graph.show_goal":true,"graph.show_trendline":false,"graph.y_axis.title_text":"avg OTD Rate","scatter.bubble":"total_pengiriman","graph.goal_label":"Target OTD","graph.series_order_dimension":null,"graph.goal_value":90,"graph.metrics":["otd_pct"],"graph.series_order":null,"column_settings":{"[\"name\",\"otd_pct\"]":{"number_separators":", ","suffix":"%","decimals":1},"[\"name\",\"avg_delay_days\"]":{"number_separators":", "}},"series_settings":{"avg_delay_days":{"color":"#227FD2"},"otd_pct":{"color":"#227FD2"}},"graph.x_axis.scale":"linear","graph.dimensions":["avg_delay_days"]},"database":2}');
INSERT INTO public.query VALUES ('\x8551abfb2901e3fe421088b5726894750d23eb96941f9944e9800104e3dc4daf', 49, '{"constraints":{"max-results":10000,"max-results-bare-rows":2000},"lib/type":"mbql/query","lib/metadata":null,"stages":[{"lib/type":"mbql.stage/native","native":"SELECT\n  -- `periode_bulan` AS `periode_bulan`,\n  -- `vendor_otd_pct` AS `vendor_otd_pct`\n  *\nFROM\n  `kba_gold`.`gold_budget_adherence_vendor_otd`\n-- WHERE {{bulan}}\nWHERE `periode_bulan` <= \nCOALESCE(\n    [[ toStartOfMonth(toDate({{bulan}})) , ]] \n    toStartOfMonth(now())\n  ) \n  AND (\n    SELECT count(*) \n    FROM `kba_gold`.`gold_budget_adherence_vendor_otd` \n    WHERE `periode_bulan` = \n\tCOALESCE(\n    [[ toStartOfMonth(toDate({{bulan}})) , ]] \n    toStartOfMonth(now())\n  ) \n  ) > 0\nORDER BY `periode_bulan` ASC\n\n-- select date(now())","template-tags":{"bulan":{"name":"bulan","id":"24ad855b-b71e-4c8c-835d-45291c9163f9","type":"date","display-name":"Bulan","default":"2025-12-28"}}}],"middleware":{"js-int-to-string?":true,"ignore-cached-results?":false,"userland-query?":true},"cache-strategy":null,"viz-settings":{"table.pivot_column":"periode_bulan","table.cell_column":"vendor_otd_pct","progress.goal":90,"progress.color":"#689636","gauge.segments":[{"min":0,"max":50,"color":"#E3595E","label":"Jauh dari Target"},{"min":50,"max":90,"color":"#E8B921","label":"Hampir Tercapai"},{"min":90,"max":100,"color":"#689735","label":"Target Tercapai"}],"scalar.field":"vendor_otd_pct","scalar.comparisons":[{"id":"7dcd18ad-52db-979e-bde0-08256e452ac9","type":"staticNumber","label":"Target Vendor OTD","value":90},{"id":"bbcc1092-784c-0f5d-96e0-d282b9413c1c","type":"previousPeriod"}],"column_settings":{"[\"name\",\"vendor_otd_pct\"]":{"suffix":"%"}}},"database":2,"parameters":[{"type":"date/single","value":"2026-03-30","id":"695f1b78","target":["variable",["template-tag","bulan"]]}]}');
INSERT INTO public.query VALUES ('\xc684746dbeb168c24cf14fdf912fef65ade187210613a9224adb91d32a415564', 15, '{"lib/type":"mbql/query","stages":[{"lib/type":"mbql.stage/native","native":"{{ config(materialized=''table'') }}\n\nSELECT\n    toInt32OrNull(id) AS id_line,\n    toInt32OrNull(order_id) AS id_order,\n    toInt32OrNull(product_id) AS id_produk,\n    \n    -- JANGKAR WAKTU: Menggunakan create_date agar Quotation Maret tetap di Maret\n    toDateTime64OrNull(create_date) AS tanggal_buat,\n    toStartOfMonth(toDateTime64OrNull(create_date)) AS periode_bulan,\n    \n    -- DATA NILAI\n    toFloat64OrNull(product_uom_qty) AS qty,\n    toFloat64OrNull(price_unit) AS harga_satuan,\n    toFloat64OrNull(price_subtotal) AS nilai_subtotal,\n    \n    -- STATUS: Tetap bawa semua status (draft, sent, sale, done)\n    state AS status_transaksi\n\nFROM kba_bronze.sale_order_line\nWHERE id_produk IS NOT NULL AND id_produk != ''''","template-tags":{}}],"database":2,"middleware":{"js-int-to-string?":true,"userland-query?":true,"add-default-userland-constraints?":true}}');
INSERT INTO public.query VALUES ('\x77e35a7e4da91b86366fed41eaa6dcc46583713e4bd8554154214e36db949527', 19, '{"lib/type":"mbql/query","database":2,"stages":[{"native":"SELECT\n  `kba_gold`.`gold_sales_achievement_conversion`.`periode_bulan` AS `periode_bulan`,\n  `kba_gold`.`gold_sales_achievement_conversion`.`achievement_rate` AS `achievement_rate`\nFROM\n  `kba_gold`.`gold_sales_achievement_conversion`\nWHERE `periode_bulan` = \nCOALESCE(\n    [[ toStartOfMonth(toDate({{bulan}})) , ]] \n    toStartOfMonth(now())\n  ) AND aktual_penjualan > 0","lib/type":"mbql.stage/native","template-tags":{"bulan":{"type":"date","display-name":"Bulan","name":"bulan","id":"327da3a5-0f95-4f2f-b872-594bf8bd28b3","required":false}}}],"parameters":[{"id":"327da3a5-0f95-4f2f-b872-594bf8bd28b3","type":"date/single","value":null,"target":["variable",["template-tag","bulan"]]}],"middleware":{"js-int-to-string?":true,"userland-query?":true,"add-default-userland-constraints?":true}}');
INSERT INTO public.query VALUES ('\x91efdc31ee63a68cd7ffb0d4b76a4062fbc3c14eb44a81d6b44c1a4ece74a3ba', 54, '{"constraints":{"max-results":10000,"max-results-bare-rows":2000},"lib/type":"mbql/query","lib/metadata":null,"stages":[{"lib/type":"mbql.stage/native","native":"SELECT\n  `periode_bulanan`,\n  `source`.`is_slow_moving` AS `is_slow_moving`,\n  `source`.`count` AS `count`,\n  `source`.`count` AS `Jumlah Produk`\nFROM\n  (\n    SELECT\n\t  `periode_bulanan`,\n      FLOOR(\n        (\n          `kba_gold`.`gold_slow_moving`.`is_slow_moving` / 0.125\n        )\n      ) * 0.125 AS `is_slow_moving`,\n      COUNT(*) AS `count`\n    FROM\n      `kba_gold`.`gold_slow_moving`\n    GROUP BY\n\t  `periode_bulanan`,\n      FLOOR(\n        (\n          `kba_gold`.`gold_slow_moving`.`is_slow_moving` / 0.125\n        )\n      ) * 0.125\n    ORDER BY\n      FLOOR(\n        (\n          `kba_gold`.`gold_slow_moving`.`is_slow_moving` / 0.125\n        )\n      ) * 0.125 ASC\n  ) AS `source`\nWHERE `periode_bulanan` = \nCOALESCE(\n    [[ toStartOfMonth(toDate({{bulan}})) , ]] \n    toStartOfMonth(now())\n  )","template-tags":{"bulan":{"id":"48db9bbd-7275-44f0-8540-56ef79f4ea38","type":"date","display-name":"Bulan","name":"bulan","default":"2026-03-30"}}}],"middleware":{"js-int-to-string?":true,"ignore-cached-results?":false,"userland-query?":true},"cache-strategy":null,"viz-settings":{"pie.rows":[{"key":"1","name":"Slow Moving","originalName":"1","color":"#F7C41F","defaultColor":false,"enabled":true,"hidden":false,"isOther":false},{"key":"0","name":"Non Slow Moving","originalName":"0","color":"#227FD2","defaultColor":false,"enabled":true,"hidden":false,"isOther":false},{"isOther":false,"hidden":true,"enabled":false,"defaultColor":true,"color":"#509EE3","originalName":"Three-Seat Sofa","name":"Three-Seat Sofa","key":"Three-Seat Sofa"},{"key":"Office Chair","name":"Office Chair","originalName":"Office Chair","color":"#87BCEC","defaultColor":true,"enabled":true,"hidden":true,"isOther