INSERT INTO public.query VALUES ('\x03082a3a3007349e5bb5fcb066297bb3e4800798031a450613c4c149df2ca767', 26, '{"constraints":{"max-results":10000,"max-results-bare-rows":2000},"lib/type":"mbql/query","lib/metadata":null,"stages":[{"native":"SELECT\n  `kba_gold`.`gold_vendor`.`periode_bulan` AS `periode_bulan`,\n  `kba_gold`.`gold_vendor`.`id_vendor` AS `id_vendor`,\n  `kba_gold`.`gold_vendor`.`nama_vendor` AS `nama_vendor`,\n  `kba_gold`.`gold_vendor`.`total_pengiriman` AS `total_pengiriman`,\n  `kba_gold`.`gold_vendor`.`tepat_waktu` AS `tepat_waktu`,\n  `kba_gold`.`gold_vendor`.`otd_pct` AS `otd_pct`\nFROM\n  `kba_gold`.`gold_vendor`\nWHERE `periode_bulan` = \nCOALESCE(\n    [[ toStartOfMonth(toDate({{bulan}})) , ]] \n    toStartOfMonth(now())\n  )\norder by otd_pct desc","lib/type":"mbql.stage/native","template-tags":{"bulan":{"display-name":"Bulan","id":"fd5402b5-cb4a-4a5f-9f24-2ed362ee20f3","type":"date","name":"bulan","default":"2026-04-02"}}}],"middleware":{"js-int-to-string?":true,"ignore-cached-results?":false,"userland-query?":true},"cache-strategy":null,"viz-settings":{"graph.y_axis.title_text":"Rata-rata OTD Rate (%)","graph.show_values":true,"graph.x_axis.title_text":"Nama Vendor","graph.label_value_frequency":"all","graph.metrics":["otd_pct"],"graph.label_value_formatting":"full","column_settings":{"[\"name\",\"otd_pct\"]":{"suffix":"%","number_separators":", "}},"series_settings":{"avg":{"color":"#227FD2"},"otd_pct":{"color":"#227FD2"}},"graph.x_axis.scale":"ordinal","graph.dimensions":["nama_vendor"]},"database":2,"parameters":[{"type":"date/single","value":"2026-01-14","id":"695f1b78","target":["variable",["template-tag","bulan"]]}]}');
INSERT INTO public.query VALUES ('\x5a8f13387ad3e0b4edce8da36bed3d971e313d89c27c6f559ccc9360954b1190', 16, '{"constraints":{"max-results":10000,"max-results-bare-rows":2000},"lib/type":"mbql/query","lib/metadata":null,"stages":[{"lib/type":"mbql.stage/native","native":"SELECT\n  `kba_gold`.`gold_slow_moving`.`periode_bulanan` AS `Periode Bulan`,\n  `kba_gold`.`gold_slow_moving`.`id_produk` AS `ID Produk`,\n  `kba_gold`.`gold_slow_moving`.`nama_produk` AS `Nama Produk`,\n  `kba_gold`.`gold_slow_moving`.`nilai_stok` AS `Nilai Stok`,\n  `kba_gold`.`gold_slow_moving`.`demand_segment` AS `demand_segment`,\n  `kba_gold`.`gold_slow_moving`.`is_slow_moving` AS `is_slow_moving`,\n  `kba_gold`.`gold_slow_moving`.`slow_moving_reason` AS `slow_moving_reason`\nFROM\n  `kba_gold`.`gold_slow_moving`\nWHERE `periode_bulanan` = \nCOALESCE(\n    [[ toStartOfMonth(toDate({{bulan}})) , ]] \n    toStartOfMonth(now())\n  ) AND `is_slow_moving` = 1\nORDER BY nilai_stok desc","template-tags":{"bulan":{"name":"bulan","id":"1fd9c625-2306-44ff-8e1d-3e60000472f0","display-name":"Bulan","type":"date","default":"2026-04-02"}}}],"middleware":{"js-int-to-string?":true,"ignore-cached-results?":false,"userland-query?":true},"cache-strategy":null,"viz-settings":{"graph.show_values":true,"table.cell_column":"id_produk","graph.series_order_dimension":null,"graph.metrics":["Nilai Stok"],"graph.label_value_formatting":"compact","graph.series_order":null,"table.pivot_column":"periode_bulanan","column_settings":{"[\"name\",\"Nilai Stok\"]":{"number_separators":", ","prefix":"$"}},"series_settings":{"Nilai Stok":{"color":"#227FD2"}},"graph.dimensions":["Nama Produk"]},"database":2,"parameters":[{"type":"date/single","value":"2026-01-14","id":"695f1b78","target":["variable",["template-tag","bulan"]]}]}');
INSERT INTO public.query VALUES ('\x4561844fc2b1a9732b865cd189b71c8d36daa18fbdc1760981a1c0f29bc3553f', 39, '{"constraints":{"max-results":10000,"max-results-bare-rows":2000},"lib/type":"mbql/query","lib/metadata":null,"stages":[{"native":"SELECT\n  `periode_bulanan`,\n  SUM(CASE WHEN is_slow_moving = 1 THEN nilai_stok ELSE 0 END) AS total_stok_slow_moving,\n  SUM(nilai_stok) AS total_seluruh_stok,\n  SUM(CASE WHEN is_slow_moving = 1 THEN nilai_stok ELSE 0 END) * 100 / SUM(nilai_stok) AS rasio_slow_moving\nFROM\n  `kba_gold`.`gold_slow_moving`\nWHERE `periode_bulanan` <= \nCOALESCE(\n    [[ toStartOfMonth(toDate({{bulan}})) , ]] \n    toStartOfMonth(now())\n  )\nGROUP BY `periode_bulanan`","lib/type":"mbql.stage/native","template-tags":{"bulan":{"display-name":"Bulan","name":"bulan","id":"c27cea3d-ca3b-40f7-8533-8182000603b8","type":"date","default":null}}}],"middleware":{"js-int-to-string?":true,"ignore-cached-results?":false,"userland-query?":true},"cache-strategy":null,"viz-settings":{"scalar.field":"rasio_slow_moving","scalar.segments":[{"min":0,"max":24,"color":"#689735","label":"Aman"},{"min":25,"max":59,"color":"#E8B921","label":"Waspada"},{"min":60,"max":100,"color":"#E3595E","label":"Kritis"}],"column_settings":{"[\"name\",\"rasio_slow_moving\"]":{"suffix":"%"}}},"database":2,"parameters":[{"type":"date/single","value":"2026-03-31","id":"695f1b78","target":["variable",["template-tag","bulan"]]}]}');
INSERT INTO public.query VALUES ('\x4681fd574e105ccbf555a42943baac8ec3dfb98bbc35192f15d26128ff419d63', 41, '{"constraints":{"max-results":10000,"max-results-bare-rows":2000},"lib/type":"mbql/query","lib/metadata":null,"stages":[{"lib/type":"mbql.stage/native","native":"SELECT\n  `periode_bulanan`,\n  `source`.`is_slow_moving` AS `is_slow_moving`,\n  `source`.`count` AS `count`,\n  `source`.`count` AS `Jumlah Produk`\nFROM\n  (\n    SELECT\n\t  `periode_bulanan`,\n      FLOOR(\n        (\n          `kba_gold`.`gold_slow_moving`.`is_slow_moving` / 0.125\n        )\n      ) * 0.125 AS `is_slow_moving`,\n      COUNT(*) AS `count`\n    FROM\n      `kba_gold`.`gold_slow_moving`\n    GROUP BY\n\t  `periode_bulanan`,\n      FLOOR(\n        (\n          `kba_gold`.`gold_slow_moving`.`is_slow_moving` / 0.125\n        )\n      ) * 0.125\n    ORDER BY\n      FLOOR(\n        (\n          `kba_gold`.`gold_slow_moving`.`is_slow_moving` / 0.125\n        )\n      ) * 0.125 ASC\n  ) AS `source`\nWHERE `periode_bulanan` = \nCOALESCE(\n    [[ toStartOfMonth(toDate({{bulan}})) , ]] \n    toStartOfMonth(now())\n  )","template-tags":{"bulan":{"id":"48db9bbd-7275-44f0-8540-56ef79f4ea38","type":"date","display-name":"Bulan","name":"bulan","default":"2026-03-30"}}}],"middleware":{"js-int-to-string?":true,"ignore-cached-results?":false,"userland-query?":true},"cache-strategy":null,"viz-settings":{"pie.rows":[{"key":"1","name":"Slow Moving","originalName":"1","color":"#F7C41F","defaultColor":false,"enabled":true,"hidden":false,"isOther":false},{"key":"0","name":"Non Slow Moving","originalName":"0","color":"#227FD2","defaultColor":false,"enabled":true,"hidden":false,"isOther":false},{"isOther":false,"hidden":true,"enabled":false,"defaultColor":true,"color":"#509EE3","originalName":"Three-Seat Sofa","name":"Three-Seat Sofa","key":"Three-Seat Sofa"},{"key":"Office Chair","name":"Office Chair","originalName":"Office Chair","color":"#87BCEC","defaultColor":true,"enabled":true,"hidden":true,"isOther