INSERT INTO public.query VALUES ('\xc303c45f41928a35f518021b0640dc6be21667bf88f77c23cd019f61164f652a', 45, '{"constraints":{"max-results":10000,"max-results-bare-rows":2000},"lib/type":"mbql/query","lib/metadata":null,"stages":[{"lib/type":"mbql.stage/native","native":"SELECT\n  -- `periode_bulan` AS `periode_bulan`,\n  -- `vendor_otd_pct` AS `vendor_otd_pct`\n  *\nFROM\n  `kba_gold`.`gold_budget_adherence_vendor_otd`\n-- WHERE {{bulan}}\nWHERE `periode_bulan` <= \nCOALESCE(\n    [[ toStartOfMonth(toDate({{bulan}})) , ]] \n    toStartOfMonth(now())\n  ) \n  AND (\n    SELECT count(*) \n    FROM `kba_gold`.`gold_budget_adherence_vendor_otd` \n    WHERE `periode_bulan` = \n\tCOALESCE(\n    [[ toStartOfMonth(toDate({{bulan}})) , ]] \n    toStartOfMonth(now())\n  ) \n  ) > 0\nORDER BY `periode_bulan` ASC\n\n-- select date(now())","template-tags":{"bulan":{"name":"bulan","id":"24ad855b-b71e-4c8c-835d-45291c9163f9","type":"date","display-name":"Bulan","default":"2025-12-28"}}}],"middleware":{"js-int-to-string?":true,"ignore-cached-results?":false,"userland-query?":true},"cache-strategy":null,"viz-settings":{"table.pivot_column":"periode_bulan","table.cell_column":"vendor_otd_pct","progress.goal":90,"progress.color":"#689636","gauge.segments":[{"min":0,"max":50,"color":"#E3595E","label":"Jauh dari Target"},{"min":50,"max":90,"color":"#E8B921","label":"Hampir Tercapai"},{"min":90,"max":100,"color":"#689735","label":"Target Tercapai"}],"scalar.field":"vendor_otd_pct","scalar.comparisons":[{"id":"7dcd18ad-52db-979e-bde0-08256e452ac9","type":"staticNumber","label":"Target Vendor OTD","value":90},{"id":"bbcc1092-784c-0f5d-96e0-d282b9413c1c","type":"previousPeriod"}],"column_settings":{"[\"name\",\"vendor_otd_pct\"]":{"suffix":"%"}}},"database":2,"parameters":[{"type":"date/single","value":"2026-03-31","id":"695f1b78","target":["variable",["template-tag","bulan"]]}]}');
INSERT INTO public.query VALUES ('\x1a3f65669e11b3f6a2d35252e2fb8b5a092c4ba5745c25c1a428e99e7300d2a9', 23, '{"lib/type":"mbql/query","stages":[{"lib/type":"mbql.stage/native","native":"SELECT\n  `kba_gold`.`gold_vendor`.`id_vendor` AS `id_vendor`,\n  `kba_gold`.`gold_vendor`.`nama_vendor` AS `nama_vendor`,\n  `kba_gold`.`gold_vendor`.`periode_bulan` AS `periode_bulan`,\n  `kba_gold`.`gold_vendor`.`total_pengiriman` AS `total_pengiriman`,\n  `kba_gold`.`gold_vendor`.`tepat_waktu` AS `tepat_waktu`,\n  `kba_gold`.`gold_vendor`.`terlambat` AS `terlambat`,\n  `kba_gold`.`gold_vendor`.`otd_pct` AS `otd_pct`,\n  `kba_gold`.`gold_vendor`.`avg_delay_days` AS `avg_delay_days`,\n  `kba_gold`.`gold_vendor`.`max_delay_days` AS `max_delay_days`,\n  `kba_gold`.`gold_vendor`.`internal_scheduling_gap` AS `internal_scheduling_gap`\nFROM\n  `kba_gold`.`gold_vendor`\nWHERE `periode_bulan` = \nCOALESCE(\n    [[ toStartOfMonth(toDate({{bulan}})) , ]] \n    toStartOfMonth(now())\n  )","template-tags":{"bulan":{"id":"9c022643-3c76-44b7-bd87-21264cc77430","type":"date","name":"bulan","display-name":"Bulan"}}}],"database":2,"parameters":[{"id":"9c022643-3c76-44b7-bd87-21264cc77430","type":"date/single","value":null,"target":["variable",["template-tag","bulan"]]}],"middleware":{"js-int-to-string?":true,"userland-query?":true,"add-default-userland-constraints?":true}}');
