INSERT INTO public.query VALUES ('\x87567737b79b6b6fe987d82efd8d35b0602fa86b022f090a69e43021264f27ba', 20, '{"lib/type":"mbql/query","database":2,"stages":[{"lib/type":"mbql.stage/native","native":"SELECT\n  `periode_bulan`,\n  `nama_produk`,\n  `total_sales_sum`,\n  `total_stok_sum`,\n  `total_sales_sum` AS `Total Sales`,\n  `total_stok_sum` AS `Total Nilai Stok`\nFROM (\n  SELECT\n    `periode_bulan`,\n    `nama_produk`,\n    SUM(`total_sales`) AS `total_sales_sum`,\n    SUM(`nilai_stok`) AS `total_stok_sum`\n  FROM `kba_gold`.`gold_product_performance`\n  WHERE `periode_bulan` = COALESCE(\n    toStartOfMonth(toDate({{bulan}})), \n    toStartOfMonth(now())\n  )\n  GROUP BY \n    `periode_bulan`,\n    `nama_produk`\n) AS `source`\nORDER BY `total_sales_sum` DESC;","template-tags":{"bulan":{"id":"73e08f55-b78b-4ef9-b2fa-1075d89ca72c","type":"date","name":"bulan","display-name":"Bulan"}}}],"parameters":[{"id":"73e08f55-b78b-4ef9-b2fa-1075d89ca72c","type":"date/single","value":"2026-03-30","target":["variable",["template-tag","bulan"]]}],"middleware":{"js-int-to-string?":true,"userland-query?":true,"add-default-userland-constraints?":true}}');
