INSERT INTO public.query VALUES ('\x235fb9f63aa8b859429da5b5eef67a89e97e12856022bda3521044b5482d952a', 34, '{"lib/type":"mbql/query","database":2,"stages":[{"native":"SELECT\n  `periode_bulan`,\n  `nama_produk`,\n  `total_sales_sum`,\n  `total_stok_sum`,\n  `total_sales_sum` AS `Total Sales`,\n  `total_stok_sum` AS `Total Nilai Stok`\nFROM (\n  SELECT\n    `periode_bulan`,\n    `nama_produk`,\n    SUM(`total_sales`) AS `total_sales_sum`,\n    SUM(`nilai_stok`) AS `total_stok_sum`\n  FROM `kba_gold`.`gold_product_performance`\n  WHERE `periode_bulan` = COALESCE(\n    {% if bulan %} toStartOfMonth(toDate({{bulan}})) {% else %} NULL {% endif %}, \n    toStartOfMonth(now())\n  )\n  GROUP BY \n    `periode_bulan`,\n    `nama_produk`\n) AS `source`\nORDER BY `total_sales_sum` DESC;","lib/type":"mbql.stage/native","template-tags":{"bulan":{"id":"73e08f55-b78b-4ef9-b2fa-1075d89ca72c","type":"date","name":"bulan","display-name":"Bulan"}}}],"parameters":[{"id":"73e08f55-b78b-4ef9-b2fa-1075d89ca72c","type":"date/single","value":"2026-03-30","target":["variable",["template-tag","bulan"]]}],"middleware":{"js-int-to-string?":true,"userland-query?":true,"add-default-userland-constraints?":true}}');
