INSERT INTO public.query VALUES ('\x43396299d5d8f6d07e89294c9e41936be3b044efa77091d6c4faf3141461b465', 23, '{"constraints":{"max-results":10000,"max-results-bare-rows":2000},"lib/type":"mbql/query","lib/metadata":null,"stages":[{"lib/type":"mbql.stage/native","native":"SELECT\n  -- `kba_gold`.`gold_sales_achievement_conversion`.`periode_bulan` AS `periode_bulan`,\n  -- `kba_gold`.`gold_sales_achievement_conversion`.`achievement_rate` AS `achievement_rate`\n  *\nFROM\n  `kba_gold`.`gold_sales_achievement_conversion`\nWHERE `periode_bulan` <= \nCOALESCE(\n    [[ toStartOfMonth(toDate({{bulan}})) , ]] \n    toStartOfMonth(now())\n  )\nORDER BY `periode_bulan` ASC","template-tags":{"bulan":{"display-name":"Bulan","type":"date","name":"bulan","id":"854961b7-4308-4671-9734-0569ba410d9e","default":null}}}],"middleware":{"js-int-to-string?":true,"ignore-cached-results?":false,"userland-query?":true},"cache-strategy":null,"viz-settings":{"progress.goal":100,"progress.color":"#689636","scalar.comparisons":[{"id":"cf85ad35-41ce-9ab7-85ef-9a43f7c84e28","type":"staticNumber","label":"Target Achievement","value":100},{"id":"bfdb6456-28a7-b6d3-b747-d34a1c693d9a","type":"previousValue"}],"scalar.switch_positive_negative":false,"scalar.compact_primary_number":true,"scalar.field":"achievement_rate","column_settings":{"[\"name\",\"achievement_rate\"]":{"suffix":"%","number_separators":", "}}},"database":2,"parameters":[{"type":"date/single","value":"2026-03-29","id":"a0d3ccfe","target":["variable",["template-tag","bulan"]]}]}');
INSERT INTO public.query VALUES ('\x1811b063a60bc73e9e98baac8dce94a0a11c27f41e5727e9cc85c064014f4292', 17, '{"lib/type":"mbql/query","stages":[{"lib/type":"mbql.stage/native","native":"SELECT\n  `kba_gold`.`gold_product_conversion_rate`.`periode_bulan` AS `periode_bulan`,\n  `kba_gold`.`gold_product_conversion_rate`.`id_produk` AS `id_produk`,\n  `kba_gold`.`gold_product_conversion_rate`.`nama_produk` AS `nama_produk`,\n  `kba_gold`.`gold_product_conversion_rate`.`total_qty_quotation` AS `total_qty_quotation`,\n  `kba_gold`.`gold_product_conversion_rate`.`total_qty_aktual` AS `total_qty_aktual`,\n  `kba_gold`.`gold_product_conversion_rate`.`conversion_rate_qty` AS `conversion_rate_qty`,\n  `kba_gold`.`gold_product_conversion_rate`.`conversion_rate_value` AS `conversion_rate_value`\nFROM\n  `kba_gold`.`gold_product_conversion_rate`\n","template-tags":{}}],"database":2,"middleware":{"js-int-to-string?":true,"userland-query?":true,"add-default-userland-constraints?":true}}');
INSERT INTO public.query VALUES ('\xb2b94de5ff2c4cc0e789abd8ab11631da504c2e3dbf3017b8b72fa800358dadc', 23, '{"lib/type":"mbql/query","database":2,"stages":[{"lib/type":"mbql.stage/native","native":"SELECT\n  `source`.`nama_produk` AS `nama_produk`,\n  `source`.`sum` AS `sum`,\n  `source`.`sum_2` AS `sum_2`,\n  `source`.`sum` AS `Total Sales`,\n  `source`.`sum_2` AS `Total Nilai Stok`\nFROM\n  (\n    SELECT\n      `kba_gold`.`gold_product_performance`.`nama_produk` AS `nama_produk`,\n      SUM(\n        `kba_gold`.`gold_product_performance`.`total_sales`\n      ) AS `sum`,\n      SUM(\n        `kba_gold`.`gold_product_performance`.`nilai_stok`\n      ) AS `sum_2`\n    FROM\n      `kba_gold`.`gold_product_performance`\n    GROUP BY\n      `kba_gold`.`gold_product_performance`.`nama_produk`\n    ORDER BY\n      `kba_gold`.`gold_product_performance`.`nama_produk` ASC\n  ) AS `source`\nORDER BY\n  `source`.`sum` DESC\nWHERE `periode_bulan` = \nCOALESCE(\n    [[ toStartOfMonth(toDate({{bulan}})) , ]] \n    toStartOfMonth(now())\n  ) \n","template-tags":{"bulan":{"id":"56fdee90-30a6-4d7e-a7bd-dce27f99675c","type":"text","name":"bulan","display-name":"Bulan"}}}],"parameters":[{"id":"56fdee90-30a6-4d7e-a7bd-dce27f99675c","type":"string/=","value":null,"target":["variable",["template-tag","bulan"]]}],"middleware":{"js-int-to-string?":true,"userland-query?":true,"add-default-userland-constraints?":true}}');
