INSERT INTO public.query VALUES ('\xfca1361b281a9d5917c913f621c1770f29ab9d39d960a935c68c34d93dbecffe', 91, '{"constraints":{"max-results":10000,"max-results-bare-rows":2000},"lib/type":"mbql/query","lib/metadata":null,"stages":[{"lib/type":"mbql.stage/native","native":"SELECT\n  -- `kba_gold`.`gold_sales_achievement_conversion`.`periode_bulan` AS `periode_bulan`,\n  -- `kba_gold`.`gold_sales_achievement_conversion`.`achievement_rate` AS `achievement_rate`\n  *\nFROM\n  `kba_gold`.`gold_sales_achievement_conversion`\nWHERE `periode_bulan` <= \nCOALESCE(\n    [[ toStartOfMonth(toDate({{bulan}})) , ]] \n    toStartOfMonth(now())\n  )\nORDER BY `periode_bulan` ASC","template-tags":{"bulan":{"display-name":"Bulan","type":"date","name":"bulan","id":"854961b7-4308-4671-9734-0569ba410d9e","default":null}}}],"middleware":{"js-int-to-string?":true,"ignore-cached-results?":false,"userland-query?":true},"cache-strategy":null,"viz-settings":{"progress.goal":100,"progress.color":"#689636","scalar.comparisons":[{"id":"cf85ad35-41ce-9ab7-85ef-9a43f7c84e28","type":"staticNumber","label":"Target Achievement","value":100},{"id":"bfdb6456-28a7-b6d3-b747-d34a1c693d9a","type":"previousValue"}],"scalar.switch_positive_negative":false,"scalar.compact_primary_number":true,"scalar.field":"achievement_rate","column_settings":{"[\"name\",\"achievement_rate\"]":{"suffix":"%","number_separators":", "}}},"database":2,"parameters":[{"type":"date/single","value":"2026-04-02","id":"a0d3ccfe","target":["variable",["template-tag","bulan"]]}]}');
INSERT INTO public.query VALUES ('\x46ba49311ef88908acf6a1f66ea6e85b228f89cc7150c08d1df7c1f759cad049', 13, '{"lib/type":"mbql/query","database":2,"stages":[{"lib/type":"mbql.stage/native","native":"SELECT\n`periode_bulan`,\n  `source`.`nama_produk` AS `nama_produk`,\n  `source`.`sum` AS `sum`,\n  `source`.`sum_2` AS `sum_2`,\n  `source`.`sum` AS `Total Sales`,\n  `source`.`sum_2` AS `Total Nilai Stok`\nFROM\n  (\n    SELECT\n\t`periode_bulan`,\n      `kba_gold`.`gold_product_performance`.`nama_produk` AS `nama_produk`,\n      SUM(\n        `kba_gold`.`gold_product_performance`.`total_sales`\n      ) AS `sum`,\n      SUM(\n        `kba_gold`.`gold_product_performance`.`nilai_stok`\n      ) AS `sum_2`\n    FROM\n      `kba_gold`.`gold_product_performance`\n    GROUP BY\n      `kba_gold`.`gold_product_performance`.`nama_produk`\n    ORDER BY\n      `kba_gold`.`gold_product_performance`.`nama_produk` ASC\n  ) AS `source`\nORDER BY\n  `source`.`sum` DESC\n\n","template-tags":{}}],"middleware":{"js-int-to-string?":true,"userland-query?":true,"add-default-userland-constraints?":true}}');
INSERT INTO public.query VALUES ('\xfdf52d0cf110fa7a656c0340ccea00b1415e9b68f604048d48237db57e422294', 28, '{"constraints":{"max-results":10000,"max-results-bare-rows":2000},"lib/type":"mbql/query","lib/metadata":null,"stages":[{"native":"SELECT\n  `periode_bulanan`,\n  `source`.`is_slow_moving` AS `is_slow_moving`,\n  `source`.`count` AS `count`,\n  `source`.`count` AS `Jumlah Produk`\nFROM\n  (\n    SELECT\n\t  `periode_bulanan`,\n      FLOOR(\n        (\n          `kba_gold`.`gold_slow_moving`.`is_slow_moving` / 0.125\n        )\n      ) * 0.125 AS `is_slow_moving`,\n      COUNT(*) AS `count`\n    FROM\n      `kba_gold`.`gold_slow_moving`\n    GROUP BY\n\t  `periode_bulanan`,\n      FLOOR(\n        (\n          `kba_gold`.`gold_slow_moving`.`is_slow_moving` / 0.125\n        )\n      ) * 0.125\n    ORDER BY\n      FLOOR(\n        (\n          `kba_gold`.`gold_slow_moving`.`is_slow_moving` / 0.125\n        )\n      ) * 0.125 ASC\n  ) AS `source`\nWHERE `periode_bulanan` = \nCOALESCE(\n    [[ toStartOfMonth(toDate({{bulan}})) , ]] \n    toStartOfMonth(now())\n  )","lib/type":"mbql.stage/native","template-tags":{"bulan":{"id":"48db9bbd-7275-44f0-8540-56ef79f4ea38","type":"date","display-name":"Bulan","name":"bulan","default":null}}}],"middleware":{"js-int-to-string?":true,"ignore-cached-results?":false,"userland-query?":true},"cache-strategy":null,"viz-settings":{"pie.rows":[{"key":"1","name":"Slow Moving","originalName":"1","color":"#F7C41F","defaultColor":false,"enabled":true,"hidden":false,"isOther":false},{"key":"0","name":"Non Slow Moving","originalName":"0","color":"#227FD2","defaultColor":false,"enabled":true,"hidden":false,"isOther":false},{"isOther":false,"hidden":true,"enabled":false,"defaultColor":true,"color":"#509EE3","originalName":"Three-Seat Sofa","name":"Three-Seat Sofa","key":"Three-Seat Sofa"},{"key":"Office Chair","name":"Office Chair","originalName":"Office Chair","color":"#87BCEC","defaultColor":true,"enabled":true,"hidden":true,"isOther":false}