INSERT INTO public.query VALUES ('\x6a943bcceceb3dfb59ab73574d9522594b84bb49a0bf65da25cda4eccca69fd3', 19, '{"lib/type":"mbql/query","database":2,"stages":[{"native":"SELECT\n  -- `kba_gold`.`gold_product_conversion_rate`.`periode_bulan` AS `periode_bulan`,\n  -- `kba_gold`.`gold_product_conversion_rate`.`id_produk` AS `id_produk`,\n  -- `kba_gold`.`gold_product_conversion_rate`.`nama_produk` AS `nama_produk`,\n  -- `kba_gold`.`gold_product_conversion_rate`.`total_qty_quotation` AS `total_qty_quotation`,\n  -- `kba_gold`.`gold_product_conversion_rate`.`total_qty_aktual` AS `total_qty_aktual`,\n  -- `kba_gold`.`gold_product_conversion_rate`.`conversion_rate_value` AS `conversion_rate_value`\n  *\nFROM\n  `kba_gold`.`gold_product_conversion_rate`\nWHERE `periode_bulan` = \nCOALESCE(\n    [[ toStartOfMonth(toDate({{bulan}})) ,]]\n    toStartOfMonth(now())\n  )\n\n  order by `total_nilai_aktual` desc","lib/type":"mbql.stage/native","template-tags":{"bulan":{"id":"21054f1c-c129-436b-9387-0c1c60b5177f","type":"date","name":"bulan","display-name":"Bulan"}}}],"parameters":[{"id":"21054f1c-c129-436b-9387-0c1c60b5177f","type":"date/single","value":null,"target":["variable",["template-tag","bulan"]]}],"middleware":{"js-int-to-string?":true,"userland-query?":true,"add-default-userland-constraints?":true}}');
