INSERT INTO public.query VALUES ('\xaa8a410cbb570fb4e3ca1207d4c88c114ac503f06b6e4ef2dc59b3e82036a6a8', 17, '{"lib/type":"mbql/query","database":2,"stages":[{"lib/type":"mbql.stage/native","native":"SELECT\n  `periode_bulan`,\n  `nama_produk`,\n  `total_sales_sum`,\n  `total_stok_sum`,\n  `total_sales_sum` AS `Total Sales`,\n  `total_stok_sum` AS `Total Nilai Stok`\nFROM (\n  SELECT\n    `periode_bulan`,\n    `nama_produk`,\n    SUM(`total_sales`) AS `total_sales_sum`,\n    SUM(`nilai_stok`) AS `total_stok_sum`\n  FROM `kba_gold`.`gold_product_performance`\n  SELECT\n  `periode_bulan`,\n  `nama_produk`,\n  `total_sales_sum`,\n  `total_stok_sum`,\n  `total_sales_sum` AS `Total Sales`,\n  `total_stok_sum` AS `Total Nilai Stok`\nFROM (\n  SELECT\n    `periode_bulan`,\n    `nama_produk`,\n    SUM(`total_sales`) AS `total_sales_sum`,\n    SUM(`nilai_stok`) AS `total_stok_sum`\n  FROM `kba_gold`.`gold_product_performance`\n WHERE `periode_bulan` = \nCOALESCE(\n    [[ toStartOfMonth(toDate({{bulan}}))]] \n    toStartOfMonth(now())\n  ) \n  GROUP BY \n    `periode_bulan`,\n    `nama_produk`\n) AS `source`\nORDER BY `total_sales_sum` DESC;\n  GROUP BY \n    `periode_bulan`,\n    `nama_produk`\n) AS `source`\nORDER BY `total_sales_sum` DESC;","template-tags":{"bulan":{"name":"bulan","id":"73e08f55-b78b-4ef9-b2fa-1075d89ca72c","type":"date","display-name":"Bulan"}}}],"parameters":[{"id":"73e08f55-b78b-4ef9-b2fa-1075d89ca72c","type":"date/single","value":null,"target":["variable",["template-tag","bulan"]]}],"middleware":{"js-int-to-string?":true,"userland-query?":true,"add-default-userland-constraints?":true}}');
INSERT INTO public.query VALUES ('\x57a5ae35ba3df54ec41acd04289a8def037f7a9022f9e0ee09faae5e9160aaa4', 15, '{"lib/type":"mbql/query","database":2,"stages":[{"lib/type":"mbql.stage/native","native":"SELECT\n  `periode_bulan`,\n  `source`.`nama_produk` AS `nama_produk`,\n  `source`.`sum` AS `sum`,\n  `source`.`sum_2` AS `sum_2`,\n  `source`.`sum` AS `Total Sales`,\n  `source`.`sum_2` AS `Total Nilai Stok`\nFROM\n  (\n    SELECT\n\t  `periode_bulan`,\n      `kba_gold`.`gold_product_performance`.`nama_produk` AS `nama_produk`,\n      SUM(\n        `kba_gold`.`gold_product_performance`.`total_sales`\n      ) AS `sum`,\n      SUM(\n        `kba_gold`.`gold_product_performance`.`nilai_stok`\n      ) AS `sum_2`\n    FROM\n      `kba_gold`.`gold_product_performance`\n\t  -- WHERE `periode_bulan` = COALESCE(\n  --   toStartOfMonth(toDate({{bulan}})), \n  --   toStartOfMonth(now())\n  -- )\n    GROUP BY\n\t  `periode_bulan`,\n      `kba_gold`.`gold_product_performance`.`nama_produk`\n    ORDER BY\n      `kba_gold`.`gold_product_performance`.`nama_produk` ASC\n  ) AS `source`\nORDER BY\n  `source`.`sum` DESC\n\n","template-tags":{}}],"middleware":{"js-int-to-string?":true,"userland-query?":true,"add-default-userland-constraints?":true}}');
INSERT INTO public.query VALUES ('\x5579a83a3ec491c87dd8d89a9209303a22e7b18dbb9a55fd7abe0b096262734c', 44, '{"constraints":{"max-results":10000,"max-results-bare-rows":2000},"lib/type":"mbql/query","lib/metadata":null,"stages":[{"native":"SELECT\n  `kba_gold`.`gold_product_conversion_rate`.`periode_bulan` AS `periode_bulan`,\n  `kba_gold`.`gold_product_conversion_rate`.`id_produk` AS `id_produk`,\n  `kba_gold`.`gold_product_conversion_rate`.`nama_produk` AS `nama_produk`,\n  `kba_gold`.`gold_product_conversion_rate`.`total_qty_quotation` AS `total_qty_quotation`,\n  `kba_gold`.`gold_product_conversion_rate`.`total_qty_aktual` AS `total_qty_aktual`,\n  `kba_gold`.`gold_product_conversion_rate`.`conversion_rate_value` AS `conversion_rate_value`\nFROM\n  `kba_gold`.`gold_product_conversion_rate`\nWHERE `periode_bulan` = \nCOALESCE(\n    [[ toStartOfMonth(toDate({{bulan}})) ,]]\n    toStartOfMonth(now())\n  )\n\n  order by `conversion_rate_value` desc, `total_qty_aktual` desc","lib/type":"mbql.stage/native","template-tags":{"bulan":{"id":"21054f1c-c129-436b-9387-0c1c60b5177f","type":"date","name":"bulan","display-name":"Bulan"}}}],"middleware":{"js-int-to-string?":true,"ignore-cached-results?":false,"userland-query?":true},"cache-strategy":null,"viz-settings":{"graph.series_order":null,"graph.series_order_dimension":null,"graph.dimensions":["nama_produk"],"series_settings":{"conversion_rate_value":{"color":"#227FD2"}},"graph.show_values":true,"stackable.stack_type":null,"column_settings":{"[\"name\",\"conversion_rate_value\"]":{"number_separators":", ","suffix":"%"}},"graph.metrics":["conversion_rate_value"]},"database":2,"parameters":[{"type":"date/single","value":"2026-03-30","id":"29b9c635","target":["variable",["template-tag","bulan"]]}]}');
