INSERT INTO public.query VALUES ('\xcee70623aefe1a118ea9bce0d3001e10101902051c59251b0c1621bbe8734f0d', 18, '{"lib/type":"mbql/query","database":2,"stages":[{"lib/type":"mbql.stage/native","native":"SELECT\n  `periode_bulan` AS `Periode Bulan`,\n  `total_pengiriman` as `Total Pengiriman`,\n  `tepat_waktu` as `Pengiriman Tepat Waktu`\n  -- `vendor_otd_pct` AS `Vendor OTD Rate`\n  -- *\nFROM\n  `kba_gold`.`gold_budget_adherence_vendor_otd`\n-- WHERE {{bulan}}\nwhere `periode_bulan` <= date(now())\nORDER BY `periode_bulan` ASC\n\n-- select date(now())","template-tags":{}}],"middleware":{"js-int-to-string?":true,"userland-query?":true,"add-default-userland-constraints?":true}}');
INSERT INTO public.query VALUES ('\xd24487ba077b91119b499239c847abcd0fed7afc61919a6e81299796703905d6', 47, '{"constraints":{"max-results":10000,"max-results-bare-rows":2000},"lib/type":"mbql/query","lib/metadata":null,"stages":[{"native":"SELECT\n  `kba_gold`.`gold_vendor`.`id_vendor` AS `id_vendor`,\n  `kba_gold`.`gold_vendor`.`nama_vendor` AS `nama_vendor`,\n  `kba_gold`.`gold_vendor`.`periode_bulan` AS `periode_bulan`,\n  `kba_gold`.`gold_vendor`.`total_pengiriman` AS `total_pengiriman`,\n  `kba_gold`.`gold_vendor`.`tepat_waktu` AS `Tepat Waktu`,\n  `kba_gold`.`gold_vendor`.`terlambat` AS `Terlambat`,\n  `kba_gold`.`gold_vendor`.`otd_pct` AS `otd_pct`,\n  `kba_gold`.`gold_vendor`.`avg_delay_days` AS `avg_delay_days`,\n  `kba_gold`.`gold_vendor`.`max_delay_days` AS `max_delay_days`,\n  `kba_gold`.`gold_vendor`.`internal_scheduling_gap` AS `internal_scheduling_gap`\nFROM\n  `kba_gold`.`gold_vendor`\nWHERE `periode_bulan` = \nCOALESCE(\n    [[ toStartOfMonth(toDate({{bulan}})) , ]] \n    toStartOfMonth(now())\n  )","lib/type":"mbql.stage/native","template-tags":{"bulan":{"name":"bulan","id":"1b4747ad-1ef7-4817-add8-91e21ed4081d","type":"date","display-name":"Bulan"}}}],"middleware":{"js-int-to-string?":true,"ignore-cached-results?":false,"userland-query?":true},"cache-strategy":null,"viz-settings":{"graph.y_axis.title_text":"Jumlah","graph.show_values":true,"graph.series_order_dimension":null,"graph.x_axis.title_text":"Nama Vendor","graph.y_axis.auto_split":false,"graph.metrics":["Terlambat","Tepat Waktu"],"graph.series_order":null,"column_settings":{"[\"name\",\"periode_bulan\"]":{"date_style":"D MMMM, YYYY"}},"series_settings":{"tepat_waktu":{"color":"#227FD2"},"terlambat":{"color":"#F7C41F"},"Terlambat":{"color":"#F7C41F"},"Tepat Waktu":{"color":"#227FD2"}},"graph.x_axis.scale":"ordinal","graph.dimensions":["nama_vendor"],"stackable.stack_type":"stacked"},"database":2,"parameters":[{"type":"date/single","value":"2026-03-29","id":"47291403","target":["variable",["