INSERT INTO public.query VALUES ('\x6f759dc7cd30e68c42fb3ce4fdb287e3935ab75f9970442318aa3072603e1fa4', 43, '{"constraints":{"max-results":10000,"max-results-bare-rows":2000},"lib/type":"mbql/query","lib/metadata":null,"stages":[{"native":"SELECT\n-- `kba_gold`.`gold_budget_adherence_vendor_otd`.`budget_usage_pct` AS `budget_usage_pct`\n*\nFROM\n  `kba_gold`.`gold_budget_adherence_vendor_otd`\nWHERE `periode_bulan` <= \nCOALESCE(\n    [[ toStartOfMonth(toDate({{bulan}})) , ]] \n    toStartOfMonth(now())\n  )\n  AND (\n    SELECT count(*) \n    FROM `kba_gold`.`gold_budget_adherence_vendor_otd` \n    WHERE `periode_bulan` = \n\tCOALESCE(\n    [[ toStartOfMonth(toDate({{bulan}})) , ]] \n    toStartOfMonth(now())\n  ) \n  ) > 0\nORDER BY `periode_bulan` ASC","lib/type":"mbql.stage/native","template-tags":{"bulan":{"id":"63ec009d-9950-498c-bfd5-b69b769aaccf","type":"date","display-name":"Bulan","name":"bulan","default":null}}}],"middleware":{"js-int-to-string?":true,"ignore-cached-results?":false,"userland-query?":true},"cache-strategy":null,"viz-settings":{"gauge.segments":[{"min":0,"max":90,"color":"#689735","label":"Aman"},{"min":90,"max":95,"color":"#E8B921","label":"Beresiko"},{"min":95,"max":100,"color":"#E3595E","label":"Melebihi Batas"}],"table.pivot_column":"periode_bulan","table.cell_column":"total_pengeluaran_po","scalar.field":"budget_usage_pct","scalar.comparisons":[{"id":"e90f3a91-ecfe-5326-a698-20a3c7cac6b3","type":"staticNumber","label":"Maximum Usage","value":90},{"id":"a63dcca3-f5fc-3e6a-7494-896bfcf8dc7f","type":"previousPeriod"}],"scalar.switch_positive_negative":true,"column_settings":{"[\"name\",\"budget_usage_pct\"]":{"suffix":"%"}}},"database":2}');
INSERT INTO public.query VALUES ('\x44e1c114e4efe36b53d251e32be342b3ac86472b8f4c38d81fd73b859210c97f', 86, '{"constraints":{"max-results":10000,"max-results-bare-rows":2000},"lib/type":"mbql/query","lib/metadata":null,"stages":[{"native":"SELECT\n  `periode_bulanan`,\n  SUM(CASE WHEN is_slow_moving = 1 THEN nilai_stok ELSE 0 END) AS total_stok_slow_moving,\n  SUM(nilai_stok) AS total_seluruh_stok,\n  SUM(CASE WHEN is_slow_moving = 1 THEN nilai_stok ELSE 0 END) * 100 / SUM(nilai_stok) AS rasio_slow_moving\nFROM\n  `kba_gold`.`gold_slow_moving`\nWHERE `periode_bulanan` <= \nCOALESCE(\n    [[ toStartOfMonth(toDate({{bulan}})) , ]] \n    toStartOfMonth(now())\n  )\nGROUP BY `periode_bulanan`","lib/type":"mbql.stage/native","template-tags":{"bulan":{"display-name":"Bulan","name":"bulan","id":"c27cea3d-ca3b-40f7-8533-8182000603b8","type":"date","default":null}}}],"middleware":{"js-int-to-string?":true,"ignore-cached-results?":false,"userland-query?":true},"cache-strategy":null,"viz-settings":{"scalar.field":"rasio_slow_moving","scalar.segments":[{"min":0,"max":24,"color":"#689735","label":"Aman"},{"min":25,"max":59,"color":"#E8B921","label":"Waspada"},{"min":60,"max":100,"color":"#E3595E","label":"Kritis"}],"column_settings":{"[\"name\",\"rasio_slow_moving\"]":{"suffix":"%"}}},"database":2,"parameters":[{"type":"date/single","value":null,"id":"695f1b78","target":["variable",["template-tag","bulan"]]}]}');
