INSERT INTO public.query VALUES ('\x73de4189b34fda9340623e11e17f3f38ee03502b22f702b83d732ec1ae9d13fe', 34, '{"constraints":{"max-results":10000,"max-results-bare-rows":2000},"lib/type":"mbql/query","lib/metadata":null,"stages":[{"lib/type":"mbql.stage/native","native":"SELECT\n  `kba_gold`.`gold_slow_moving`.`periode_bulanan` AS `Periode Bulan`,\n  `kba_gold`.`gold_slow_moving`.`id_produk` AS `ID Produk`,\n  `kba_gold`.`gold_slow_moving`.`nama_produk` AS `Nama Produk`,\n  `kba_gold`.`gold_slow_moving`.`nilai_stok` AS `Nilai Stok`,\n  `kba_gold`.`gold_slow_moving`.`demand_segment` AS `demand_segment`,\n  `kba_gold`.`gold_slow_moving`.`is_slow_moving` AS `is_slow_moving`,\n  `kba_gold`.`gold_slow_moving`.`slow_moving_reason` AS `slow_moving_reason`\nFROM\n  `kba_gold`.`gold_slow_moving`\nWHERE `periode_bulanan` = \nCOALESCE(\n    [[ toStartOfMonth(toDate({{bulan}})) , ]] \n    toStartOfMonth(now())\n  ) AND `is_slow_moving` = 1\nORDER BY nilai_stok desc","template-tags":{"bulan":{"name":"bulan","id":"1fd9c625-2306-44ff-8e1d-3e60000472f0","display-name":"Bulan","type":"date","default":"2026-04-02"}}}],"middleware":{"js-int-to-string?":true,"ignore-cached-results?":false,"userland-query?":true},"cache-strategy":null,"viz-settings":{"graph.show_values":true,"table.cell_column":"id_produk","graph.series_order_dimension":null,"graph.metrics":["Nilai Stok"],"graph.label_value_formatting":"compact","graph.series_order":null,"table.pivot_column":"periode_bulanan","column_settings":{"[\"name\",\"Nilai Stok\"]":{"number_separators":", ","prefix":"$"}},"series_settings":{"Nilai Stok":{"color":"#227FD2"}},"graph.dimensions":["Nama Produk"]},"database":2,"parameters":[{"type":"date/single","value":null,"id":"695f1b78","target":["variable",["template-tag","bulan"]]}]}');
INSERT INTO public.query VALUES ('\xfc083a820e8af3f4cf8e98d87ca58cd5294445dad6219640c3136eddc72ceb5f', 77, '{"constraints":{"max-results":10000,"max-results-bare-rows":2000},"lib/type":"mbql/query","lib/metadata":null,"stages":[{"lib/type":"mbql.stage/native","native":"SELECT\n  `periode_bulanan`,\n  SUM(CASE WHEN is_slow_moving = 1 THEN nilai_stok ELSE 0 END) AS total_stok_slow_moving,\n  SUM(nilai_stok) AS total_seluruh_stok,\n  SUM(CASE WHEN is_slow_moving = 1 THEN nilai_stok ELSE 0 END) * 100 / SUM(nilai_stok) AS rasio_slow_moving\nFROM\n  `kba_gold`.`gold_slow_moving`\nWHERE `periode_bulanan` = \nCOALESCE(\n    [[ toStartOfMonth(toDate({{bulan}})) , ]] \n    toStartOfMonth(now())\n  ) AND `snapshot_type` IN ({{snapshot}})\nGROUP BY `periode_bulanan`","template-tags":{"bulan":{"id":"17b918c5-2395-47b8-a273-7014a43feaa5","type":"date","name":"bulan","display-name":"Bulan"},"snapshot":{"display-name":"Snapshot","name":"snapshot","id":"2b52cf5b-9904-4c59-9114-009887121740","default":["Historical"],"type":"text","required":true}}}],"middleware":{"js-int-to-string?":true,"ignore-cached-results?":false,"userland-query?":true},"cache-strategy":null,"viz-settings":{"scalar.field":"rasio_slow_moving","scalar.segments":[{"min":0,"max":24,"color":"#689735","label":"Aman"},{"min":25,"max":59,"color":"#E8B921","label":"Waspada"},{"min":60,"max":100,"color":"#E3595E","label":"Kritis"}],"column_settings":{"[\"name\",\"rasio_slow_moving\"]":{"suffix":"%"}},"click_behavior":{"type":"link","linkType":"dashboard","targetId":7,"parameterMapping":{"b560239f":{"source":{"type":"parameter","id":"695f1b78","name":"Bulan"},"target":{"type":"parameter","id":"b560239f"},"id":"b560239f"},"8524b4ff":{"source":{"type":"parameter","id":"695f1b78","name":"Bulan"},"target":{"type":"parameter","id":"8524b4ff"},"id":"8524b4ff"}}}},"database":2,"parameters":[{"type":"date/single","value":"2026-05-01","id":"695f1b78","target":["variable",["template-tag","bulan"]]}]}');
INSERT INTO public.query VALUES ('\xd5c1bf5e451923ed8e2321bd84742c7deec6c8ed1aa69eae5915d7c202cbecda', 60, '{"constraints":{"max-results":10000,"max-results-bare-rows":2000},"lib/type":"mbql/query","lib/metadata":null,"stages":[{"native":"SELECT\n  `kba_gold`.`gold_top_spending`.`periode_bulan` AS `periode_bulan`,\n  `kba_gold`.`gold_top_spending`.`rank_pengeluaran` AS `rank_pengeluaran`,\n  `kba_gold`.`gold_top_spending`.`id_produk` AS `id_produk`,\n  `kba_gold`.`gold_top_spending`.`nama_produk` AS `nama_produk`,\n  `kba_gold`.`gold_top_spending`.`total_pengeluaran_produk` AS `total_pengeluaran_produk`\n  \nFROM\n  `kba_gold`.`gold_top_spending`\nWHERE `periode_bulan` = \nCOALESCE(\n    [[ toStartOfMonth(toDate({{bulan}})) , ]] \n    toStartOfMonth(now())\n  )\nORDER BY\n  `kba_gold`.`gold_top_spending`.`rank_pengeluaran` ASC\nLIMIT\n  1048575","lib/type":"mbql.stage/native","template-tags":{"bulan":{"name":"bulan","display-name":"Bulan","id":"ca1860c6-3cb4-4588-a5b6-27fdce33c515","type":"date","required":false}}}],"middleware":{"js-int-to-string?":true,"ignore-cached-results?":false,"userland-query?":true},"cache-strategy":null,"viz-settings":{"graph.y_axis.title_text":"Total Pengeluaran","graph.show_values":true,"table.cell_column":"id_produk","graph.series_order_dimension":null,"graph.x_axis.title_text":"Nama Produk","graph.metrics":["total_pengeluaran_produk"],"graph.label_value_formatting":"compact","graph.series_order":null,"table.pivot_column":"periode_bulan","column_settings":{"[\"name\",\"rank_pengeluaran\"]":{"column_title":"Rank","number_separators":", "},"[\"name\",\"id_produk\"]":{"column_title":"ID Produk","number_separators":", "},"[\"name\",\"nama_produk\"]":{"column_title":"Nama Produk","text_wrapping":false},"[\"name\",\"total_pengeluaran_produk\"]":{"column_title":"Total Pengeluaran","number_separators":", ","prefix":"$"}},"series_settings":{"total_pengeluaran_produk":{"color":"#227FD2"}},"graph.dimensions":["nama_produk"]},"database":2,"paramete