INSERT INTO public.query VALUES ('\xbcc716158140871a42c577af06d0a105a99cebe0c4f8042a87738d75d33fea26', 19, '{"lib/type":"mbql/query","stages":[{"lib/type":"mbql.stage/native","native":"SELECT\n  `kba_gold`.`gold_potential_revenue`.`periode_bulan` AS `periode_bulan`,\n  `kba_gold`.`gold_potential_revenue`.`id_produk` AS `id_produk`,\n  `kba_gold`.`gold_potential_revenue`.`status_transaksi` AS `status_transaksi`,\n  `kba_gold`.`gold_potential_revenue`.`total_qty_penawaran` AS `total_qty_penawaran`,\n  `kba_gold`.`gold_potential_revenue`.`total_nilai_potensi` AS `total_nilai_potensi`,\n  `kba_gold`.`gold_potential_revenue`.`jumlah_unique_quotation` AS `jumlah_unique_quotation`\n  -- `kba_gold`.`gold_product_performance`.`nama_produk` AS `Gold Product Performance - ID Produk__nama_produk`\nFROM `kba_gold`.`gold_potential_revenue`\n  LEFT JOIN `kba_gold`.`gold_product_performance`\n  ON `kba_gold`.`gold_potential_revenue`.`id_produk` = `kba_gold`.`gold_product_performance`.`id_produk`\n-- group by periode_bulan, id_produk","template-tags":{}}],"database":2,"middleware":{"js-int-to-string?":true,"userland-query?":true,"add-default-userland-constraints?":true}}');
