INSERT INTO public.query VALUES ('\x2d4e8e834135d7e2b1fd4e8b1201eb8273dfe5da2d600c64533c2d49b61a5d79', 42, '{"constraints":{"max-results":10000,"max-results-bare-rows":2000},"lib/type":"mbql/query","lib/metadata":null,"stages":[{"native":"SELECT\n  `kba_gold`.`gold_product_conversion_rate`.`periode_bulan` AS `periode_bulan`,\n  `kba_gold`.`gold_product_conversion_rate`.`id_produk` AS `id_produk`,\n  `kba_gold`.`gold_product_conversion_rate`.`nama_produk` AS `nama_produk`,\n  `kba_gold`.`gold_product_conversion_rate`.`total_qty_quotation` AS `total_qty_quotation`,\n  `kba_gold`.`gold_product_conversion_rate`.`total_qty_aktual` AS `total_qty_aktual`,\n  `kba_gold`.`gold_product_conversion_rate`.`conversion_rate_value` AS `conversion_rate_value`\nFROM\n  `kba_gold`.`gold_product_conversion_rate`\nWHERE `periode_bulan` = \nCOALESCE(\n    [[ toStartOfMonth(toDate({{bulan}})) ,]]\n    toStartOfMonth(now())\n  )\n\n  order by `conversion_rate_value` desc, `total_qty_aktual` desc","lib/type":"mbql.stage/native","template-tags":{"bulan":{"id":"21054f1c-c129-436b-9387-0c1c60b5177f","type":"date","name":"bulan","display-name":"Bulan"}}}],"middleware":{"js-int-to-string?":true,"ignore-cached-results?":false,"userland-query?":true},"cache-strategy":null,"viz-settings":{"graph.series_order":null,"graph.series_order_dimension":null,"graph.dimensions":["nama_produk"],"series_settings":{"conversion_rate_value":{"color":"#227FD2"}},"graph.show_values":true,"stackable.stack_type":null,"column_settings":{"[\"name\",\"conversion_rate_value\"]":{"number_separators":", ","suffix":"%"}},"graph.metrics":["conversion_rate_value"]},"database":2,"parameters":[{"type":"date/single","value":"2026-04-29","id":"29b9c635","target":["variable",["template-tag","bulan"]]}]}');
INSERT INTO public.query VALUES ('\x9909cac2807a7aa3008dc985192ac723a7dc6dfd2ff6aed80d5fbcb1a1079921', 54, '{"constraints":{"max-results":10000,"max-results-bare-rows":2000},"lib/type":"mbql/query","lib/metadata":null,"stages":[{"lib/type":"mbql.stage/native","native":"SELECT\n  `periode_bulan`,\n  `source`.`nama_produk` AS `nama_produk`,\n  `source`.`sum` AS `sum`,\n  `source`.`sum_2` AS `sum_2`,\n  `source`.`sum` AS `Total Sales`,\n  `source`.`sum_2` AS `Total Nilai Stok`\nFROM\n  (\n    SELECT\n\t  `periode_bulan`,\n      `kba_gold`.`gold_product_performance`.`nama_produk` AS `nama_produk`,\n      SUM(\n        `kba_gold`.`gold_product_performance`.`total_sales`\n      ) AS `sum`,\n      SUM(\n        `kba_gold`.`gold_product_performance`.`nilai_stok`\n      ) AS `sum_2`\n    FROM\n      `kba_gold`.`gold_product_performance`\n\t  WHERE `periode_bulan` = \nCOALESCE(\n    [[ toStartOfMonth(toDate({{bulan}})) , ]] \n    toStartOfMonth(now())\n  ) \n    GROUP BY\n\t  `periode_bulan`,\n      `kba_gold`.`gold_product_performance`.`nama_produk`\n    ORDER BY\n      `kba_gold`.`gold_product_performance`.`nama_produk` ASC\n  ) AS `source`\nORDER BY\n  `source`.`sum` DESC\n\n","template-tags":{"bulan":{"id":"f4fe689f-e31c-456d-a46d-9f0c6e4d30b2","type":"date","name":"bulan","display-name":"Bulan"}}}],"middleware":{"js-int-to-string?":true,"ignore-cached-results?":false,"userland-query?":true},"cache-strategy":null,"viz-settings":{"graph.y_axis.title_text":"Nilai","graph.show_values":true,"graph.x_axis.title_text":"Nama Produk","graph.y_axis.auto_split":false,"graph.metrics":["Total Sales","Total Nilai Stok"],"graph.label_value_formatting":"compact","column_settings":{"[\"name\",\"sum\"]":{"column_title":"Total Nilai Stok"},"[\"name\",\"Total Sales\"]":{"number_separators":", ","prefix":"$"},"[\"name\",\"Total Nilai Stok\"]":{"number_separators":", ","prefix":"$"}},"series_settings":{"Total Sales":{"color":"#F7C41F","display":"bar"},"Total Nilai Stok":{"color":"#227FD2"}},"