INSERT INTO public.query VALUES ('\xeae6dceb3dc759e89addd7fde88dc75fcfd0d9cea80e1ed2aabd94f6c1c6f2b7', 36, '{"constraints":{"max-results":10000,"max-results-bare-rows":2000},"lib/type":"mbql/query","lib/metadata":null,"stages":[{"native":"SELECT\n  `periode_bulanan`,\n  SUM(CASE WHEN is_slow_moving = 1 THEN nilai_stok ELSE 0 END) AS total_stok_slow_moving,\n  SUM(nilai_stok) AS total_seluruh_stok,\n  SUM(CASE WHEN is_slow_moving = 1 THEN nilai_stok ELSE 0 END) * 100 / SUM(nilai_stok) AS rasio_slow_moving\nFROM\n  `kba_gold`.`gold_slow_moving`\nWHERE `periode_bulanan` <= \nCOALESCE(\n    [[ toStartOfMonth(toDate({{bulan}})) , ]] \n    toStartOfMonth(now())\n  )\nGROUP BY `periode_bulanan`","lib/type":"mbql.stage/native","template-tags":{"bulan":{"display-name":"Bulan","name":"bulan","id":"c27cea3d-ca3b-40f7-8533-8182000603b8","type":"date","default":null}}}],"middleware":{"js-int-to-string?":true,"ignore-cached-results?":false,"userland-query?":true},"cache-strategy":null,"viz-settings":{"scalar.field":"rasio_slow_moving","scalar.segments":[{"min":0,"max":24,"color":"#689735","label":"Aman"},{"min":25,"max":59,"color":"#E8B921","label":"Waspada"},{"min":60,"max":100,"color":"#E3595E","label":"Kritis"}],"column_settings":{"[\"name\",\"rasio_slow_moving\"]":{"suffix":"%"}},"click_behavior":{"type":"link","linkType":"dashboard","targetId":7,"parameterMapping":{}}},"database":2,"parameters":[{"type":"date/single","value":"2026-04-27","id":"695f1b78","target":["variable",["template-tag","bulan"]]}]}');
