INSERT INTO public.query VALUES ('\x5264abd7189cdc8eae84ea6464eae0217ba1197d85cb35714abb5aa38cfc31c2', 19, '{"lib/type":"mbql/query","database":2,"stages":[{"native":"SELECT\n  `kba_gold`.`gold_slow_moving`.`periode_bulanan` AS `Periode Bulan`,\n  `kba_gold`.`gold_slow_moving`.`id_produk` AS `ID Produk`,\n  `kba_gold`.`gold_slow_moving`.`nama_produk` AS `Nama Produk`,\n  `kba_gold`.`gold_slow_moving`.`nilai_stok` AS `Nilai Stok`,\n  `kba_gold`.`gold_slow_moving`.`demand_segment` AS `demand_segment`,\n  `kba_gold`.`gold_slow_moving`.`is_slow_moving` AS `is_slow_moving`,\n  `kba_gold`.`gold_slow_moving`.`slow_moving_reason` AS `slow_moving_reason`\nFROM\n  `kba_gold`.`gold_slow_moving`\nWHERE `periode_bulanan` = \nCOALESCE(\n    [[ toStartOfMonth(toDate({{bulan}})) , ]] \n    toStartOfMonth(now())\n  ) AND `is_slow_moving` = 1\n-- ORDER BY nilai_stok desc","lib/type":"mbql.stage/native","template-tags":{"bulan":{"name":"bulan","id":"bdf2f4c2-d859-4583-8964-3eda0a430770","type":"date","display-name":"Bulan"}}}],"parameters":[{"id":"bdf2f4c2-d859-4583-8964-3eda0a430770","type":"date/single","value":"2026-04-28","target":["variable",["template-tag","bulan"]]}],"middleware":{"js-int-to-string?":true,"userland-query?":true,"add-default-userland-constraints?":true}}');
INSERT INTO public.query VALUES ('\xb3395b78ba917958e25d6d28b0df75d8385bb154d04ef9a03027b31b4d0f202b', 28, '{"lib/type":"mbql/query","stages":[{"lib/type":"mbql.stage/native","native":"SELECT\n  `kba_gold`.`gold_slow_moving`.`periode_bulanan` AS `periode_bulanan`,\n  `kba_gold`.`gold_slow_moving`.`snapshot_type` AS `snapshot_type`,\n  `kba_gold`.`gold_slow_moving`.`nama_produk` AS `nama_produk`,\n  -- `kba_gold`.`gold_slow_moving`.`id_produk` AS `id_produk`,\n  `kba_gold`.`gold_slow_moving`.`nilai_stok` AS `nilai_stok`,\n  CASE  \n  When `kba_gold`.`gold_slow_moving`.`is_slow_moving` = 1 THEN \"Slow-Moving\"\n  WHEN `kba_gold`.`gold_slow_moving`.`is_slow_moving` = 0 THEN \"Non-Slow\"\n  ELSE ''Unknown''\n  END AS `is_slow_moving`,\n  `kba_gold`.`gold_slow_moving`.`demand_segment` AS `demand_segment`,\n  `kba_gold`.`gold_slow_moving`.`slow_moving_reason` AS `slow_moving_reason`\n  \nFROM\n  `kba_gold`.`gold_slow_moving`\n","template-tags":{}}],"database":2,"middleware":{"js-int-to-string?":true,"userland-query?":true,"add-default-userland-constraints?":true}}');
