INSERT INTO public.query VALUES ('\x7cbff6d5197b24501b02c48f42ff23ca31ec389d95c1e6832f20401bde538878', 75, '{"constraints":{"max-results":10000,"max-results-bare-rows":2000},"lib/type":"mbql/query","lib/metadata":null,"stages":[{"native":"SELECT\n-- `kba_gold`.`gold_budget_adherence_vendor_otd`.`budget_usage_pct` AS `budget_usage_pct`\n*\nFROM\n  `kba_gold`.`gold_budget_adherence_vendor_otd`\nWHERE `periode_bulan` <= \nCOALESCE(\n    [[ toStartOfMonth(toDate({{bulan}})) , ]] \n    toStartOfMonth(now())\n  )\n  AND (\n    SELECT count(*) \n    FROM `kba_gold`.`gold_budget_adherence_vendor_otd` \n    WHERE `periode_bulan` = \n\tCOALESCE(\n    [[ toStartOfMonth(toDate({{bulan}})) , ]] \n    toStartOfMonth(now())\n  ) \n  ) > 0\nORDER BY `periode_bulan` ASC","lib/type":"mbql.stage/native","template-tags":{"bulan":{"id":"63ec009d-9950-498c-bfd5-b69b769aaccf","type":"date","display-name":"Bulan","name":"bulan","default":null}}}],"middleware":{"js-int-to-string?":true,"ignore-cached-results?":false,"userland-query?":true},"cache-strategy":null,"viz-settings":{"gauge.segments":[{"min":0,"max":90,"color":"#689735","label":"Aman"},{"min":90,"max":95,"color":"#E8B921","label":"Beresiko"},{"min":95,"max":100,"color":"#E3595E","label":"Melebihi Batas"}],"table.pivot_column":"periode_bulan","table.cell_column":"total_pengeluaran_po","scalar.field":"budget_usage_pct","scalar.comparisons":[{"id":"e90f3a91-ecfe-5326-a698-20a3c7cac6b3","type":"staticNumber","label":"Maximum Usage","value":90},{"id":"a63dcca3-f5fc-3e6a-7494-896bfcf8dc7f","type":"previousPeriod"}],"scalar.switch_positive_negative":true,"column_settings":{"[\"name\",\"budget_usage_pct\"]":{"suffix":"%"}}},"database":2,"parameters":[{"type":"date/single","value":null,"id":"695f1b78","target":["variable",["template-tag","bulan"]]}]}');
