INSERT INTO public.query VALUES ('\x162b99a5d8c38742546d03596d4203cd454c00f70e8bc88ed9aa211a7236b6c5', 25, '{"lib/type":"mbql/query","database":2,"stages":[{"native":"SELECT\n  `kba_gold`.`gold_product_conversion_rate`.`periode_bulan` AS `periode_bulan`,\n  `kba_gold`.`gold_product_conversion_rate`.`id_produk` AS `id_produk`,\n  `kba_gold`.`gold_product_conversion_rate`.`nama_produk` AS `nama_produk`,\n  `kba_gold`.`gold_product_conversion_rate`.`demand_segment` AS `demand_segment`,\n  `kba_gold`.`gold_product_conversion_rate`.`total_qty_quotation` AS `total_qty_quotation`,\n  `kba_gold`.`gold_product_conversion_rate`.`total_qty_aktual` AS `total_qty_aktual`,\n  `kba_gold`.`gold_product_conversion_rate`.`conversion_rate_value` AS `conversion_rate_value`\nFROM\n  `kba_gold`.`gold_product_conversion_rate`\nWHERE `periode_bulan` = \nCOALESCE(\n    [[ toStartOfMonth(toDate({{bulan}})) ,]]\n    toStartOfMonth(now())\n  )\n\n  order by `conversion_rate_value` desc, `total_qty_aktual` desc","lib/type":"mbql.stage/native","template-tags":{"bulan":{"type":"date","name":"bulan","id":"21054f1c-c129-436b-9387-0c1c60b5177f","display-name":"Bulan"}}}],"parameters":[{"id":"21054f1c-c129-436b-9387-0c1c60b5177f","type":"date/single","value":null,"target":["variable",["template-tag","bulan"]]}],"middleware":{"js-int-to-string?":true,"userland-query?":true,"add-default-userland-constraints?":true}}');
