INSERT INTO public.query VALUES ('\xaedbb7d2ec71acff1fb8c4331cf3ebdb270008a29c40bb54f270c9ebe80e362b', 53, '{"constraints":{"max-results":10000,"max-results-bare-rows":2000},"lib/type":"mbql/query","lib/metadata":null,"stages":[{"lib/type":"mbql.stage/native","native":"SELECT\n  `kba_gold`.`gold_slow_moving`.`demand_segment` AS `demand_segment`,\n  `kba_gold`.`gold_slow_moving`.`snapshot_type` AS `Tipe Snapshot`,\n  COUNT(*) AS `count`\nFROM\n  `kba_gold`.`gold_slow_moving`\nWHERE `periode_bulanan` = \nCOALESCE(\n    [[ toStartOfMonth(toDate({{bulan}})) , ]] \n    toStartOfMonth(now())\n  )\n  AND `kba_gold`.`gold_slow_moving`.`is_slow_moving` IN ({{Kategori}})\n  AND `kba_gold`.`gold_slow_moving`.`snapshot_type` IN ({{snapshot}})\nGROUP BY\n  `kba_gold`.`gold_slow_moving`.`demand_segment`, `kba_gold`.`gold_slow_moving`.`snapshot_type`\nORDER BY\n  `kba_gold`.`gold_slow_moving`.`demand_segment` ASC","template-tags":{"Kategori":{"id":"98f79f2f-535b-4ef3-ae8a-aefe4741da59","default":["1"],"type":"text","display-name":"Kategori","name":"Kategori","required":true},"snapshot":{"type":"text","display-name":"Snapshot","name":"snapshot","id":"d6219d02-4581-462f-a4b0-3697a4faccc9","default":["Real-time"]},"bulan":{"id":"9da5a6e8-c939-4b1f-8506-f02624ad8c69","type":"date","name":"bulan","display-name":"Bulan"}}}],"middleware":{"js-int-to-string?":true,"ignore-cached-results?":false,"userland-query?":true},"cache-strategy":null,"viz-settings":{"map.type":"region","graph.y_axis.title_text":"Jumlah Produk","map.pin_type":"tiles","graph.show_values":true,"map.longitude_column":"is_slow_moving","map.latitude_column":"nilai_stok","graph.series_order_dimension":null,"graph.metrics":[null,"count"],"graph.label_value_formatting":"compact","graph.series_order":null,"series_settings":{"count":{"color":"#227FD2"}},"graph.x_axis.scale":"ordinal","graph.dimensions":["demand_segment"]},"database":2,"parameters":[{"type":"date/single","value":null,"id":"8524b4ff","target":["variable",["template-tag","bulan"]]},{"type":"string/=","value":["1","0"],"id":"dae647fa","target":["variable",["template-tag","Kategori"]]},{"type":"string/=","value":["Historical"],"id":"c2e57f55","target":["variable",["template-tag","snapshot"]]}]}');
INSERT INTO public.query VALUES ('\xe918309f60ade2c46a4bca5abff408ae3bdb99f9504065f2eeb5a353c6d9d647', 33, '{"constraints":{"max-results":10000,"max-results-bare-rows":2000},"lib/type":"mbql/query","lib/metadata":null,"stages":[{"lib/type":"mbql.stage/native","native":"SELECT\n  `periode_bulanan`,\n  SUM(CASE WHEN is_slow_moving = 1 THEN nilai_stok ELSE 0 END) AS total_stok_slow_moving,\n  SUM(nilai_stok) AS total_seluruh_stok,\n  SUM(CASE WHEN is_slow_moving = 1 THEN nilai_stok ELSE 0 END) * 100 / SUM(nilai_stok) AS rasio_slow_moving\nFROM\n  `kba_gold`.`gold_slow_moving`\nWHERE `periode_bulanan` <= \nCOALESCE(\n    [[ toStartOfMonth(toDate({{bulan}})) , ]] \n    toStartOfMonth(now())\n  )\nGROUP BY `periode_bulanan`","template-tags":{"bulan":{"type":"date","name":"bulan","id":"17b918c5-2395-47b8-a273-7014a43feaa5","display-name":"Bulan"}}}],"middleware":{"js-int-to-string?":true,"ignore-cached-results?":false,"userland-query?":true},"cache-strategy":null,"viz-settings":{"scalar.field":"rasio_slow_moving","scalar.segments":[{"min":0,"max":24,"color":"#689735","label":"Aman"},{"min":25,"max":59,"color":"#E8B921","label":"Waspada"},{"min":60,"max":100,"color":"#E3595E","label":"Kritis"}],"column_settings":{"[\"name\",\"rasio_slow_moving\"]":{"suffix":"%"}}},"database":2,"parameters":[{"type":"date/single","value":"2026-04-27","id":"8524b4ff","target":["variable",["template-tag","bulan"]]}]}');
