INSERT INTO public.query VALUES ('\x45bdd95687aafce9a0a62d3f606bc4e11685f8f525687299deeadbfcfdaa01ff', 138, '{"constraints":{"max-results":10000,"max-results-bare-rows":2000},"lib/type":"mbql/query","lib/metadata":null,"stages":[{"lib/type":"mbql.stage/native","native":"SELECT\n  -- `kba_gold`.`gold_sales_achievement_conversion`.`periode_bulan` AS `periode_bulan`,\n  -- `kba_gold`.`gold_sales_achievement_conversion`.`achievement_rate` AS `achievement_rate`\n  *\nFROM\n  `kba_gold`.`gold_sales_achievement_conversion`\nWHERE `periode_bulan` <= \nCOALESCE(\n    [[ toStartOfMonth(toDate({{bulan}})) , ]] \n    toStartOfMonth(now())\n  )\nORDER BY `periode_bulan` ASC","template-tags":{"bulan":{"display-name":"Bulan","type":"date","name":"bulan","id":"854961b7-4308-4671-9734-0569ba410d9e","default":null}}}],"middleware":{"js-int-to-string?":true,"ignore-cached-results?":false,"userland-query?":true},"cache-strategy":null,"viz-settings":{"progress.goal":100,"progress.color":"#689636","scalar.comparisons":[{"id":"cf85ad35-41ce-9ab7-85ef-9a43f7c84e28","type":"staticNumber","label":"Target Achievement","value":100},{"id":"bfdb6456-28a7-b6d3-b747-d34a1c693d9a","type":"previousValue"}],"scalar.switch_positive_negative":false,"scalar.compact_primary_number":true,"scalar.field":"achievement_rate","column_settings":{"[\"name\",\"achievement_rate\"]":{"suffix":"%","number_separators":", "}}},"database":2,"parameters":[{"type":"date/single","value":"2026-05-30","id":"a0d3ccfe","target":["variable",["template-tag","bulan"]]}]}');
INSERT INTO public.query VALUES ('\x75d22a2a5a7c27276cfa0e7cfe2722f774201e666191c75966021fdfc1c0f086', 25, '{"constraints":{"max-results":10000,"max-results-bare-rows":2000},"lib/type":"mbql/query","lib/metadata":null,"stages":[{"lib/type":"mbql.stage/native","native":"SELECT\n  `kba_gold`.`gold_sales_achievement_conversion`.`periode_bulan` AS `periode_bulan`,\n  `kba_gold`.`gold_sales_achievement_conversion`.`achievement_rate` AS `achievement_rate`\nFROM\n  `kba_gold`.`gold_sales_achievement_conversion`\nWHERE `periode_bulan` = \nCOALESCE(\n    [[ toStartOfMonth(toDate({{bulan}})) , ]] \n    toStartOfMonth(now())\n  ) AND aktual_penjualan > 0","template-tags":{"bulan":{"name":"bulan","required":false,"id":"327da3a5-0f95-4f2f-b872-594bf8bd28b3","type":"date","display-name":"Bulan","default":null}}}],"middleware":{"js-int-to-string?":true,"ignore-cached-results?":false,"userland-query?":true},"cache-strategy":null,"viz-settings":{"progress.goal":100,"progress.color":"#227FD2","column_settings":{"[\"name\",\"achievement_rate\"]":{"suffix":"%"}}},"database":2,"parameters":[{"type":"date/single","value":"2026-05-20","id":"a0d3ccfe","target":["variable",["template-tag","bulan"]]}]}');
INSERT INTO public.query VALUES ('\x10d4fc97ae4f7654cd63090f75553e6174d6d2b719c6b0538a412f78b3a5bddd', 65, '{"constraints":{"max-results":10000,"max-results-bare-rows":2000},"lib/type":"mbql/query","lib/metadata":null,"stages":[{"lib/type":"mbql.stage/native","native":"SELECT\n  `periode_bulanan`,\n  SUM(CASE WHEN is_slow_moving = 1 THEN nilai_stok ELSE 0 END) AS total_stok_slow_moving,\n  SUM(nilai_stok) AS total_seluruh_stok,\n  SUM(CASE WHEN is_slow_moving = 1 THEN nilai_stok ELSE 0 END) * 100 / SUM(nilai_stok) AS rasio_slow_moving\nFROM\n  `kba_gold`.`gold_slow_moving`\nWHERE `periode_bulanan` = \nCOALESCE(\n    [[ toStartOfMonth(toDate({{bulan}})) , ]] \n    toStartOfMonth(now())\n  ) AND `snapshot_type` IN ({{snapshot}})\nGROUP BY `periode_bulanan`","template-tags":{"bulan":{"id":"17b918c5-2395-47b8-a273-7014a43feaa5","type":"date","name":"bulan","display-name":"Bulan"},"snapshot":{"display-name":"Snapshot","name":"snapshot","id":"2b52cf5b-9904-4c59-9114-009887121740","default":["Historical"],"type":"text","required":true}}}],"middleware":{"js-int-to-string?":true,"ignore-cached-results?":false,"userland-query?":true},"cache-strategy":null,"viz-settings":{"scalar.field":"rasio_slow_moving","scalar.segments":[{"min":0,"max":24,"color":"#689735","label":"Aman"},{"min":25,"max":59,"color":"#E8B921","label":"Waspada"},{"min":60,"max":100,"color":"#E3595E","label":"Kritis"}],"column_settings":{"[\"name\",\"rasio_slow_moving\"]":{"suffix":"%"}},"click_behavior":{"type":"link","linkType":"dashboard","targetId":7,"parameterMapping":{"b560239f":{"source":{"type":"parameter","id":"695f1b78","name":"Bulan"},"target":{"type":"parameter","id":"b560239f"},"id":"b560239f"},"8524b4ff":{"source":{"type":"parameter","id":"695f1b78","name":"Bulan"},"target":{"type":"parameter","id":"8524b4ff"},"id":"8524b4ff"}}}},"database":2,"parameters":[{"type":"date/single","value":"2026-04-02","id":"695f1b78","target":["variable",["template-tag","bulan"]]}]}');
