INSERT INTO public.query VALUES ('\xa7421368d56c1a7e6d9e2a2db3789b633ddac02bba04c16a3d6e343ed2baedc5', 47, '{"constraints":{"max-results":10000,"max-results-bare-rows":2000},"lib/type":"mbql/query","lib/metadata":null,"stages":[{"lib/type":"mbql.stage/native","native":"SELECT\n  *\nFROM\n  `kba_gold`.`gold_product_performance`\nWHERE `periode_bulan` = \nCOALESCE(\n    [[ toStartOfMonth(toDate({{bulan}})) , ]] \n    toStartOfMonth(now())\n  ) AND total_sales > 0\nORDER BY total_sales DESC","template-tags":{"bulan":{"id":"565d581f-74e8-495c-b403-8e4c7ac3aa57","type":"date","name":"bulan","display-name":"Bulan","default":"2026-03-30"}}}],"middleware":{"js-int-to-string?":true,"ignore-cached-results?":false,"userland-query?":true},"cache-strategy":null,"viz-settings":{"graph.y_axis.title_text":"Nilai","graph.show_values":true,"graph.x_axis.title_text":"Nama Produk","graph.y_axis.auto_split":false,"graph.metrics":["total_sales"],"graph.label_value_formatting":"compact","column_settings":{"[\"name\",\"total_sales\"]":{"number_separators":", ","prefix":"$"}},"series_settings":{"Total Sales":{"color":"#227FD2"},"total_sales":{"color":"#227FD2"}},"graph.x_axis.scale":"ordinal","graph.dimensions":["nama_produk"]},"database":2,"parameters":[{"type":"date/single","value":"2026-04-27","id":"695f1b78","target":["variable",["template-tag","bulan"]]}]}');
INSERT INTO public.query VALUES ('\xdb4f9bae12ed5ddbd7ca6dc93105cf03fd119366b16c765443261c9a083494bc', 30, '{"constraints":{"max-results":10000,"max-results-bare-rows":2000},"lib/type":"mbql/query","lib/metadata":null,"stages":[{"lib/type":"mbql.stage/native","native":"SELECT\n  `kba_gold`.`gold_sales_achievement_conversion`.`periode_bulan` AS `Periode Bulan`,\n   `total_quotation` as `Total Quotation`,\n   `aktual_penjualan` as `Penjualan Aktual`,\n  `kba_gold`.`gold_sales_achievement_conversion`.`conversion_rate` AS `Conversion Rate`\nFROM\n  `kba_gold`.`gold_sales_achievement_conversion`\nWHERE `periode_bulan` <= \nCOALESCE(\n    [[ toStartOfMonth(toDate({{bulan}})) , ]] \n    toStartOfMonth(now())\n  )\nORDER BY `periode_bulan` ASC","template-tags":{"bulan":{"id":"aa7d07b1-55d4-4a56-a53e-9236e979552b","type":"date","name":"bulan","display-name":"Bulan"}}}],"middleware":{"js-int-to-string?":true,"ignore-cached-results?":false,"userland-query?":true},"cache-strategy":null,"viz-settings":{"scalar.comparisons":[{"id":"a9dd4d47-179a-6adf-2403-8e3ff0deabf0","type":"staticNumber","label":"Target Conversion","value":70},{"id":"0ece0d52-a3b5-4928-dc43-ac4737c7e883","type":"previousValue"}],"graph.y_axis.title_text":"Value","graph.show_values":true,"progress.color":"#689636","graph.x_axis.title_text":"Periode","progress.goal":70,"graph.y_axis.labels_enabled":false,"graph.metrics":["Conversion Rate"],"graph.label_value_formatting":"compact","scalar.field":"conversion_rate","column_settings":{"[\"name\",\"Total Quotation\"]":{"prefix":"$"},"[\"name\",\"Penjualan Aktual\"]":{"prefix":"$"},"[\"name\",\"Conversion Rate\"]":{"number_separators":", ","suffix":"%"}},"series_settings":{"Total Quotation":{"display":"bar","color":"#87BCEC"},"Penjualan Aktual":{"display":"bar","color":"#F9D45C"},"Conversion Rate":{"line.size":"L","line.marker_enabled":null,"color":"#227FD2"}},"graph.x_axis.scale":"timeseries","graph.dimensions":["Periode Bulan"]},"database":2,"parameters":[{"type":"d