INSERT INTO public.query VALUES ('\xfe47a60ac1b712f21233eca5d18596c3b89c8cad06072bd0804432ef63a961c4', 59, '{"constraints":{"max-results":10000,"max-results-bare-rows":2000},"lib/type":"mbql/query","lib/metadata":null,"stages":[{"lib/type":"mbql.stage/native","native":"SELECT\n  `periode_bulan`,\n  `source`.`nama_produk` AS `nama_produk`,\n  `source`.`sum` AS `sum`,\n  `source`.`sum_2` AS `sum_2`,\n  `source`.`sum` AS `Total Sales`,\n  `source`.`sum_2` AS `Total Nilai Stok`\nFROM\n  (\n    SELECT\n\t  `periode_bulan`,\n      `kba_gold`.`gold_product_performance`.`nama_produk` AS `nama_produk`,\n      SUM(\n        `kba_gold`.`gold_product_performance`.`total_sales`\n      ) AS `sum`,\n      SUM(\n        `kba_gold`.`gold_product_performance`.`nilai_stok`\n      ) AS `sum_2`\n    FROM\n      `kba_gold`.`gold_product_performance`\n\t  WHERE `periode_bulan` = \nCOALESCE(\n    [[ toStartOfMonth(toDate({{bulan}})) , ]] \n    toStartOfMonth(now())\n  ) \n    GROUP BY\n\t  `periode_bulan`,\n      `kba_gold`.`gold_product_performance`.`nama_produk`\n    ORDER BY\n      `kba_gold`.`gold_product_performance`.`nama_produk` ASC\n  ) AS `source`\nORDER BY\n  `source`.`sum` DESC\n\n","template-tags":{"bulan":{"id":"f4fe689f-e31c-456d-a46d-9f0c6e4d30b2","type":"date","name":"bulan","display-name":"Bulan"}}}],"middleware":{"js-int-to-string?":true,"ignore-cached-results?":false,"userland-query?":true},"cache-strategy":null,"viz-settings":{"graph.y_axis.title_text":"Nilai","graph.show_values":true,"graph.x_axis.title_text":"Nama Produk","graph.y_axis.auto_split":false,"graph.metrics":["Total Sales","Total Nilai Stok"],"graph.label_value_formatting":"compact","column_settings":{"[\"name\",\"sum\"]":{"column_title":"Total Nilai Stok"},"[\"name\",\"Total Sales\"]":{"number_separators":", ","prefix":"$"},"[\"name\",\"Total Nilai Stok\"]":{"number_separators":", ","prefix":"$"}},"series_settings":{"Total Sales":{"color":"#F7C41F","display":"bar"},"Total Nilai Stok":{"color":"#227FD2"}},"graph.x_axis.scale":"ordinal","graph.dimensions":["nama_produk"],"stackable.stack_type":"stacked"},"database":2,"parameters":[{"type":"date/single","value":null,"id":"a0d3ccfe","target":["variable",["template-tag","bulan"]]}]}');
INSERT INTO public.query VALUES ('\xf592c523498d881a790b31a1faff150a6af3112f4521d4855ecaa78f13f141d5', 27, '{"constraints":{"max-results":10000,"max-results-bare-rows":2000},"lib/type":"mbql/query","lib/metadata":null,"stages":[{"lib/type":"mbql.stage/native","native":"SELECT\n  -- `kba_gold`.`gold_sales_achievement_conversion`.`periode_bulan` AS `periode_bulan`,\n  -- `kba_gold`.`gold_sales_achievement_conversion`.`achievement_rate` AS `achievement_rate`\n  *\nFROM\n  `kba_gold`.`gold_sales_achievement_conversion`\nWHERE `periode_bulan` <= \nCOALESCE(\n    [[ toStartOfMonth(toDate({{bulan}})) , ]] \n    toStartOfMonth(now())\n  )\nORDER BY `periode_bulan` ASC","template-tags":{"bulan":{"display-name":"Bulan","type":"date","name":"bulan","id":"854961b7-4308-4671-9734-0569ba410d9e","default":null}}}],"middleware":{"js-int-to-string?":true,"ignore-cached-results?":false,"userland-query?":true},"cache-strategy":null,"viz-settings":{"progress.goal":100,"progress.color":"#689636","scalar.comparisons":[{"id":"cf85ad35-41ce-9ab7-85ef-9a43f7c84e28","type":"staticNumber","label":"Target Achievement","value":100},{"id":"bfdb6456-28a7-b6d3-b747-d34a1c693d9a","type":"previousValue"}],"scalar.switch_positive_negative":false,"scalar.compact_primary_number":true,"scalar.field":"achievement_rate","column_settings":{"[\"name\",\"achievement_rate\"]":{"suffix":"%","number_separators":", "}}},"database":2,"parameters":[{"type":"date/single","value":"2026-05-20","id":"a0d3ccfe","target":["variable",["template-tag","bulan"]]}]}');
INSERT INTO public.query VALUES ('\x87c84caa423df887634c0dde0041700a5d1821ef9f16665f7466ca279883901b', 32, '{"constraints":{"max-results":10000,"max-results-bare-rows":2000},"lib/type":"mbql/query","lib/metadata":null,"stages":[{"lib/type":"mbql.stage/native","native":"SELECT\n  `kba_gold`.`gold_potential_revenue`.`periode_bulan` AS `periode_bulan`,\n  `kba_gold`.`gold_potential_revenue`.`id_produk` AS `id_produk`,\n  `kba_gold`.`gold_potential_revenue`.`status_transaksi` AS `status_transaksi`,\n  `kba_gold`.`gold_potential_revenue`.`total_qty_penawaran` AS `total_qty_penawaran`,\n  `kba_gold`.`gold_potential_revenue`.`total_nilai_potensi` AS `total_nilai_potensi`,\n  `kba_gold`.`gold_potential_revenue`.`jumlah_unique_quotation` AS `jumlah_unique_quotation`,\n  `Gold Product Performance - ID Produk`.`nama_produk` AS `Gold Product Performance - ID Produk__nama_produk`\nFROM\n  `kba_gold`.`gold_potential_revenue`\n  LEFT JOIN (\n    SELECT distinct\n      `kba_gold`.`gold_product_performance`.`id_produk` AS `id_produk`,\n      `kba_gold`.`gold_product_performance`.`nama_produk` AS `nama_produk`\n    FROM\n      `kba_gold`.`gold_product_performance`\n  ) AS `Gold Product Performance - ID Produk` ON `kba_gold`.`gold_potential_revenue`.`id_produk` = `Gold Product Performance - ID Produk`.`id_produk`\n  WHERE `periode_bulan` = \nCOALESCE(\n    [[ toStartOfMonth(toDate({{bulan}})) , ]] \n    toStartOfMonth(now())\n  )\n","template-tags":{"bulan":{"id":"54fffe30-f8ed-4ea4-8789-2906ecddd410","type":"date","name":"bulan","display-name":"Bulan"}}}],"middleware":{"js-int-to-string?":true,"ignore-cached-results?":false,"userland-query?":true},"cache-strategy":null,"viz-settings":{"graph.y_axis.title_text":"Nilai Potensi","table.cell_column":"id_produk","graph.series_order_dimension":null,"graph.x_axis.title_text":"Nama Produk","graph.metrics":["total_nilai_potensi"],"graph.series_order":null,"table.pivot_column":"periode_bulan","column_settings":{"[\"name\",\"total_nilai_potensi\"]":{"number_separators":", ","prefix":"$"}},"series_settings":{"total_nilai_potensi":{"color":"#227FD2"}},"graph.dimensions":["Gold Product Performance - ID Produk__nama_produk"]},"database":2,"parameters":[{"type":"date/single","value":"2026-04-27","id":"29b9c635","target":["variable",["template-tag","bulan"]]}]}');
