INSERT INTO public.query VALUES ('\xd9cdcca1d4aa1e674f9c26950769ac58b92b3a173434289d4ce37abc8f121d22', 54, '{"constraints":{"max-results":10000,"max-results-bare-rows":2000},"lib/type":"mbql/query","lib/metadata":null,"stages":[{"lib/type":"mbql.stage/native","native":"SELECT\n  *\nFROM\n  `kba_gold`.`gold_product_performance`\nWHERE `periode_bulan` = \nCOALESCE(\n    [[ toStartOfMonth(toDate({{bulan}})) , ]] \n    toStartOfMonth(now())\n  ) AND total_sales > 0\nORDER BY total_sales DESC","template-tags":{"bulan":{"id":"565d581f-74e8-495c-b403-8e4c7ac3aa57","type":"date","name":"bulan","display-name":"Bulan","default":"2026-03-30"}}}],"middleware":{"js-int-to-string?":true,"ignore-cached-results?":false,"process-viz-settings?":false,"userland-query?":true},"cache-strategy":null,"viz-settings":{"graph.y_axis.title_text":"Nilai","graph.show_values":true,"graph.series_order_dimension":null,"graph.x_axis.title_text":"Nama Produk","graph.y_axis.auto_split":false,"graph.metrics":["total_sales"],"graph.label_value_formatting":"compact","graph.series_order":null,"column_settings":{"[\"name\",\"total_sales\"]":{"number_separators":", ","prefix":"$"}},"series_settings":{"total_sales":{"color":"#227FD2"},"Total Sales":{"color":"#227FD2"},"awaiting_more_sales":{"color":"#EF8C8C"}},"graph.x_axis.scale":"ordinal","graph.dimensions":["nama_produk","demand_segment"],"stackable.stack_type":"stacked"},"database":2,"parameters":[{"id":"565d581f-74e8-495c-b403-8e4c7ac3aa57","type":"date/single","target":["variable",["template-tag","bulan"]],"value":"2026-04-01"}]}');
INSERT INTO public.query VALUES ('\xedd3933ae6ea3f311830f74ff2a8fd7994fd9df24a6d16a48c7c2f9835cbe0b0', 92, '{"constraints":{"max-results":10000,"max-results-bare-rows":2000},"lib/type":"mbql/query","lib/metadata":null,"stages":[{"native":"SELECT\n  `periode_bulanan`,\n  `source`.`is_slow_moving` AS `is_slow_moving`,\n  `source`.`count` AS `count`,\n  `source`.`count` AS `Jumlah Produk`\nFROM\n  (\n    SELECT\n\t  `periode_bulanan`,\n      FLOOR(\n        (\n          `kba_gold`.`gold_slow_moving`.`is_slow_moving` / 0.125\n        )\n      ) * 0.125 AS `is_slow_moving`,\n      COUNT(*) AS `count`\n    FROM\n      `kba_gold`.`gold_slow_moving`\n    GROUP BY\n\t  `periode_bulanan`,\n      FLOOR(\n        (\n          `kba_gold`.`gold_slow_moving`.`is_slow_moving` / 0.125\n        )\n      ) * 0.125\n    ORDER BY\n      FLOOR(\n        (\n          `kba_gold`.`gold_slow_moving`.`is_slow_moving` / 0.125\n        )\n      ) * 0.125 ASC\n  ) AS `source`\nWHERE `periode_bulanan` = \nCOALESCE(\n    [[ toStartOfMonth(toDate({{bulan}})) , ]] \n    toStartOfMonth(now())\n  )","lib/type":"mbql.stage/native","template-tags":{"bulan":{"id":"48db9bbd-7275-44f0-8540-56ef79f4ea38","type":"date","display-name":"Bulan","name":"bulan","default":null}}}],"middleware":{"js-int-to-string?":true,"ignore-cached-results?":false,"userland-query?":true},"cache-strategy":null,"viz-settings":{"pie.rows":[{"key":"1","name":"Slow Moving","originalName":"1","color":"#F7C41F","defaultColor":false,"enabled":true,"hidden":false,"isOther":false},{"key":"0","name":"Non Slow Moving","originalName":"0","color":"#227FD2","defaultColor":false,"enabled":true,"hidden":false,"isOther":false},{"isOther":false,"hidden":true,"enabled":false,"defaultColor":true,"color":"#509EE3","originalName":"Three-Seat Sofa","name":"Three-Seat Sofa","key":"Three-Seat Sofa"},{"key":"Office Chair","name":"Office Chair","originalName":"Office Chair","color":"#87BCEC","defaultColor":true,"enabled":true,"hidden":true,"isOther":false}