INSERT INTO public.query VALUES ('\x042df4da05157e42bc06b2c75e31cc8377d10d576d967cb6f5c8c2dbb2a2f77f', 50, '{"constraints":{"max-results":10000,"max-results-bare-rows":2000},"lib/type":"mbql/query","lib/metadata":null,"stages":[{"lib/type":"mbql.stage/native","native":"SELECT\n  -- `kba_gold`.`gold_product_conversion_rate`.`periode_bulan` AS `periode_bulan`,\n  -- `kba_gold`.`gold_product_conversion_rate`.`id_produk` AS `id_produk`,\n  -- `kba_gold`.`gold_product_conversion_rate`.`nama_produk` AS `nama_produk`,\n  -- `kba_gold`.`gold_product_conversion_rate`.`total_qty_quotation` AS `total_qty_quotation`,\n  -- `kba_gold`.`gold_product_conversion_rate`.`total_qty_aktual` AS `total_qty_aktual`,\n  -- `kba_gold`.`gold_product_conversion_rate`.`conversion_rate_value` AS `conversion_rate_value`\n  *\nFROM\n  `kba_gold`.`gold_product_conversion_rate`\nWHERE `periode_bulan` = \nCOALESCE(\n    [[ toStartOfMonth(toDate({{bulan}})) ,]]\n    toStartOfMonth(now())\n  )\n\n  order by `conversion_rate_value` desc, `total_qty_aktual` desc","template-tags":{"bulan":{"name":"bulan","id":"21054f1c-c129-436b-9387-0c1c60b5177f","type":"date","display-name":"Bulan"}}}],"middleware":{"js-int-to-string?":true,"ignore-cached-results?":false,"userland-query?":true},"cache-strategy":null,"viz-settings":{"graph.y_axis.title_text":"Total Penjualan","graph.show_values":true,"graph.series_order_dimension":null,"graph.x_axis.title_text":"Nama Produk","graph.metrics":["total_nilai_aktual"],"graph.series_order":null,"column_settings":{"[\"name\",\"total_nilai_aktual\"]":{"number_separators":", ","prefix":"$"},"[\"name\",\"conversion_rate_value\"]":{"number_separators":", ","suffix":"%"}},"series_settings":{"conversion_rate_value":{"color":"#227FD2"},"total_nilai_aktual":{"color":"#227FD2"}},"graph.dimensions":["nama_produk"],"stackable.stack_type":null},"database":2,"parameters":[{"type":"date/single","value":"2026-04-27","id":"29b9c635","target":["variable",["template-tag","bulan"]]}]}');
