INSERT INTO public.query VALUES ('\x3ecf32c484178a1f33e43e78f3b5d8131f7c42b58a495841cb8ae82abd3e0369', 195, '{"constraints":{"max-results":10000,"max-results-bare-rows":2000},"lib/type":"mbql/query","lib/metadata":null,"stages":[{"lib/type":"mbql.stage/native","native":"SELECT\n  `periode_bulan`,\n  `source`.`nama_produk` AS `nama_produk`,\n  `source`.`sum` AS `sum`,\n  `source`.`sum_2` AS `sum_2`,\n  `source`.`sum` AS `Total Sales`,\n  `source`.`sum_2` AS `Total Nilai Stok`\nFROM\n  (\n    SELECT\n\t  `periode_bulan`,\n      `kba_gold`.`gold_product_performance`.`nama_produk` AS `nama_produk`,\n      SUM(\n        `kba_gold`.`gold_product_performance`.`total_sales`\n      ) AS `sum`,\n      SUM(\n        `kba_gold`.`gold_product_performance`.`nilai_stok`\n      ) AS `sum_2`\n    FROM\n      `kba_gold`.`gold_product_performance`\n\t  WHERE `periode_bulan` = \nCOALESCE(\n    [[ toStartOfMonth(toDate({{bulan}})) , ]] \n    toStartOfMonth(now())\n  ) \n    GROUP BY\n\t  `periode_bulan`,\n      `kba_gold`.`gold_product_performance`.`nama_produk`\n    ORDER BY\n      `kba_gold`.`gold_product_performance`.`nama_produk` ASC\n  ) AS `source`\nORDER BY\n  `source`.`sum` DESC\n\n","template-tags":{"bulan":{"id":"f4fe689f-e31c-456d-a46d-9f0c6e4d30b2","type":"date","name":"bulan","display-name":"Bulan"}}}],"middleware":{"js-int-to-string?":true,"ignore-cached-results?":false,"userland-query?":true},"cache-strategy":null,"viz-settings":{"graph.y_axis.title_text":"Nilai","graph.show_values":true,"graph.x_axis.title_text":"Nama Produk","graph.y_axis.auto_split":false,"graph.metrics":["Total Sales","Total Nilai Stok"],"graph.label_value_formatting":"compact","column_settings":{"[\"name\",\"sum\"]":{"column_title":"Total Nilai Stok"},"[\"name\",\"Total Sales\"]":{"number_separators":", ","prefix":"$"},"[\"name\",\"Total Nilai Stok\"]":{"number_separators":", ","prefix":"$"}},"series_settings":{"Total Sales":{"color":"#F7C41F","display":"bar"},"Total Nilai Stok":{"color":"#227FD2"}},"graph.x_axis.scale":"ordinal","graph.dimensions":["nama_produk"],"stackable.stack_type":"stacked"},"database":2,"parameters":[{"type":"date/single","value":"2026-05-30","id":"a0d3ccfe","target":["variable",["template-tag","bulan"]]}]}');
INSERT INTO public.query VALUES ('\xe50b70ea4b5b4f51f077cff22f62400bfee32dfe26c417c8dc8e0752d29b8c00', 27, '{"constraints":{"max-results":10000,"max-results-bare-rows":2000},"lib/type":"mbql/query","lib/metadata":null,"stages":[{"native":"SELECT\n  `kba_gold`.`gold_vendor`.`periode_bulan` AS `periode_bulan`,\n  `kba_gold`.`gold_vendor`.`id_vendor` AS `id_vendor`,\n  `kba_gold`.`gold_vendor`.`nama_vendor` AS `nama_vendor`,\n  `kba_gold`.`gold_vendor`.`total_pengiriman` AS `total_pengiriman`,\n  `kba_gold`.`gold_vendor`.`tepat_waktu` AS `tepat_waktu`,\n  `kba_gold`.`gold_vendor`.`otd_pct` AS `otd_pct`\nFROM\n  `kba_gold`.`gold_vendor`\nWHERE `periode_bulan` = \nCOALESCE(\n    [[ toStartOfMonth(toDate({{bulan}})) , ]] \n    toStartOfMonth(now())\n  )\norder by otd_pct desc","lib/type":"mbql.stage/native","template-tags":{"bulan":{"display-name":"Bulan","id":"fd5402b5-cb4a-4a5f-9f24-2ed362ee20f3","type":"date","name":"bulan","default":"2026-04-02"}}}],"middleware":{"js-int-to-string?":true,"ignore-cached-results?":false,"userland-query?":true},"cache-strategy":null,"viz-settings":{"graph.y_axis.title_text":"Rata-rata OTD Rate (%)","graph.show_values":true,"graph.x_axis.title_text":"Nama Vendor","graph.label_value_frequency":"all","graph.metrics":["otd_pct"],"graph.label_value_formatting":"full","column_settings":{"[\"name\",\"otd_pct\"]":{"suffix":"%","number_separators":", "}},"series_settings":{"avg":{"color":"#227FD2"},"otd_pct":{"color":"#227FD2"}},"graph.x_axis.scale":"ordinal","graph.dimensions":["nama_vendor"]},"database":2,"parameters":[{"type":"date/single","value":"2026-04-02","id":"695f1b78","target":["variable",["template-tag","bulan"]]}]}');
INSERT INTO public.query VALUES ('\x4ba94a907b2176b68c7c88ebd4c968d57b16a7f20b8800796cf5f039223a8724', 44, '{"constraints":{"max-results":10000,"max-results-bare-rows":2000},"lib/type":"mbql/query","lib/metadata":null,"stages":[{"lib/type":"mbql.stage/native","native":"SELECT\n  `periode_bulanan`,\n  SUM(CASE WHEN is_slow_moving = 1 THEN nilai_stok ELSE 0 END) AS total_stok_slow_moving,\n  SUM(nilai_stok) AS total_seluruh_stok,\n  SUM(CASE WHEN is_slow_moving = 1 THEN nilai_stok ELSE 0 END) * 100 / SUM(nilai_stok) AS rasio_slow_moving\nFROM\n  `kba_gold`.`gold_slow_moving`\nWHERE `periode_bulanan` = \nCOALESCE(\n    [[ toStartOfMonth(toDate({{bulan}})) , ]] \n    toStartOfMonth(now())\n  ) AND `snapshot_type` IN ({{snapshot}})\nGROUP BY `periode_bulanan`","template-tags":{"bulan":{"id":"17b918c5-2395-47b8-a273-7014a43feaa5","type":"date","name":"bulan","display-name":"Bulan"},"snapshot":{"display-name":"Snapshot","name":"snapshot","id":"2b52cf5b-9904-4c59-9114-009887121740","default":["Historical"],"type":"text","required":true}}}],"middleware":{"js-int-to-string?":true,"ignore-cached-results?":false,"userland-query?":true},"cache-strategy":null,"viz-settings":{"scalar.field":"rasio_slow_moving","scalar.segments":[{"min":0,"max":24,"color":"#689735","label":"Aman"},{"min":25,"max":59,"color":"#E8B921","label":"Waspada"},{"min":60,"max":100,"color":"#E3595E","label":"Kritis"}],"column_settings":{"[\"name\",\"rasio_slow_moving\"]":{"suffix":"%"}}},"database":2,"parameters":[{"type":"date/single","value":"2026-04-27","id":"8524b4ff","target":["variable",["template-tag","bulan"]]},{"type":"string/=","value":["Historical"],"id":"c2e57f55","target":["variable",["template-tag","snapshot"]]}]}');
INSERT INTO public.query VALUES ('\x53e6ab991058610f4b5b55ecf5fda4f42d18a2042f4a7ef0820ccf52702229d9', 72, '{"constraints":{"max-results":10000,"max-results-bare-rows":2000},"lib/type":"mbql/query","lib/metadata":null,"stages":[{"lib/type":"mbql.stage/native","native":"SELECT\n  -- `kba_gold`.`gold_sales_achievement_conversion`.`periode_bulan` AS `periode_bulan`,\n  -- `kba_gold`.`gold_sales_achievement_conversion`.`conversion_rate` AS `conversion_rate`\n  *\nFROM\n  `kba_gold`.`gold_sales_achievement_conversion`\nWHERE `periode_bulan` <= \nCOALESCE(\n    [[ toStartOfMonth(toDate({{bulan}})) , ]] \n    toStartOfMonth(now())\n  )\nORDER BY `periode_bulan` ASC","template-tags":{"bulan":{"id":"d1e5b910-38b6-466c-b3b0-4c34d31f346a","type":"date","name":"bulan","display-name":"Bulan"}}}],"middleware":{"js-int-to-string?":true,"ignore-cached-results?":false,"userland-query?":true},"cache-strategy":null,"viz-settings":{"progress.goal":70,"progress.color":"#689636","scalar.field":"conversion_rate","scalar.comparisons":[{"id":"a9dd4d47-179a-6adf-2403-8e3ff0deabf0","type":"staticNumber","label":"Target Conversion","value":70},{"id":"0ece0d52-a3b5-4928-dc43-ac4737c7e883","type":"previousValue"}],"column_settings":{"[\"name\",\"conversion_rate\"]":{"suffix":"%"}}},"database":2,"parameters":[{"type":"date/single","value":"2026-04-27","id":"695f1b78","target":["variable",["template-tag","bulan"]]}]}');
