INSERT INTO public.query VALUES ('\x9b17b42e4f639b2d09cee6f144051069c6687a75626b8af0daf3525fa6061784', 57, '{"lib/type":"mbql/query","database":2,"stages":[{"native":"SELECT\n  `kba_gold`.`gold_slow_moving`.`periode_bulanan` AS `Periode Bulanan`,\n  `kba_gold`.`gold_slow_moving`.`snapshot_type` AS `Snapshot Type`,\n  `kba_gold`.`gold_slow_moving`.`nama_produk` AS `Nama Produk`,\n  -- `kba_gold`.`gold_slow_moving`.`id_produk` AS `id_produk`,\n  `kba_gold`.`gold_slow_moving`.`nilai_stok` AS `Nilai Stok`,\n  CASE  \n  WHEN `kba_gold`.`gold_slow_moving`.`is_slow_moving` = 1 THEN ''Slow Moving''\n  WHEN `kba_gold`.`gold_slow_moving`.`is_slow_moving` = 0 THEN ''Non Slow Moving''\n  ELSE ''Unknown''\n  END AS `Status Slow Moving`,\n  `kba_gold`.`gold_slow_moving`.`demand_segment` AS `Demand Segment`,\n  `kba_gold`.`gold_slow_moving`.`slow_moving_reason` AS `slow_moving_reason`\n  \nFROM\n  `kba_gold`.`gold_slow_moving`\nWHERE `periode_bulanan` = \nCOALESCE(\n    [[ toStartOfMonth(toDate({{bulan}})) , ]] \n    toStartOfMonth(now())\n  ) AND `is_slow_moving` IN ({{Kategori}})\n  AND `snapshot_type` IN ({{Snapshot}})","lib/type":"mbql.stage/native","template-tags":{"bulan":{"id":"e1752801-f2fc-497e-b209-dbd3f6d3608f","display-name":"Bulan","required":true,"type":"date","name":"bulan","default":"2026-04-27"},"Kategori":{"display-name":"Kategori","default":["1"],"name":"Kategori","id":"7387fc39-351e-4b7e-b826-6498be688002","type":"text","required":true},"Snapshot":{"name":"Snapshot","id":"53e8bd26-df0f-4517-a755-f32eec51dc92","default":["Real-time"],"type":"text","display-name":"Snapshot","required":true}}}],"parameters":[{"id":"e1752801-f2fc-497e-b209-dbd3f6d3608f","type":"date/single","value":"2026-04-27","target":["variable",["template-tag","bulan"]]},{"id":"7387fc39-351e-4b7e-b826-6498be688002","type":"string/=","value":["1"],"target":["variable",["template-tag","Kategori"]]},{"id":"53e8bd26-df0f-4517-a755-f32eec51dc92","type":"string/=","value":["Real-time"],"target":["var