INSERT INTO public.query VALUES ('\x73ba4badcbcddc82dbc294e8aef2fcd522a0cf7dee8dcb02536982e6588d0342', 38, '{"constraints":{"max-results":10000,"max-results-bare-rows":2000},"lib/type":"mbql/query","lib/metadata":null,"stages":[{"lib/type":"mbql.stage/native","native":"SELECT\n  `kba_gold`.`gold_product_performance`.`periode_bulan` AS `periode_bulan`,\n  `kba_gold`.`gold_product_performance`.`id_produk` AS `id_produk`,\n  `kba_gold`.`gold_product_performance`.`nama_produk` AS `nama_produk`,\n  `kba_gold`.`gold_product_performance`.`total_sales` AS `total_sales`,\n  `kba_gold`.`gold_product_performance`.`total_qty` AS `total_qty`,\n  `kba_gold`.`gold_product_performance`.`nilai_stok` AS `nilai_stok`,\n  `kba_gold`.`gold_product_performance`.`is_slow_moving_flag` AS `is_slow_moving_flag`\nFROM\n  `kba_gold`.`gold_product_performance`\nwhere `is_slow_moving_flag` IN ({{kategori}})\nAND `periode_bulan` = \nCOALESCE(\n    [[ toStartOfMonth(toDate({{bulan}})) , ]] \n    toStartOfMonth(now())\n  )","template-tags":{"bulan":{"name":"bulan","id":"998ddd19-22af-4c09-a5fa-f20f481254d5","type":"date","display-name":"Bulan"},"kategori":{"display-name":"Kategori","required":false,"type":"text","name":"kategori","id":"73f15e6d-6a97-4fbf-9553-ec4bc3de7440","default":["1"]}}}],"middleware":{"js-int-to-string?":true,"ignore-cached-results?":false,"userland-query?":true},"cache-strategy":null,"viz-settings":{"graph.y_axis.title_text":"Total Penjualan","scatter.bubble":"nilai_stok","graph.series_order_dimension":null,"graph.x_axis.title_text":"Nama Produk","graph.metrics":["total_sales"],"graph.series_order":null,"column_settings":{"[\"name\",\"total_sales\"]":{"number_separators":", ","prefix":"$"}},"series_settings":{"total_sales":{"color":"#227FD2"}},"graph.x_axis.scale":"ordinal","graph.dimensions":["nama_produk"]},"database":2,"parameters":[{"type":"date/single","value":"2026-05-06","id":"8524b4ff","target":["variable",["template-tag","bulan"]]},{"type":"string/=","value":["1"],"i