INSERT INTO public.query VALUES ('\x02585ac08a75804e28e31bea1511a00bc1531f873eceec837e50011d20b6bcd5', 25, '{"lib/type":"mbql/query","database":2,"stages":[{"lib/type":"mbql.stage/native","native":"SELECT\n  `periode_bulanan`,\n  SUM(CASE WHEN is_slow_moving = 1 THEN nilai_stok ELSE 0 END) AS total_stok_slow_moving,\n  SUM(nilai_stok) AS total_seluruh_stok,\n  SUM(CASE WHEN is_slow_moving = 1 THEN nilai_stok ELSE 0 END) * 100 / SUM(nilai_stok) AS rasio_slow_moving\nFROM\n  `kba_gold`.`gold_slow_moving`\nWHERE `periode_bulanan` = \nCOALESCE(\n    [[ toStartOfMonth(toDate({{bulan}})) , ]] \n    toStartOfMonth(now())\n  ) AND `snapshot_type` IN ({{snapshot}})\nGROUP BY `periode_bulanan`","template-tags":{"bulan":{"name":"bulan","id":"17b918c5-2395-47b8-a273-7014a43feaa5","type":"date","display-name":"Bulan"},"snapshot":{"default":["Real-time"],"type":"text","display-name":"Snapshot","name":"snapshot","id":"2b52cf5b-9904-4c59-9114-009887121740","required":true}}}],"parameters":[{"id":"17b918c5-2395-47b8-a273-7014a43feaa5","type":"date/single","value":null,"target":["variable",["template-tag","bulan"]]},{"id":"2b52cf5b-9904-4c59-9114-009887121740","type":"string/=","value":["Real-time"],"target":["variable",["template-tag","snapshot"]]}],"middleware":{"js-int-to-string?":true,"userland-query?":true,"add-default-userland-constraints?":true}}');
