INSERT INTO public.query VALUES ('\xdbf7c7bc3c64a58e6f425ccbbb4038ed85436fa40d9ea71914b24d330be8737c', 32, '{"constraints":{"max-results":10000,"max-results-bare-rows":2000},"lib/type":"mbql/query","lib/metadata":null,"stages":[{"lib/type":"mbql.stage/native","native":"SELECT\n  `kba_gold`.`gold_sales_achievement_conversion`.`periode_bulan` AS `Periode Bulan`,\n  `target_penjualan` as `Target Penjualan`,\n  `aktual_penjualan` as `Penjualan Aktual`,\n  `kba_gold`.`gold_sales_achievement_conversion`.`achievement_rate` AS `Achievement Rate`\nFROM\n  `kba_gold`.`gold_sales_achievement_conversion`\nWHERE `periode_bulan` <= \nCOALESCE(\n    [[ toStartOfMonth(toDate({{bulan}})) , ]] \n    toStartOfMonth(now())\n  )\nORDER BY `periode_bulan` ASC","template-tags":{"bulan":{"id":"2b673b23-2508-4a49-9c66-55d9175b4d3b","type":"date","name":"bulan","display-name":"Bulan"}}}],"middleware":{"js-int-to-string?":true,"ignore-cached-results?":false,"userland-query?":true},"cache-strategy":null,"viz-settings":{"scalar.comparisons":[{"id":"cf85ad35-41ce-9ab7-85ef-9a43f7c84e28","type":"staticNumber","label":"Target Achievement","value":100},{"id":"bfdb6456-28a7-b6d3-b747-d34a1c693d9a","type":"previousValue"}],"graph.y_axis.title_text":"Nilai","graph.show_values":true,"progress.color":"#689636","graph.x_axis.title_text":"Periode","progress.goal":100,"graph.y_axis.labels_enabled":false,"scalar.compact_primary_number":true,"graph.metrics":["Achievement Rate"],"graph.y_axis.unpin_from_zero":false,"graph.label_value_formatting":"compact","scalar.field":"achievement_rate","scalar.switch_positive_negative":false,"column_settings":{"[\"name\",\"Target Penjualan\"]":{"number_separators":", ","prefix":"$"},"[\"name\",\"Penjualan Aktual\"]":{"number_separators":", ","prefix":"$"},"[\"name\",\"Achievement Rate\"]":{"number_separators":", ","suffix":"%"}},"series_settings":{"Target Penjualan":{"color":"#87BCEC","display":"bar"},"Penjualan Aktual":{"display":"bar","color":"#F9D45C"},"Achievement Rate":{"color":"#227FD2","line.size":"L"}},"graph.x_axis.scale":"timeseries","graph.dimensions":["Periode Bulan"]},"database":2,"parameters":[{"type":"date/single","value":"2026-03-30","id":"695f1b78","target":["variable",["template-tag","bulan"]]}]}');
