INSERT INTO public.query VALUES ('\x83c006805f6386b1a54e72cfc7026a8bf9e388265e4f93933b73da114fedb3f9', 31, '{"lib/type":"mbql/query","database":2,"stages":[{"lib/type":"mbql.stage/native","native":"SELECT\n  `kba_gold`.`gold_slow_moving`.`periode_bulanan` AS `Periode Bulanan`,\n  `kba_gold`.`gold_slow_moving`.`snapshot_type` AS `Snapshot Type`,\n  `kba_gold`.`gold_slow_moving`.`nama_produk` AS `Nama Produk`,\n  -- `kba_gold`.`gold_slow_moving`.`id_produk` AS `id_produk`,\n  `kba_gold`.`gold_slow_moving`.`nilai_stok` AS `Nilai Stok`,\n  CASE  \n  WHEN `kba_gold`.`gold_slow_moving`.`is_slow_moving` = 1 THEN ''Slow Moving''\n  WHEN `kba_gold`.`gold_slow_moving`.`is_slow_moving` = 0 THEN ''Non Slow Moving''\n  ELSE ''Unknown''\n  END AS `Status Slow Moving`,\n  `kba_gold`.`gold_slow_moving`.`demand_segment` AS `Demand Segment`,\n  `kba_gold`.`gold_slow_moving`.`slow_moving_reason` AS `slow_moving_reason`\n  \nFROM\n  `kba_gold`.`gold_slow_moving`\n-- WHERE {{bulan}} \nWHERE `periode_bulanan` = \nCOALESCE(\n    [[ toStartOfMonth(toDate({{bulan}})) , ]] \n    toStartOfMonth(now())\n  )\nAND `is_slow_moving` IN ({{Kategori}})\n  AND `snapshot_type` IN ({{Snapshot}})","template-tags":{"Kategori":{"type":"text","display-name":"Kategori","default":["1","0"],"name":"Kategori","id":"7387fc39-351e-4b7e-b826-6498be688002","required":true},"Snapshot":{"display-name":"Snapshot","name":"Snapshot","id":"53e8bd26-df0f-4517-a755-f32eec51dc92","default":["Historical"],"type":"text","required":true},"bulan":{"name":"bulan","id":"22c0d8f7-8cb5-4163-a3f9-094743fd3fc1","type":"text","display-name":"Bulan"}}}],"parameters":[{"id":"7387fc39-351e-4b7e-b826-6498be688002","type":"string/=","value":["1","0"],"target":["variable",["template-tag","Kategori"]]},{"id":"53e8bd26-df0f-4517-a755-f32eec51dc92","type":"string/=","value":["Historical"],"target":["variable",["template-tag","Snapshot"]]},{"id":"22c0d8f7-8cb5-4163-a3f9-094743fd3fc1","type":"string/=","value":null,"target":["variable",["template-tag","bulan"]]}],"middleware":{"js-int-to-string?":true,"userland-query?":true,"add-default-userland-constraints?":true}}');
INSERT INTO public.query VALUES ('\x085b31d45c3aeb466d5667f6f9b73a40d0467c6bd0099f32a23373cedd911e6b', 33, '{"constraints":{"max-results":10000,"max-results-bare-rows":2000},"lib/type":"mbql/query","lib/metadata":null,"stages":[{"lib/type":"mbql.stage/native","native":"SELECT\n  `periode_bulanan`,\n  SUM(CASE WHEN is_slow_moving = 1 THEN nilai_stok ELSE 0 END) AS total_stok_slow_moving,\n  SUM(nilai_stok) AS total_seluruh_stok,\n  SUM(CASE WHEN is_slow_moving = 1 THEN nilai_stok ELSE 0 END) * 100 / SUM(nilai_stok) AS rasio_slow_moving\nFROM\n  `kba_gold`.`gold_slow_moving`\nWHERE `periode_bulanan` = \nCOALESCE(\n    [[ toStartOfMonth(toDate({{bulan}})) , ]] \n    toStartOfMonth(now())\n  ) AND `snapshot_type` IN ({{snapshot}})\nGROUP BY `periode_bulanan`","template-tags":{"bulan":{"id":"17b918c5-2395-47b8-a273-7014a43feaa5","type":"date","name":"bulan","display-name":"Bulan"},"snapshot":{"name":"snapshot","id":"2b52cf5b-9904-4c59-9114-009887121740","default":["Real-time"],"type":"text","display-name":"Snapshot","required":true}}}],"middleware":{"js-int-to-string?":true,"ignore-cached-results?":false,"userland-query?":true},"cache-strategy":null,"viz-settings":{"scalar.field":"rasio_slow_moving","scalar.segments":[{"min":0,"max":24,"color":"#689735","label":"Aman"},{"min":25,"max":59,"color":"#E8B921","label":"Waspada"},{"min":60,"max":100,"color":"#E3595E","label":"Kritis"}],"column_settings":{"[\"name\",\"rasio_slow_moving\"]":{"suffix":"%"}}},"database":2,"parameters":[{"type":"date/single","value":"2026-05-06","id":"8524b4ff","target":["variable",["template-tag","bulan"]]}]}');
INSERT INTO public.query VALUES ('\xa3102385547089e9607a8991ab6fbbbf14db1d2efd5f6a6710008d9ad166b586', 23, '{"lib/type":"mbql/query","database":2,"stages":[{"lib/type":"mbql.stage/native","native":"SELECT\n  `kba_gold`.`gold_slow_moving`.`demand_segment` AS `demand_segment`,\n  `kba_gold`.`gold_slow_moving`.`snapshot_type` AS `Tipe Snapshot`,\n  COUNT(*) AS `count`\nFROM\n  `kba_gold`.`gold_slow_moving`\nWHERE\n  `kba_gold`.`gold_slow_moving`.`is_slow_moving` IN ({{Kategori}})\nGROUP BY\n  `kba_gold`.`gold_slow_moving`.`demand_segment`, `kba_gold`.`gold_slow_moving`.`snapshot_type`\nORDER BY\n  `kba_gold`.`gold_slow_moving`.`demand_segment` ASC","template-tags":{"Kategori":{"default":["1"],"type":"text","display-name":"Kategori","name":"Kategori","id":"98f79f2f-535b-4ef3-ae8a-aefe4741da59","required":true}}}],"parameters":[{"id":"98f79f2f-535b-4ef3-ae8a-aefe4741da59","type":"string/=","value":["1"],"target":["variable",["template-tag","Kategori"]]}],"middleware":{"js-int-to-string?":true,"userland-query?":true,"add-default-userland-constraints?":true}}');
INSERT INTO public.query VALUES ('\xbfcc22a99f955ca142c64e5d77e2607d9f744d9e43eda2142b11e5aa8dedc4bf', 35, '{"constraints":{"max-results":10000,"max-results-bare-rows":2000},"lib/type":"mbql/query","lib/metadata":null,"stages":[{"native":"SELECT\n  `kba_gold`.`gold_slow_moving`.`periode_bulanan` AS `Periode Bulan`,\n  `kba_gold`.`gold_slow_moving`.`id_produk` AS `ID Produk`,\n  `kba_gold`.`gold_slow_moving`.`snapshot_type` AS `Tipe Snapshot`,\n  `kba_gold`.`gold_slow_moving`.`nama_produk` AS `Nama Produk`,\n  `kba_gold`.`gold_slow_moving`.`nilai_stok` AS `Nilai Stok`,\n  `kba_gold`.`gold_slow_moving`.`demand_segment` AS `demand_segment`,\n  `kba_gold`.`gold_slow_moving`.`is_slow_moving` AS `is_slow_moving`,\n  `kba_gold`.`gold_slow_moving`.`slow_moving_reason` AS `slow_moving_reason`\nFROM\n  `kba_gold`.`gold_slow_moving`\nWHERE `periode_bulanan` = \nCOALESCE(\n    [[ toStartOfMonth(toDate({{bulan}})) , ]] \n    toStartOfMonth(now())\n  ) AND `is_slow_moving` IN ({{Kategori}})\n  AND `snapshot_type` IN ({{Snapshot}})\nORDER BY nilai_stok desc","lib/type":"mbql.stage/native","template-tags":{"bulan":{"id":"bdf2f4c2-d859-4583-8964-3eda0a430770","type":"date","name":"bulan","display-name":"Bulan"},"Kategori":{"name":"Kategori","id":"602bff62-d74c-4905-8389-6ffc2d7ccc2a","default":["1"],"type":"text","display-name":"Kategori","required":true},"Snapshot":{"id":"50e13fca-c7df-4123-bac4-165c3a4221cc","type":"text","display-name":"Snapshot","name":"Snapshot","default":["Real-time"]}}}],"middleware":{"js-int-to-string?":true,"ignore-cached-results?":false,"userland-query?":true},"cache-strategy":null,"viz-settings":{"graph.show_values":true,"table.cell_column":"id_produk","graph.series_order_dimension":null,"graph.metrics":["Nilai Stok"],"graph.label_value_formatting":"compact","graph.series_order":null,"table.pivot_column":"periode_bulanan","column_settings":{"[\"name\",\"Nilai Stok\"]":{"number_separators":", ","prefix":"$"}},"series_settings":{"balanced_regular":{"color":"#227FD2"},"Nilai Stok":{"color":"#227FD2"},"dead_stock":{"color":"#F7C41F"},"frequent_small":{"color":"#689636"}},"graph.dimensions":["Nama Produk","demand_segment"],"stackable.stack_type":"stacked"},"database":2,"parameters":[{"type":"date/single","value":"2026-04-27","id":"8524b4ff","target":["variable",["template-tag","bulan"]]},{"type":"string/=","value":["1","0"],"id":"dae647fa","target":["variable",["template-tag","Kategori"]]},{"type":"string/=","value":["Real-time"],"id":"c2e57f55","target":["variable",["template-tag","Snapshot"]]}]}');
INSERT INTO public.query VALUES ('\xee3531d32265559f0696c8ae80b567e0f3c02b9ead0667a9192860ca9471aa5f', 58, '{"constraints":{"max-results":10000,"max-results-bare-rows":2000},"lib/type":"mbql/query","lib/metadata":null,"stages":[{"native":"SELECT\n  *\nFROM\n  `kba_gold`.`gold_product_performance`\nWHERE `periode_bulan` = \nCOALESCE(\n    [[ toStartOfMonth(toDate({{bulan}})) , ]] \n    toStartOfMonth(now())\n  ) AND total_sales > 0\nORDER BY total_sales DESC","lib/type":"mbql.stage/native","template-tags":{"bulan":{"id":"ac3057d7-f18d-4ab0-84a0-f758937158e3","type":"date","name":"bulan","display-name":"Bulan"}}}],"middleware":{"js-int-to-string?":true,"ignore-cached-results?":false,"process-viz-settings?":false,"userland-query?":true},"cache-strategy":null,"viz-settings":{"graph.y_axis.title_text":"Nilai","graph.show_values":true,"graph.series_order_dimension":null,"graph.x_axis.title_text":"Nama Produk","graph.y_axis.auto_split":false,"graph.metrics":["total_sales"],"graph.label_value_formatting":"compact","graph.series_order":null,"column_settings":{"[\"name\",\"total_sales\"]":{"number_separators":", ","prefix":"$"}},"series_settings":{"balanced_regular":{"color":"#227FD2"},"(empty)":{"color":"#DCDFE0"},"total_sales":{"color":"#227FD2"},"Total Sales":{"color":"#227FD2"},"awaiting_more_sales":{"color":"#EF8C8C"},"frequent_small":{"color":"#689636"},"dead_stock":{"color":"#F7C41F"}},"graph.x_axis.scale":"ordinal","graph.dimensions":["nama_produk","demand_segment"],"stackable.stack_type":"stacked"},"database":2,"parameters":[{"id":"ac3057d7-f18d-4ab0-84a0-f758937158e3","type":"date/single","target":["variable",["template-tag","bulan"]],"value":null}]}');
INSERT INTO public.query VALUES ('\xc1ddffc12af47935d7fb40d82041a8f998665514c6ba0c9f278ce6ab91f7e213', 63, '{"constraints":{"max-results":10000,"max-results-bare-rows":2000},"lib/type":"mbql/query","lib/metadata":null,"stages":[{"lib/type":"mbql.stage/native","native":"SELECT\n  `periode_bulanan`,\n  `snapshot_type`,\n  `source`.`is_slow_moving` AS `is_slow_moving`,\n  `source`.`count` AS `count`,\n  `source`.`count` AS `Jumlah Produk`\nFROM\n  (\n    SELECT\n\t  `periode_bulanan`,\n\t  `snapshot_type`,\n      FLOOR(\n        (\n          `kba_gold`.`gold_slow_moving`.`is_slow_moving` / 0.125\n        )\n      ) * 0.125 AS `is_slow_moving`,\n      COUNT(*) AS `count`\n    FROM\n      `kba_gold`.`gold_slow_moving`\n    GROUP BY\n\t  `periode_bulanan`,\n\t  `snapshot_type`,\n      FLOOR(\n        (\n          `kba_gold`.`gold_slow_moving`.`is_slow_moving` / 0.125\n        )\n      ) * 0.125\n    ORDER BY\n      FLOOR(\n        (\n          `kba_gold`.`gold_slow_moving`.`is_slow_moving` / 0.125\n        )\n      ) * 0.125 ASC\n  ) AS `source`\nWHERE `periode_bulanan` = \nCOALESCE(\n    [[ toStartOfMonth(toDate({{bulan}})) , ]] \n    toStartOfMonth(now())\n  ) AND `snapshot_type` = ''Historical''","template-tags":{"bulan":{"name":"bulan","id":"48db9bbd-7275-44f0-8540-56ef79f4ea38","type":"date","display-name":"Bulan","default":null}}}],"middleware":{"js-int-to-string?":true,"ignore-cached-results?":false,"userland-query?":true},"cache-strategy":null,"viz-settings":{"pie.rows":[{"key":"1","name":"Slow Moving","originalName":"1","color":"#F7C41F","defaultColor":false,"enabled":true,"hidden":false,"isOther":false},{"key":"0","name":"Non Slow Moving","originalName":"0","color":"#227FD2","defaultColor":false,"enabled":true,"hidden":false,"isOther":false},{"isOther":false,"hidden":true,"enabled":false,"defaultColor":true,"color":"#509EE3","originalName":"Three-Seat Sofa","name":"Three-Seat Sofa","key":"Three-Seat Sofa"},{"key":"Office Chair","name":"Office Chair","originalNam