INSERT INTO public.query VALUES ('\x5b34a6e3c325389bb327ff2d67639eeb85b3bd5432b784bcf11eaa388105b74d', 50, '{"constraints":{"max-results":10000,"max-results-bare-rows":2000},"lib/type":"mbql/query","lib/metadata":null,"stages":[{"native":"SELECT\n  `kba_gold`.`gold_slow_moving`.`periode_bulanan` AS `periode_bulanan`,\n  `kba_gold`.`gold_slow_moving`.`id_produk` AS `id_produk`,\n    `kba_gold`.`gold_slow_moving`.`snapshot_type` AS `Tipe Snapshot`,\n  `kba_gold`.`gold_slow_moving`.`nilai_stok` AS `nilai_stok`,\n  `kba_gold`.`gold_slow_moving`.`is_slow_moving` AS `is_slow_moving`,\n  `kba_gold`.`gold_slow_moving`.`demand_segment` AS `demand_segment`,\n  `kba_gold`.`gold_slow_moving`.`slow_moving_reason` AS `slow_moving_reason`,\n  `kba_gold`.`gold_slow_moving`.`nama_produk` AS `nama_produk`\nFROM\n  `kba_gold`.`gold_slow_moving`\nWHERE `periode_bulanan` = \nCOALESCE(\n    [[ toStartOfMonth(toDate({{bulan}})) , ]] \n    toStartOfMonth(now())\n  ) AND `is_slow_moving` IN ({{Kategori}})\n  AND `snapshot_type` IN ({{Snapshot}})","lib/type":"mbql.stage/native","template-tags":{"bulan":{"type":"date","name":"bulan","id":"711167c8-a31e-4b8f-8bd3-f8206b8e6eb6","display-name":"Bulan","required":false},"Kategori":{"name":"Kategori","id":"fee005d5-8788-4e88-81f1-973776e7234b","default":["1"],"type":"text","display-name":"Kategori","required":true},"Snapshot":{"id":"6dca2491-e90c-402e-a409-8e7e5ffc9b4b","type":"text","default":["Real-time"],"name":"Snapshot","display-name":"Snapshot","required":true}}}],"middleware":{"js-int-to-string?":true,"ignore-cached-results?":false,"userland-query?":true},"cache-strategy":null,"viz-settings":{"pie.metric":"nilai_stok","pie.dimension":["demand_segment"],"pie.rows":[{"key":"dead_stock","name":"Dead Stock","originalName":"dead_stock","color":"#F7C41F","defaultColor":false,"enabled":true,"hidden":false,"isOther":false},{"key":"balanced_regular","name":"Balanced Regular","originalName":"balanced_regular","color":"#227FD2","defaultColor":false,"e