INSERT INTO public.query VALUES ('\x009864a589e788733c807c9207a5e42952374135016da56820a5bb9b84134d2c', 26, '{"constraints":{"max-results":10000,"max-results-bare-rows":2000},"lib/type":"mbql/query","lib/metadata":null,"stages":[{"native":"SELECT\n  `kba_gold`.`gold_vendor`.`periode_bulan` AS `periode_bulan`,\n  `kba_gold`.`gold_vendor`.`id_vendor` AS `id_vendor`,\n  `kba_gold`.`gold_vendor`.`nama_vendor` AS `nama_vendor`,\n  `kba_gold`.`gold_vendor`.`total_pengiriman` AS `total_pengiriman`,\n  `kba_gold`.`gold_vendor`.`tepat_waktu` AS `tepat_waktu`,\n  `kba_gold`.`gold_vendor`.`otd_pct` AS `otd_pct`\nFROM\n  `kba_gold`.`gold_vendor`\nWHERE `periode_bulan` = \nCOALESCE(\n    [[ toStartOfMonth(toDate({{bulan}})) , ]] \n    toStartOfMonth(now())\n  )\norder by otd_pct desc","lib/type":"mbql.stage/native","template-tags":{"bulan":{"display-name":"Bulan","id":"fd5402b5-cb4a-4a5f-9f24-2ed362ee20f3","type":"date","name":"bulan","default":"2026-04-02"}}}],"middleware":{"js-int-to-string?":true,"ignore-cached-results?":false,"userland-query?":true},"cache-strategy":null,"viz-settings":{"graph.y_axis.title_text":"Rata-rata OTD Rate (%)","graph.show_values":true,"graph.x_axis.title_text":"Nama Vendor","graph.label_value_frequency":"all","graph.metrics":["otd_pct"],"graph.label_value_formatting":"full","column_settings":{"[\"name\",\"otd_pct\"]":{"suffix":"%","number_separators":", "}},"series_settings":{"avg":{"color":"#227FD2"},"otd_pct":{"color":"#227FD2"}},"graph.x_axis.scale":"ordinal","graph.dimensions":["nama_vendor"]},"database":2,"parameters":[{"type":"date/single","value":"2026-01-07","id":"695f1b78","target":["variable",["template-tag","bulan"]]}]}');
