INSERT INTO public.query VALUES ('\x1d5f122b5e0b2197a0f7c790125cb3b62da429d8060762f0b9b53bb408f04cf7', 57, '{"constraints":{"max-results":10000,"max-results-bare-rows":2000},"lib/type":"mbql/query","lib/metadata":null,"stages":[{"native":"SELECT\n  *\nFROM\n  `kba_gold`.`gold_product_performance`\nWHERE `periode_bulan` = \nCOALESCE(\n    [[ toStartOfMonth(toDate({{bulan}})) , ]] \n    toStartOfMonth(now())\n  ) AND total_sales > 0\nORDER BY total_sales DESC","lib/type":"mbql.stage/native","template-tags":{"bulan":{"id":"ac3057d7-f18d-4ab0-84a0-f758937158e3","type":"date","name":"bulan","display-name":"Bulan"}}}],"middleware":{"js-int-to-string?":true,"ignore-cached-results?":false,"process-viz-settings?":false,"userland-query?":true},"cache-strategy":null,"viz-settings":{"graph.y_axis.title_text":"Nilai","graph.show_values":true,"graph.series_order_dimension":null,"graph.x_axis.title_text":"Nama Produk","graph.y_axis.auto_split":false,"graph.metrics":["total_sales"],"graph.label_value_formatting":"compact","graph.series_order":null,"column_settings":{"[\"name\",\"total_sales\"]":{"number_separators":", ","prefix":"$"}},"series_settings":{"balanced_regular":{"color":"#227FD2"},"(empty)":{"color":"#DCDFE0"},"total_sales":{"color":"#227FD2"},"Total Sales":{"color":"#227FD2"},"awaiting_more_sales":{"color":"#EF8C8C"},"frequent_small":{"color":"#689636"},"dead_stock":{"color":"#F7C41F"}},"graph.x_axis.scale":"ordinal","graph.dimensions":["nama_produk","demand_segment"],"stackable.stack_type":"stacked"},"database":2,"parameters":[{"id":"ac3057d7-f18d-4ab0-84a0-f758937158e3","type":"date/single","target":["variable",["template-tag","bulan"]],"value":"2026-03-30"}]}');
INSERT INTO public.query VALUES ('\x81922c2fd4d2bbdedcbc814d04b25ada73d681aac115af006d9dc3c8e5cc4647', 26, '{"constraints":{"max-results":10000,"max-results-bare-rows":2000},"lib/type":"mbql/query","lib/metadata":null,"stages":[{"lib/type":"mbql.stage/native","native":"SELECT\n  `periode_bulanan`,\n  `snapshot_type`,\n  `source`.`is_slow_moving` AS `is_slow_moving`,\n  `source`.`count` AS `count`,\n  `source`.`count` AS `Jumlah Produk`\nFROM\n  (\n    SELECT\n\t  `periode_bulanan`,\n\t  `snapshot_type`,\n      FLOOR(\n        (\n          `kba_gold`.`gold_slow_moving`.`is_slow_moving` / 0.125\n        )\n      ) * 0.125 AS `is_slow_moving`,\n      COUNT(*) AS `count`\n    FROM\n      `kba_gold`.`gold_slow_moving`\n    GROUP BY\n\t  `periode_bulanan`,\n\t  `snapshot_type`,\n      FLOOR(\n        (\n          `kba_gold`.`gold_slow_moving`.`is_slow_moving` / 0.125\n        )\n      ) * 0.125\n    ORDER BY\n      FLOOR(\n        (\n          `kba_gold`.`gold_slow_moving`.`is_slow_moving` / 0.125\n        )\n      ) * 0.125 ASC\n  ) AS `source`\nWHERE `periode_bulanan` = \nCOALESCE(\n    [[ toStartOfMonth(toDate({{bulan}})) , ]] \n    toStartOfMonth(now())\n  ) AND `snapshot_type` = ''Historical''","template-tags":{"bulan":{"name":"bulan","id":"48db9bbd-7275-44f0-8540-56ef79f4ea38","type":"date","display-name":"Bulan","default":null}}}],"middleware":{"js-int-to-string?":true,"ignore-cached-results?":false,"userland-query?":true},"cache-strategy":null,"viz-settings":{"pie.rows":[{"key":"1","name":"Slow Moving","originalName":"1","color":"#F7C41F","defaultColor":false,"enabled":true,"hidden":false,"isOther":false},{"key":"0","name":"Non Slow Moving","originalName":"0","color":"#227FD2","defaultColor":false,"enabled":true,"hidden":false,"isOther":false},{"isOther":false,"hidden":true,"enabled":false,"defaultColor":true,"color":"#509EE3","originalName":"Three-Seat Sofa","name":"Three-Seat Sofa","key":"Three-Seat Sofa"},{"key":"Office Chair","name":"Office Chair","originalName":"Office Chair","color":"#87BCEC","defaultColor":true,"enabled":true,"hidden":true,"isOther":false},{"key":"Office Lamp","name":"Office Lamp","originalName":"Office Lamp","color":"#227FD2","defaultColor":true,"enabled":true,"hidden":true,"isOther":false},{"key":"Desk Combination","name":"Desk Combination","originalName":"Desk Combination","color":"#88BF4D","defaultColor":true,"enabled":true,"hidden":true,"isOther":false},{"key":"Storage Box","name":"Storage Box","originalName":"Storage Box","color":"#A7D07C","defaultColor":true,"enabled":true,"hidden":true,"isOther":false},{"key":"Large Desk","name":"Large Desk","originalName":"Large Desk","color":"#689636","defaultColor":true,"enabled":true,"hidden":true,"isOther":false},{"key":"Cabinet with Doors","name":"Cabinet with Doors","originalName":"Cabinet with Doors","color":"#A989C5","defaultColor":true,"enabled":true,"hidden":true,"isOther":false},{"key":"Office Chair Black","name":"Office Chair Black","originalName":"Office Chair Black","color":"#C8B4DA","defaultColor":true,"enabled":true,"hidden":true,"isOther":false},{"key":"Drawer Black","name":"Drawer Black","originalName":"Drawer Black","color":"#8A5EB0","defaultColor":true,"enabled":true,"hidden":true,"isOther":false},{"key":"Flipover","name":"Flipover","originalName":"Flipover","color":"#EF8C8C","defaultColor":true,"enabled":true,"hidden":true,"isOther":false},{"key":"Desk Stand with Screen","name":"Desk Stand with Screen","originalName":"Desk Stand with Screen","color":"#F7C4C4","defaultColor":true,"enabled":true,"hidden":true,"isOther":false},{"key":"Individual Workplace","name":"Individual Workplace","originalName":"Individual Workplace","color":"#E75454","defaultColor":true,"enabled":true,"hidden":true,"isOther":false},{"key":"Acoustic Bloc Screens","name":"Acoustic Bloc Screens","originalName":"Acoustic Bloc Screens","color":"#F9D45C","defaultColor":true,"enabled":true,"hidden":true,"isOther":false},{"key":"Drawer","name":"Drawer","originalName":"Drawer","color":"#FBE499","defaultColor":true,"enabled":true,"hidden":true,"isOther":false},{"key":"Large Meeting Table","name":"Large Meeting Table","originalName":"Large Meeting Table","color":"#F7C41F","defaultColor":true,"enabled":true,"hidden":true,"isOther":false},{"key":"Table","name":"Table","originalName":"Table","color":"#F2A86F","defaultColor":true,"enabled":true,"hidden":true,"isOther":false},{"key":"Table Top","name":"Table Top","originalName":"Table Top","color":"#F7CBA9","defaultColor":true,"enabled":true,"hidden":true,"isOther":false},{"key":"Table Leg","name":"Table Leg","originalName":"Table Leg","color":"#ED8535","defaultColor":true,"enabled":true,"hidden":true,"isOther":false},{"key":"Bolt","name":"Bolt","originalName":"Bolt","color":"#98D9D9","defaultColor":true,"enabled":true,"hidden":true,"isOther":false},{"key":"Screw","name":"Screw","originalName":"Screw","color":"#C7EAEA","defaultColor":true,"enabled":true,"hidden":true,"isOther":false},{"key":"Ply Layer","name":"Ply Layer","originalName":"Ply Layer","color":"#69C8C8","defaultColor":true,"enabled":true,"hidden":true,"isOther":false},{"key":"Wear Layer","name":"Wear Layer","originalName":"Wear Layer","color":"#7172AD","defaultColor":true,"enabled":true,"hidden":true,"isOther":false},{"key":"Ply Veneer","name":"Ply Veneer","originalName":"Ply Veneer","color":"#999AC4","defaultColor":true,"enabled":true,"hidden":true,"isOther":false},{"key":"Wood Panel","name":"Wood Panel","originalName":"Wood Panel","color":"#51528D","defaultColor":true,"enabled":true,"hidden":true,"isOther":false},{"key":"Plastic Laminate","name":"Plastic Laminate","originalName":"Plastic Laminate","color":"#509EE3","defaultColor":true,"enabled":true,"hidden":true,"isOther":false},{"key":"Drawer Case Black","name":"Drawer Case Black","originalName":"Drawer Case Black","color":"#87BCEC","defaultColor":true,"enabled":true,"hidden":true,"isOther":false}],"pie.dimension":["is_slow_moving"],"pie.show_total":false,"pie.show_legend":true,"pie.percent_visibility":"legend","pie.show_labels":false,"version":2,"pie.metric":"Jumlah Produk"},"database":2,"parameters":[{"type":"date/single","value":"2026-01-07","id":"695f1b78","target":["variable",["template-tag","bulan"]]}]}');
INSERT INTO public.query VALUES ('\x2b1dc97f6809c7c5c7e13a0de6bc8cd2a1273d39e579ef7483b7442052288a0c', 43, '{"constraints":{"max-results":10000,"max-results-bare-rows":2000},"lib/type":"mbql/query","lib/metadata":null,"stages":[{"lib/type":"mbql.stage/native","native":"SELECT\n  `periode_bulanan`,\n  SUM(CASE WHEN is_slow_moving = 1 THEN nilai_stok ELSE 0 END) AS total_stok_slow_moving,\n  SUM(nilai_stok) AS total_seluruh_stok,\n  SUM(CASE WHEN is_slow_moving = 1 THEN nilai_stok ELSE 0 END) * 100 / SUM(nilai_stok) AS rasio_slow_moving\nFROM\n  `kba_gold`.`gold_slow_moving`\nWHERE `periode_bulanan` = \nCOALESCE(\n    [[ toStartOfMonth(toDate({{bulan}})) , ]] \n    toStartOfMonth(now())\n  ) AND `snapshot_type` IN ({{snapshot}})\nGROUP BY `periode_bulanan`","template-tags":{"bulan":{"id":"17b918c5-2395-47b8-a273-7014a43feaa5","type":"date","name":"bulan","display-name":"Bulan"},"snapshot":{"name":"snapshot","id":"2b52cf5b-9904-4c59-9114-009887121740","default":["Real-time"],"type":"text","display-name":"Snapshot","required":true}}}],"middleware":{"js-int-to-string?":true,"ignore-cached-results?":false,"userland-query?":true},"cache-strategy":null,"viz-settings":{"scalar.field":"rasio_slow_moving","scalar.segments":[{"min":0,"max":24,"color":"#689735","label":"Aman"},{"min":25,"max":59,"color":"#E8B921","label":"Waspada"},{"min":60,"max":100,"color":"#E3595E","label":"Kritis"}],"column_settings":{"[\"name\",\"rasio_slow_moving\"]":{"suffix":"%"}}},"database":2,"parameters":[{"type":"date/single","value":null,"id":"8524b4ff","target":["variable",["template-tag","bulan"]]},{"type":"string/=","value":["Historical"],"id":"c2e57f55","target":["variable",["template-tag","snapshot"]]}]}');
INSERT INTO public.query VALUES ('\x9ff5359b3ed8c667d17e2317e6cc4dc4f98dfc1cb57ec4ccbc8669b52966d28c', 20, '{"constraints":{"max-results":10000,"max-results-bare-rows":2000},"lib/type":"mbql/query","lib/metadata":null,"stages":[{"native":"SELECT\n  *\nFROM\n  `kba_gold`.`gold_product_performance`\nWHERE `periode_bulan` = \nCOALESCE(\n    [[ toStartOfMonth(toDate({{bulan}})) , ]] \n    toStartOfMonth(now())\n  ) AND total_sales > 0\nORDER BY total_sales DESC","lib/type":"mbql.stage/native","template-tags":{"bulan":{"id":"ac3057d7-f18d-4ab0-84a0-f758937158e3","type":"date","name":"bulan","display-name":"Bulan"}}}],"middleware":{"js-int-to-string?":true,"ignore-cached-results?":false,"userland-query?":true},"cache-strategy":null,"viz-settings":{"graph.y_axis.title_text":"Nilai","graph.show_values":true,"graph.series_order_dimension":null,"graph.x_axis.title_text":"Nama Produk","graph.y_axis.auto_split":false,"graph.metrics":["total_sales"],"graph.label_value_formatting":"compact","graph.series_order":null,"column_settings":{"[\"name\",\"total_sales\"]":{"number_separators":", ","prefix":"$"}},"series_settings":{"balanced_regular":{"color":"#227FD2"},"(empty)":{"color":"#DCDFE0"},"total_sales":{"color":"#227FD2"},"Total Sales":{"color":"#227FD2"},"awaiting_more_sales":{"color":"#EF8C8C"},"frequent_small":{"color":"#689636"},"dead_stock":{"color":"#F7C41F"}},"graph.x_axis.scale":"ordinal","graph.dimensions":["nama_produk","demand_segment"],"stackable.stack_type":"stacked"},"database":2,"parameters":[{"type":"date/single","value":"2026-01-07","id":"695f1b78","target":["variable",["template-tag","bulan"]]}]}');
INSERT INTO public.query VALUES ('\x5b1a8ad4fa8472944c6c03cd6dbefef4e751d8300ec49fe8c47637773e3b6376', 56, '{"constraints":{"max-results":10000,"max-results-bare-rows":2000},"lib/type":"mbql/query","lib/metadata":null,"stages":[{"native":"SELECT\n  `kba_gold`.`gold_top_spending`.`periode_bulan` AS `periode_bulan`,\n  `kba_gold`.`gold_top_spending`.`rank_pengeluaran` AS `rank_pengeluaran`,\n  `kba_gold`.`gold_top_spending`.`demand_segment` AS `demand_segment`,\n  `kba_gold`.`gold_top_spending`.`id_produk` AS `id_produk`,\n  `kba_gold`.`gold_top_spending`.`nama_produk` AS `nama_produk`,\n  `kba_gold`.`gold_top_spending`.`total_pengeluaran_produk` AS `total_pengeluaran_produk`\n  \nFROM\n  `kba_gold`.`gold_top_spending`\nWHERE `periode_bulan` = \nCOALESCE(\n    [[ toStartOfMonth(toDate({{bulan}})) , ]] \n    toStartOfMonth(now())\n  )\nORDER BY\n  `kba_gold`.`gold_top_spending`.`rank_pengeluaran` ASC\nLIMIT\n  1048575","lib/type":"mbql.stage/native","template-tags":{"bulan":{"id":"ca1860c6-3cb4-4588-a5b6-27fdce33c515","type":"date","name":"bulan","display-name":"Bulan","required":false}}}],"middleware":{"js-int-to-string?":true,"ignore-cached-results?":false,"process-viz-settings?":false,"userland-query?":true},"cache-strategy":null,"viz-settings":{"graph.y_axis.title_text":"Total Pengeluaran","graph.show_values":true,"table.cell_column":"id_produk","graph.series_order_dimension":null,"graph.x_axis.title_text":"Nama Produk","graph.metrics":["total_pengeluaran_produk"],"graph.label_value_formatting":"compact","graph.series_order":null,"table.pivot_column":"periode_bulan","column_settings":{"[\"name\",\"rank_pengeluaran\"]":{"column_title":"Rank","number_separators":", "},"[\"name\",\"id_produk\"]":{"column_title":"ID Produk","number_separators":", "},"[\"name\",\"nama_produk\"]":{"column_title":"Nama Produk","text_wrapping":false},"[\"name\",\"total_pengeluaran_produk\"]":{"column_title":"Total Pengeluaran","number_separators":", ","prefix":"$"}},"series_settings":{"frequent_small":{"color":"#689636"},"balanced_regular":{"color":"#227FD2"},"total_pengeluaran_produk":{"color":"#227FD2"},"dead_stock":{"color":"#F7C41F"},"rare_bulk":{"color":"#F2A86F"}},"graph.dimensions":["nama_produk","demand_segment"],"stackable.stack_type":"stacked"},"database":2,"parameters":[{"id":"ca1860c6-3cb4-4588-a5b6-27fdce33c515","type":"date/single","target":["variable",["template-tag","bulan"]],"value":"2026-04-28"}]}');
INSERT INTO public.query VALUES ('\x2bc9f8366c95b902decc1975a91cf8e6d3d9cfc5d54d46d2b17c0cfa846b4b36', 45, '{"constraints":{"max-results":10000,"max-results-bare-rows":2000},"lib/type":"mbql/query","lib/metadata":null,"stages":[{"lib/type":"mbql.stage/native","native":"SELECT\n  `kba_gold`.`gold_sales_achievement_conversion`.`periode_bulan` AS `Periode Bulan`,\n  `target_penjualan` as `Target Penjualan`,\n  `aktual_penjualan` as `Penjualan Aktual`,\n  `kba_gold`.`gold_sales_achievement_conversion`.`achievement_rate` AS `Achievement Rate`\nFROM\n  `kba_gold`.`gold_sales_achievement_conversion`\nWHERE `periode_bulan` <= \nCOALESCE(\n    [[ toStartOfMonth(toDate({{bulan}})) , ]] \n    toStartOfMonth(now())\n  )\nORDER BY `periode_bulan` ASC","template-tags":{"bulan":{"id":"2b673b23-2508-4a49-9c66-55d9175b4d3b","type":"date","name":"bulan","display-name":"Bulan"}}}],"middleware":{"js-int-to-string?":true,"ignore-cached-results?":false,"userland-query?":true},"cache-strategy":null,"viz-settings":{"scalar.comparisons":[{"id":"cf85ad35-41ce-9ab7-85ef-9a43f7c84e28","type":"staticNumber","label":"Target Achievement","value":100},{"id":"bfdb6456-28a7-b6d3-b747-d34a1c693d9a","type":"previousValue"}],"graph.y_axis.title_text":"Nilai","graph.show_values":true,"progress.color":"#689636","graph.x_axis.title_text":"Periode","progress.goal":100,"graph.y_axis.labels_enabled":false,"scalar.compact_primary_number":true,"graph.metrics":["Achievement Rate"],"graph.y_axis.unpin_from_zero":false,"graph.label_value_formatting":"compact","scalar.field":"achievement_rate","scalar.switch_positive_negative":false,"column_settings":{"[\"name\",\"Target Penjualan\"]":{"number_separators":", ","prefix":"$"},"[\"name\",\"Penjualan Aktual\"]":{"number_separators":", ","prefix":"$"},"[\"name\",\"Achievement Rate\"]":{"number_separators":", ","suffix":"%"}},"series_settings":{"Target Penjualan":{"color":"#87BCEC","display":"bar"},"Penjualan Aktual":{"display":"bar","color":"#F9D45C"},"Achievement Rate":{"color":"#227FD2","line.size":"L"}},"graph.x_axis.scale":"timeseries","graph.dimensions":["Periode Bulan"]},"database":2,"parameters":[{"type":"date/single","value":"2026-03-29","id":"695f1b78","target":["variable",["template-tag","bulan"]]}]}');
INSERT INTO public.query VALUES ('\xc126df941042a27c1227c463db7f1e438bbe3bf35154fc1d6fccc18ef7486cd7', 17, '{"constraints":{"max-results":10000,"max-results-bare-rows":2000},"lib/type":"mbql/query","lib/metadata":null,"stages":[{"lib/type":"mbql.stage/native","native":"SELECT\n  `kba_gold`.`gold_sales_achievement_conversion`.`periode_bulan` AS `Periode Bulan`,\n   `total_quotation` as `Total Quotation`,\n   `aktual_penjualan` as `Penjualan Aktual`,\n  `kba_gold`.`gold_sales_achievement_conversion`.`conversion_rate` AS `Conversion Rate`\nFROM\n  `kba_gold`.`gold_sales_achievement_conversion`\nWHERE `periode_bulan` <= \nCOALESCE(\n    [[ toStartOfMonth(toDate({{bulan}})) , ]] \n    toStartOfMonth(now())\n  )\nORDER BY `periode_bulan` ASC","template-tags":{"bulan":{"id":"aa7d07b1-55d4-4a56-a53e-9236e979552b","type":"date","name":"bulan","display-name":"Bulan"}}}],"middleware":{"js-int-to-string?":true,"ignore-cached-results?":false,"userland-query?":true},"cache-strategy":null,"viz-settings":{"scalar.comparisons":[{"id":"a9dd4d47-179a-6adf-2403-8e3ff0deabf0","type":"staticNumber","label":"Target Conversion","value":70},{"id":"0ece0d52-a3b5-4928-dc43-ac4737c7e883","type":"previousValue"}],"graph.y_axis.title_text":"Value","graph.show_values":true,"progress.color":"#689636","graph.x_axis.title_text":"Periode","progress.goal":70,"graph.y_axis.labels_enabled":false,"graph.metrics":["Conversion Rate"],"graph.label_value_formatting":"compact","scalar.field":"conversion_rate","column_settings":{"[\"name\",\"Total Quotation\"]":{"prefix":"$"},"[\"name\",\"Penjualan Aktual\"]":{"prefix":"$"},"[\"name\",\"Conversion Rate\"]":{"number_separators":", ","suffix":"%"}},"series_settings":{"Total Quotation":{"display":"bar","color":"#87BCEC"},"Penjualan Aktual":{"display":"bar","color":"#F9D45C"},"Conversion Rate":{"line.size":"L","line.marker_enabled":null,"color":"#227FD2"}},"graph.x_axis.scale":"timeseries","graph.dimensions":["Periode Bulan"]},"database":2,"parameters":[{"type":"d