INSERT INTO public.query VALUES ('\xef4bf98ac3c785a370368610924776b84bb2dea4735a91e218bfccabcae1a28a', 52, '{"constraints":{"max-results":10000,"max-results-bare-rows":2000},"lib/type":"mbql/query","lib/metadata":null,"stages":[{"native":"SELECT\n-- `kba_gold`.`gold_budget_adherence_vendor_otd`.`budget_usage_pct` AS `budget_usage_pct`\n*\nFROM\n  `kba_gold`.`gold_budget_adherence_vendor_otd`\nWHERE `periode_bulan` <= \nCOALESCE(\n    [[ toStartOfMonth(toDate({{bulan}})) , ]] \n    toStartOfMonth(now())\n  )\n  AND (\n    SELECT count(*) \n    FROM `kba_gold`.`gold_budget_adherence_vendor_otd` \n    WHERE `periode_bulan` = \n\tCOALESCE(\n    [[ toStartOfMonth(toDate({{bulan}})) , ]] \n    toStartOfMonth(now())\n  ) \n  ) > 0\nORDER BY `periode_bulan` ASC","lib/type":"mbql.stage/native","template-tags":{"bulan":{"id":"63ec009d-9950-498c-bfd5-b69b769aaccf","type":"date","display-name":"Bulan","name":"bulan","default":null}}}],"middleware":{"js-int-to-string?":true,"ignore-cached-results?":false,"userland-query?":true},"cache-strategy":null,"viz-settings":{"gauge.segments":[{"min":0,"max":90,"color":"#689735","label":"Aman"},{"min":90,"max":95,"color":"#E8B921","label":"Beresiko"},{"min":95,"max":100,"color":"#E3595E","label":"Melebihi Batas"}],"table.pivot_column":"periode_bulan","table.cell_column":"total_pengeluaran_po","scalar.field":"budget_usage_pct","scalar.comparisons":[{"id":"e90f3a91-ecfe-5326-a698-20a3c7cac6b3","type":"staticNumber","label":"Maximum Usage","value":90},{"id":"a63dcca3-f5fc-3e6a-7494-896bfcf8dc7f","type":"previousPeriod"}],"scalar.switch_positive_negative":true,"column_settings":{"[\"name\",\"budget_usage_pct\"]":{"suffix":"%"}},"click_behavior":{"parameterMapping":{"b3ba716":{"source":{"type":"parameter","id":"695f1b78","name":"Bulan"},"target":{"type":"parameter","id":"b3ba716"},"id":"b3ba716"}},"targetId":5,"linkType":"dashboard","type":"link"}},"database":2,"parameters":[{"type":"date/single","value":"2026-03-31","id":"695f1b78","target":["