INSERT INTO public.query VALUES ('\xb54c92ba3b74283a25e665f9446a02409992cfd99dcffdfc44f080e20b546eb7', 41, '{"constraints":{"max-results":10000,"max-results-bare-rows":2000},"lib/type":"mbql/query","lib/metadata":null,"stages":[{"lib/type":"mbql.stage/native","native":"SELECT\n  -- `kba_gold`.`gold_sales_achievement_conversion`.`periode_bulan` AS `periode_bulan`,\n  -- `kba_gold`.`gold_sales_achievement_conversion`.`conversion_rate` AS `conversion_rate`\n  *\nFROM\n  `kba_gold`.`gold_sales_achievement_conversion`\nWHERE `periode_bulan` <= \nCOALESCE(\n    [[ toStartOfMonth(toDate({{bulan}})) , ]] \n    toStartOfMonth(now())\n  )\nORDER BY `periode_bulan` ASC","template-tags":{"bulan":{"id":"d1e5b910-38b6-466c-b3b0-4c34d31f346a","type":"date","name":"bulan","display-name":"Bulan"}}}],"middleware":{"js-int-to-string?":true,"ignore-cached-results?":false,"userland-query?":true},"cache-strategy":null,"viz-settings":{"progress.goal":70,"progress.color":"#689636","scalar.field":"conversion_rate","scalar.comparisons":[{"id":"a9dd4d47-179a-6adf-2403-8e3ff0deabf0","type":"staticNumber","label":"Target Conversion","value":70},{"id":"0ece0d52-a3b5-4928-dc43-ac4737c7e883","type":"previousValue"}],"column_settings":{"[\"name\",\"conversion_rate\"]":{"suffix":"%"}},"click_behavior":{"parameterMapping":{"29b9c635":{"source":{"type":"parameter","id":"695f1b78","name":"Bulan"},"target":{"type":"parameter","id":"29b9c635"},"id":"29b9c635"}},"targetId":3,"linkType":"dashboard","type":"link"}},"database":2,"parameters":[{"type":"date/single","value":"2026-02-04","id":"695f1b78","target":["variable",["template-tag","bulan"]]}]}');
