INSERT INTO public.query VALUES ('\xefa38f10243858cf02bb391adf7353b75403f3a2584cc3dbb45401c5f2441ccf', 74, '{"constraints":{"max-results":10000,"max-results-bare-rows":2000},"lib/type":"mbql/query","lib/metadata":null,"stages":[{"lib/type":"mbql.stage/native","native":"SELECT\n  `periode_bulanan`,\n  SUM(CASE WHEN is_slow_moving = 1 THEN nilai_stok ELSE 0 END) AS total_stok_slow_moving,\n  SUM(nilai_stok) AS total_seluruh_stok,\n  SUM(CASE WHEN is_slow_moving = 1 THEN nilai_stok ELSE 0 END) * 100 / SUM(nilai_stok) AS rasio_slow_moving\nFROM\n  `kba_gold`.`gold_slow_moving`\nWHERE `periode_bulanan` = \nCOALESCE(\n    [[ toStartOfMonth(toDate({{bulan}})) , ]] \n    toStartOfMonth(now())\n  ) AND `snapshot_type` IN ({{snapshot}})\nGROUP BY `periode_bulanan`","template-tags":{"bulan":{"id":"17b918c5-2395-47b8-a273-7014a43feaa5","type":"date","name":"bulan","display-name":"Bulan"},"snapshot":{"display-name":"Snapshot","name":"snapshot","id":"2b52cf5b-9904-4c59-9114-009887121740","default":["Historical"],"type":"text","required":true}}}],"middleware":{"js-int-to-string?":true,"ignore-cached-results?":false,"userland-query?":true},"cache-strategy":null,"viz-settings":{"scalar.field":"rasio_slow_moving","scalar.segments":[{"min":0,"max":24,"color":"#689735","label":"Aman"},{"min":25,"max":59,"color":"#E8B921","label":"Waspada"},{"min":60,"max":100,"color":"#E3595E","label":"Kritis"}],"column_settings":{"[\"name\",\"rasio_slow_moving\"]":{"suffix":"%"}}},"database":2,"parameters":[{"type":"date/single","value":"2026-05-01","id":"8524b4ff","target":["variable",["template-tag","bulan"]]},{"type":"string/=","value":["Historical"],"id":"c2e57f55","target":["variable",["template-tag","snapshot"]]}]}');
