INSERT INTO public.query VALUES ('\xdcdb69c667d6c4fd5ab5beab5fa18f4e1f1a17ab59e8b94344ea3cf8631283ba', 34, '{"lib/type":"mbql/query","stages":[{"lib/type":"mbql.stage/native","native":"SELECT\n  `kba_gold`.`gold_slow_moving`.`periode_bulanan` AS `periode_bulanan`,\n  `kba_gold`.`gold_slow_moving`.`snapshot_type` AS `snapshot_type`,\n  `kba_gold`.`gold_slow_moving`.`id_produk` AS `id_produk`,\n  `kba_gold`.`gold_slow_moving`.`nilai_stok` AS `nilai_stok`,\n  `kba_gold`.`gold_slow_moving`.`is_slow_moving` AS `is_slow_moving`,\n  `kba_gold`.`gold_slow_moving`.`demand_segment` AS `demand_segment`,\n  `kba_gold`.`gold_slow_moving`.`slow_moving_reason` AS `slow_moving_reason`,\n  `kba_gold`.`gold_slow_moving`.`nama_produk` AS `nama_produk`,\n  `Silver Fitur Movement Bulanan - Periode Bulanan`.`periode_bulan` AS `Silver Fitur Movement Bulanan - Periode Bulanan__pe_f5742e38`,\n  `Silver Fitur Movement Bulanan - Periode Bulanan`.`id_produk` AS `Silver Fitur Movement Bulanan - Periode Bulanan__id_produk`,\n  `Silver Fitur Movement Bulanan - Periode Bulanan`.`snapshot_date` AS `Silver Fitur Movement Bulanan - Periode Bulanan__sn_18680083`,\n  `Silver Fitur Movement Bulanan - Periode Bulanan`.`snapshot_type` AS `Silver Fitur Movement Bulanan - Periode Bulanan__sn_3e2860d0`,\n  `Silver Fitur Movement Bulanan - Periode Bulanan`.`frekuensi_transaksi` AS `Silver Fitur Movement Bulanan - Periode Bulanan__fr_d67abe7d`,\n  `Silver Fitur Movement Bulanan - Periode Bulanan`.`total_qty_terjual_keluar` AS `Silver Fitur Movement Bulanan - Periode Bulanan__to_4984e324`,\n  `Silver Fitur Movement Bulanan - Periode Bulanan`.`rata2_qty_per_transaksi` AS `Silver Fitur Movement Bulanan - Periode Bulanan__ra_89601070`,\n  `Silver Fitur Movement Bulanan - Periode Bulanan`.`max_qty_per_transaksi` AS `Silver Fitur Movement Bulanan - Periode Bulanan__ma_73351158`,\n  `Silver Fitur Movement Bulanan - Periode Bulanan`.`jeda_hari_dari_transaksi_terakhir` AS `Silver Fitur Movement Bulanan - Periode Bulanan__je_6ff4eee3`\nFROM\n  `kba_gold`.`gold_slow_moving`\n  LEFT JOIN (\n    SELECT\n      `kba_silver`.`silver_fitur_movement_bulanan`.`periode_bulan` AS `periode_bulan`,\n      `kba_silver`.`silver_fitur_movement_bulanan`.`id_produk` AS `id_produk`,\n      `kba_silver`.`silver_fitur_movement_bulanan`.`snapshot_date` AS `snapshot_date`,\n      `kba_silver`.`silver_fitur_movement_bulanan`.`snapshot_type` AS `snapshot_type`,\n      `kba_silver`.`silver_fitur_movement_bulanan`.`frekuensi_transaksi` AS `frekuensi_transaksi`,\n      `kba_silver`.`silver_fitur_movement_bulanan`.`total_qty_terjual_keluar` AS `total_qty_terjual_keluar`,\n      `kba_silver`.`silver_fitur_movement_bulanan`.`rata2_qty_per_transaksi` AS `rata2_qty_per_transaksi`,\n      `kba_silver`.`silver_fitur_movement_bulanan`.`max_qty_per_transaksi` AS `max_qty_per_transaksi`,\n      `kba_silver`.`silver_fitur_movement_bulanan`.`jeda_hari_dari_transaksi_terakhir` AS `jeda_hari_dari_transaksi_terakhir`\n    FROM\n      `kba_silver`.`silver_fitur_movement_bulanan`\n  ) AS `Silver Fitur Movement Bulanan - Periode Bulanan` ON (\n    `toStartOfDay`(`kba_gold`.`gold_slow_moving`.`periode_bulanan`) = `toStartOfDay`(\n      `Silver Fitur Movement Bulanan - Periode Bulanan`.`periode_bulan`\n    )\n  )\n  AND (\n    `kba_gold`.`gold_slow_moving`.`id_produk` = `Silver Fitur Movement Bulanan - Periode Bulanan`.`id_produk`\n  )\nLIMIT\n  1048575"}],"database":2,"middleware":{"js-int-to-string?":true,"userland-query?":true,"add-default-userland-constraints?":true}}');
