INSERT INTO public.query VALUES ('\xdb6d41ab787e20a020e00fdd915b5baba1c4c7b5c86e8994b70124181fc01903', 42, '{"constraints":{"max-results":10000,"max-results-bare-rows":2000},"lib/type":"mbql/query","lib/metadata":null,"stages":[{"native":"SELECT\n  `kba_gold`.`gold_sales_achievement_conversion`.`periode_bulan` AS `periode_bulan`,\n  `kba_gold`.`gold_sales_achievement_conversion`.`total_quotation` AS `total_quotation`,\n  `kba_gold`.`gold_sales_achievement_conversion`.`aktual_penjualan` AS `aktual_penjualan`\nFROM\n  `kba_gold`.`gold_sales_achievement_conversion`\n-- WHERE {{bulan}}","lib/type":"mbql.stage/native"}],"middleware":{"js-int-to-string?":true,"ignore-cached-results?":false,"process-viz-settings?":false,"userland-query?":true},"cache-strategy":null,"viz-settings":{"graph.y_axis.title_text":"Nilai","graph.show_values":true,"graph.x_axis.title_text":"Periode Bulan","graph.y_axis.auto_split":false,"graph.label_value_frequency":"fit","graph.metrics":["total_quotation","aktual_penjualan"],"column_settings":{"[\"name\",\"periode_bulan\"]":{"column_title":"Periode Bulan","date_style":"D MMMM, YYYY"},"[\"name\",\"total_quotation\"]":{"column_title":"Total Quotation","number_separators":", ","prefix":"$"},"[\"name\",\"aktual_penjualan\"]":{"column_title":"Penjualan Aktual","number_separators":", ","prefix":"$"}},"series_settings":{"total_quotation":{"color":"#F9D45C","display":"bar","title":"Total Quotation"},"aktual_penjualan":{"display":"line","color":"#509EE3","title":"Penjualan Aktual"}},"graph.x_axis.scale":"timeseries","graph.dimensions":["periode_bulan"],"stackable.stack_type":null},"database":2}');
