INSERT INTO public.query VALUES ('\x69f0914b01cac6643f24b554f74e556a18fa6a728e49d557555a1ee7aa277c45', 39, '{"constraints":{"max-results":10000,"max-results-bare-rows":2000},"lib/type":"mbql/query","lib/metadata":null,"stages":[{"native":"SELECT\n  `kba_gold`.`gold_slow_moving`.`periode_bulanan` AS `Periode Bulanan`,\n  `kba_gold`.`gold_slow_moving`.`snapshot_type` AS `Snapshot Type`,\n  `kba_gold`.`gold_slow_moving`.`nama_produk` AS `Nama Produk`,\n  -- `kba_gold`.`gold_slow_moving`.`id_produk` AS `id_produk`,\n  `kba_gold`.`gold_slow_moving`.`nilai_stok` AS `Nilai Stok`,\n  CASE  \n  WHEN `kba_gold`.`gold_slow_moving`.`is_slow_moving` = 1 THEN ''Slow Moving''\n  WHEN `kba_gold`.`gold_slow_moving`.`is_slow_moving` = 0 THEN ''Non Slow Moving''\n  ELSE ''Unknown''\n  END AS `Status Slow Moving`,\n  `kba_gold`.`gold_slow_moving`.`demand_segment` AS `Demand Segment`,\n  `kba_gold`.`gold_slow_moving`.`slow_moving_reason` AS `slow_moving_reason`\n  \nFROM\n  `kba_gold`.`gold_slow_moving`\n-- WHERE {{bulan}} \nWHERE `periode_bulanan` = \nCOALESCE(\n    [[ toStartOfMonth(toDate({{bulan}})) , ]] \n    toStartOfMonth(now())\n  )\nAND `is_slow_moving` IN ({{Kategori}})\n  AND `snapshot_type` IN ({{Snapshot}})","lib/type":"mbql.stage/native","template-tags":{"Kategori":{"display-name":"Kategori","default":["1","0"],"name":"Kategori","id":"7387fc39-351e-4b7e-b826-6498be688002","type":"text","required":true},"Snapshot":{"name":"Snapshot","id":"53e8bd26-df0f-4517-a755-f32eec51dc92","default":["Historical"],"type":"text","display-name":"Snapshot","required":true},"bulan":{"type":"date","name":"bulan","id":"22c0d8f7-8cb5-4163-a3f9-094743fd3fc1","display-name":"Bulan"}}}],"middleware":{"js-int-to-string?":true,"ignore-cached-results?":false,"userland-query?":true},"cache-strategy":null,"viz-settings":{"table.column_formatting":[{"columns":["Demand Segment"],"type":"single","operator":"=","value":"frequent_small","color":"#A7D07C","highlight_row":false},{"columns":["Demand Segment"],"type":"single","operator":"=","value":"balanced_regular","color":"#87BCEC","highlight_row":false},{"columns":["Demand Segment"],"type":"single","operator":"=","value":"dead_stock","color":"#F9D45C","highlight_row":false},{"columns":["Status Slow Moving"],"type":"single","operator":"=","value":"Slow Moving","color":"#EF8C8C","highlight_row":true}],"table.pivot_column":"Periode Bulanan","table.cell_column":"Nilai Stok","column_settings":{"[\"name\",\"Periode Bulanan\"]":{"date_style":"D MMMM, YYYY","date_abbreviate":false},"[\"name\",\"Nilai Stok\"]":{"prefix":"$","number_separators":", ","show_mini_bar":false},"[\"name\",\"Status Slow Moving\"]":{"text_wrapping":false}}},"database":2,"parameters":[{"type":"date/single","value":null,"id":"8524b4ff","target":["variable",["template-tag","bulan"]]},{"type":"string/=","value":["1"],"id":"dae647fa","target":["variable",["template-tag","Kategori"]]},{"type":"string/=","value":["Historical"],"id":"c2e57f55","target":["variable",["template-tag","Snapshot"]]}]}');
