INSERT INTO public.query VALUES ('\x113fe35d3826902da23e2fea2717e0fa832337815c4ee5c9c714620d6f07802a', 51, '{"constraints":{"max-results":10000,"max-results-bare-rows":2000},"lib/type":"mbql/query","lib/metadata":null,"stages":[{"native":"SELECT\n  *\nFROM\n  `kba_gold`.`gold_product_performance`\nWHERE `periode_bulan` = \nCOALESCE(\n    [[ toStartOfMonth(toDate({{bulan}})) , ]] \n    toStartOfMonth(now())\n  ) AND total_sales > 0\nORDER BY total_sales DESC","lib/type":"mbql.stage/native","template-tags":{"bulan":{"id":"ac3057d7-f18d-4ab0-84a0-f758937158e3","type":"date","name":"bulan","display-name":"Bulan"}}}],"middleware":{"js-int-to-string?":true,"ignore-cached-results?":false,"userland-query?":true},"cache-strategy":null,"viz-settings":{"graph.y_axis.title_text":"Nilai","graph.show_values":true,"graph.series_order_dimension":null,"graph.x_axis.title_text":"Nama Produk","graph.y_axis.auto_split":false,"graph.metrics":["total_sales"],"graph.label_value_formatting":"compact","graph.series_order":null,"column_settings":{"[\"name\",\"total_sales\"]":{"number_separators":", ","prefix":"$"}},"series_settings":{"balanced_regular":{"color":"#227FD2"},"(empty)":{"color":"#DCDFE0"},"total_sales":{"color":"#227FD2"},"Total Sales":{"color":"#227FD2"},"awaiting_more_sales":{"color":"#EF8C8C"},"frequent_small":{"color":"#689636"},"dead_stock":{"color":"#F7C41F"}},"graph.x_axis.scale":"ordinal","graph.dimensions":["nama_produk","demand_segment"],"stackable.stack_type":"stacked"},"database":2,"parameters":[{"type":"date/single","value":"2026-03-29","id":"695f1b78","target":["variable",["template-tag","bulan"]]}]}');
