INSERT INTO public.query VALUES ('\xc0737c645ffb372cd76faacbf2eb50c3f082b27a62f9fd88500414d867e6f862', 44, '{"constraints":{"max-results":10000,"max-results-bare-rows":2000},"lib/type":"mbql/query","lib/metadata":null,"stages":[{"lib/type":"mbql.stage/native","native":"SELECT\n  `periode_bulanan`,\n  SUM(CASE WHEN is_slow_moving = 1 THEN nilai_stok ELSE 0 END) AS total_stok_slow_moving,\n  SUM(nilai_stok) AS total_seluruh_stok,\n  SUM(CASE WHEN is_slow_moving = 1 THEN nilai_stok ELSE 0 END) * 100 / SUM(nilai_stok) AS rasio_slow_moving\nFROM\n  `kba_gold`.`gold_slow_moving`\nWHERE `periode_bulanan` = \nCOALESCE(\n    [[ toStartOfMonth(toDate({{bulan}})) , ]] \n    toStartOfMonth(now())\n  ) AND `snapshot_type` IN ({{snapshot}})\nGROUP BY `periode_bulanan`","template-tags":{"bulan":{"id":"17b918c5-2395-47b8-a273-7014a43feaa5","type":"date","name":"bulan","display-name":"Bulan"},"snapshot":{"display-name":"Snapshot","name":"snapshot","id":"2b52cf5b-9904-4c59-9114-009887121740","default":["Historical"],"type":"text","required":true}}}],"middleware":{"js-int-to-string?":true,"ignore-cached-results?":false,"userland-query?":true},"cache-strategy":null,"viz-settings":{"scalar.field":"rasio_slow_moving","scalar.segments":[{"min":0,"max":24,"color":"#689735","label":"Aman"},{"min":25,"max":59,"color":"#E8B921","label":"Waspada"},{"min":60,"max":100,"color":"#E3595E","label":"Kritis"}],"column_settings":{"[\"name\",\"rasio_slow_moving\"]":{"suffix":"%"}}},"database":2,"parameters":[{"type":"date/single","value":"2026-04-29","id":"8524b4ff","target":["variable",["template-tag","bulan"]]},{"type":"string/=","value":["Historical"],"id":"c2e57f55","target":["variable",["template-tag","snapshot"]]}]}');
INSERT INTO public.query VALUES ('\x9b3b727ca925adbf9b9f9fb21b4adaef3dd631c3bf4aec23da1bd5d91ebb363f', 77, '{"constraints":{"max-results":10000,"max-results-bare-rows":2000},"lib/type":"mbql/query","lib/metadata":null,"stages":[{"native":"SELECT\n  `kba_gold`.`gold_slow_moving`.`periode_bulanan` AS `Periode Bulanan`,\n  `kba_gold`.`gold_slow_moving`.`snapshot_type` AS `Snapshot Type`,\n  `kba_gold`.`gold_slow_moving`.`nama_produk` AS `Nama Produk`,\n  -- `kba_gold`.`gold_slow_moving`.`id_produk` AS `id_produk`,\n  `kba_gold`.`gold_slow_moving`.`nilai_stok` AS `Nilai Stok`,\n  CASE  \n  WHEN `kba_gold`.`gold_slow_moving`.`is_slow_moving` = 1 THEN ''Slow Moving''\n  WHEN `kba_gold`.`gold_slow_moving`.`is_slow_moving` = 0 THEN ''Non Slow Moving''\n  ELSE ''Unknown''\n  END AS `Status Slow Moving`,\n  `kba_gold`.`gold_slow_moving`.`demand_segment` AS `Demand Segment`,\n  `kba_gold`.`gold_slow_moving`.`slow_moving_reason` AS `slow_moving_reason`\n  \nFROM\n  `kba_gold`.`gold_slow_moving`\n-- WHERE {{bulan}} \nWHERE `periode_bulanan` = \nCOALESCE(\n    [[ toStartOfMonth(toDate({{bulan}})) , ]] \n    toStartOfMonth(now())\n  )\nAND `is_slow_moving` IN ({{Kategori}})\n  AND `snapshot_type` IN ({{Snapshot}})","lib/type":"mbql.stage/native","template-tags":{"Kategori":{"display-name":"Kategori","default":["1","0"],"name":"Kategori","id":"7387fc39-351e-4b7e-b826-6498be688002","type":"text","required":true},"Snapshot":{"name":"Snapshot","id":"53e8bd26-df0f-4517-a755-f32eec51dc92","default":["Historical"],"type":"text","display-name":"Snapshot","required":true},"bulan":{"type":"date","name":"bulan","id":"22c0d8f7-8cb5-4163-a3f9-094743fd3fc1","display-name":"Bulan"}}}],"middleware":{"js-int-to-string?":true,"ignore-cached-results?":false,"userland-query?":true},"cache-strategy":null,"viz-settings":{"table.column_formatting":[{"columns":["Demand Segment"],"type":"single","operator":"=","value":"frequent_small","color":"#A7D07C","highlight_row":false},{"columns":["Demand Segment"],