INSERT INTO public.query VALUES ('\xbbeb2c51816e5624529239d16989559ab420a8fbb8ee0b38298fabff6c6f6b1e', 85, '{"constraints":{"max-results":10000,"max-results-bare-rows":2000},"lib/type":"mbql/query","lib/metadata":null,"stages":[{"native":"SELECT\n  -- `periode_bulan` AS `periode_bulan`,\n  -- `vendor_otd_pct` AS `vendor_otd_pct`\n  *\nFROM\n  `kba_gold`.`gold_budget_adherence_vendor_otd`\n-- WHERE {{bulan}}\nWHERE `periode_bulan` <= \nCOALESCE(\n    [[ toStartOfMonth(toDate({{bulan}})) , ]] \n    toStartOfMonth(now())\n  ) \n  AND (\n    SELECT count(*) \n    FROM `kba_gold`.`gold_budget_adherence_vendor_otd` \n    WHERE `periode_bulan` = \n\tCOALESCE(\n    [[ toStartOfMonth(toDate({{bulan}})) , ]] \n    toStartOfMonth(now())\n  ) \n  ) > 0\nORDER BY `periode_bulan` ASC\n\n-- select date(now())","lib/type":"mbql.stage/native","template-tags":{"bulan":{"name":"bulan","id":"24ad855b-b71e-4c8c-835d-45291c9163f9","type":"date","display-name":"Bulan","default":null}}}],"middleware":{"js-int-to-string?":true,"ignore-cached-results?":false,"userland-query?":true},"cache-strategy":null,"viz-settings":{"scalar.comparisons":[{"id":"7dcd18ad-52db-979e-bde0-08256e452ac9","type":"staticNumber","label":"Target Vendor OTD","value":90},{"id":"bbcc1092-784c-0f5d-96e0-d282b9413c1c","type":"previousPeriod"}],"click_behavior":{"type":"link","linkType":"dashboard","targetId":6,"parameterMapping":{}},"table.cell_column":"vendor_otd_pct","progress.color":"#689636","gauge.segments":[{"min":0,"max":50,"color":"#E3595E","label":"Jauh dari Target"},{"min":50,"max":90,"color":"#E8B921","label":"Hampir Tercapai"},{"min":90,"max":100,"color":"#689735","label":"Target Tercapai"}],"progress.goal":90,"scalar.field":"vendor_otd_pct","table.pivot_column":"periode_bulan","column_settings":{"[\"name\",\"vendor_otd_pct\"]":{"suffix":"%"}}},"database":2,"parameters":[{"type":"date/single","value":"2026-03-30","id":"695f1b78","target":["variable",["template-tag","bulan"]]}]}');
