INSERT INTO public.query VALUES ('\x7a43eac5832f60242249c8a63125038c63bc6814b7939268526c274432a5d405', 29, '{"constraints":{"max-results":10000,"max-results-bare-rows":2000},"lib/type":"mbql/query","lib/metadata":null,"stages":[{"native":"SELECT\n  `kba_gold`.`gold_top_spending`.`periode_bulan` AS `periode_bulan`,\n  `kba_gold`.`gold_top_spending`.`rank_pengeluaran` AS `rank_pengeluaran`,\n  `kba_gold`.`gold_top_spending`.`demand_segment` AS `demand_segment`,\n  `kba_gold`.`gold_top_spending`.`id_produk` AS `id_produk`,\n  `kba_gold`.`gold_top_spending`.`nama_produk` AS `nama_produk`,\n  `kba_gold`.`gold_top_spending`.`total_pengeluaran_produk` AS `total_pengeluaran_produk`\n  \nFROM\n  `kba_gold`.`gold_top_spending`\nWHERE `periode_bulan` = \nCOALESCE(\n    [[ toStartOfMonth(toDate({{bulan}})) , ]] \n    toStartOfMonth(now())\n  )\nORDER BY\n  `kba_gold`.`gold_top_spending`.`rank_pengeluaran` ASC\nLIMIT\n  1048575","lib/type":"mbql.stage/native","template-tags":{"bulan":{"id":"ca1860c6-3cb4-4588-a5b6-27fdce33c515","type":"date","name":"bulan","display-name":"Bulan","required":false}}}],"middleware":{"js-int-to-string?":true,"ignore-cached-results?":false,"userland-query?":true},"cache-strategy":null,"viz-settings":{"graph.y_axis.title_text":"Total Pengeluaran","graph.show_values":true,"table.cell_column":"id_produk","graph.series_order_dimension":null,"graph.x_axis.title_text":"Nama Produk","graph.metrics":["total_pengeluaran_produk"],"graph.label_value_formatting":"compact","graph.series_order":null,"table.pivot_column":"periode_bulan","column_settings":{"[\"name\",\"rank_pengeluaran\"]":{"column_title":"Rank","number_separators":", "},"[\"name\",\"id_produk\"]":{"column_title":"ID Produk","number_separators":", "},"[\"name\",\"nama_produk\"]":{"column_title":"Nama Produk","text_wrapping":false},"[\"name\",\"total_pengeluaran_produk\"]":{"column_title":"Total Pengeluaran","number_separators":", ","prefix":"$"}},"series_settings":{"frequent_small":{"color":"#689636