INSERT INTO public.query VALUES ('\xd0a056d45eebfc0363fdb79b4b2ac008a0ddc98332ec310a519e2e911128adbc', 26, '{"constraints":{"max-results":10000,"max-results-bare-rows":2000},"lib/type":"mbql/query","lib/metadata":null,"stages":[{"native":"SELECT\n  `kba_gold`.`gold_vendor`.`periode_bulan` AS `periode_bulan`,\n  `kba_gold`.`gold_vendor`.`id_vendor` AS `id_vendor`,\n  `kba_gold`.`gold_vendor`.`nama_vendor` AS `nama_vendor`,\n  `kba_gold`.`gold_vendor`.`total_pengiriman` AS `total_pengiriman`,\n  `kba_gold`.`gold_vendor`.`tepat_waktu` AS `tepat_waktu`,\n  `kba_gold`.`gold_vendor`.`otd_pct` AS `otd_pct`\nFROM\n  `kba_gold`.`gold_vendor`\nWHERE `periode_bulan` = \nCOALESCE(\n    [[ toStartOfMonth(toDate({{bulan}})) , ]] \n    toStartOfMonth(now())\n  )\norder by otd_pct desc","lib/type":"mbql.stage/native","template-tags":{"bulan":{"display-name":"Bulan","id":"fd5402b5-cb4a-4a5f-9f24-2ed362ee20f3","type":"date","name":"bulan","default":"2026-04-02"}}}],"middleware":{"js-int-to-string?":true,"ignore-cached-results?":false,"userland-query?":true},"cache-strategy":null,"viz-settings":{"graph.y_axis.title_text":"Rata-rata OTD Rate (%)","graph.show_values":true,"graph.x_axis.title_text":"Nama Vendor","graph.label_value_frequency":"all","graph.metrics":["otd_pct"],"graph.label_value_formatting":"full","column_settings":{"[\"name\",\"otd_pct\"]":{"suffix":"%","number_separators":", "}},"series_settings":{"avg":{"color":"#227FD2"},"otd_pct":{"color":"#227FD2"}},"graph.x_axis.scale":"ordinal","graph.dimensions":["nama_vendor"]},"database":2,"parameters":[{"type":"date/single","value":"2026-05-02","id":"695f1b78","target":["variable",["template-tag","bulan"]]}]}');
INSERT INTO public.query VALUES ('\x07187c9d99fb21cca3389eff53122a593288ee51cec51bbecfb82c9974e95c2b', 25, '{"constraints":{"max-results":10000,"max-results-bare-rows":2000},"lib/type":"mbql/query","lib/metadata":null,"stages":[{"lib/type":"mbql.stage/native","native":"SELECT\n  `kba_gold`.`gold_sales_achievement_conversion`.`periode_bulan` AS `Periode Bulan`,\n   `total_quotation` as `Total Quotation`,\n   `aktual_penjualan` as `Penjualan Aktual`,\n  `kba_gold`.`gold_sales_achievement_conversion`.`conversion_rate` AS `Conversion Rate`\nFROM\n  `kba_gold`.`gold_sales_achievement_conversion`\nWHERE `periode_bulan` <= \nCOALESCE(\n    [[ toStartOfMonth(toDate({{bulan}})) , ]] \n    toStartOfMonth(now())\n  )\nORDER BY `periode_bulan` ASC","template-tags":{"bulan":{"id":"aa7d07b1-55d4-4a56-a53e-9236e979552b","type":"date","name":"bulan","display-name":"Bulan"}}}],"middleware":{"js-int-to-string?":true,"ignore-cached-results?":false,"userland-query?":true},"cache-strategy":null,"viz-settings":{"scalar.comparisons":[{"id":"a9dd4d47-179a-6adf-2403-8e3ff0deabf0","type":"staticNumber","label":"Target Conversion","value":70},{"id":"0ece0d52-a3b5-4928-dc43-ac4737c7e883","type":"previousValue"}],"graph.y_axis.title_text":"Value","graph.show_values":true,"progress.color":"#689636","graph.x_axis.title_text":"Periode","progress.goal":70,"graph.y_axis.labels_enabled":false,"graph.metrics":["Conversion Rate"],"graph.label_value_formatting":"compact","scalar.field":"conversion_rate","column_settings":{"[\"name\",\"Total Quotation\"]":{"prefix":"$"},"[\"name\",\"Penjualan Aktual\"]":{"prefix":"$"},"[\"name\",\"Conversion Rate\"]":{"number_separators":", ","suffix":"%"}},"series_settings":{"Total Quotation":{"display":"bar","color":"#87BCEC"},"Penjualan Aktual":{"display":"bar","color":"#F9D45C"},"Conversion Rate":{"line.size":"L","line.marker_enabled":null,"color":"#227FD2"}},"graph.x_axis.scale":"timeseries","graph.dimensions":["Periode Bulan"]},"database":2,"parameters":[{"type":"d