INSERT INTO public.query VALUES ('\x602c568aa67e0ff12918ef14646601445920b68638ae92e7edd28cb28e73dcaf', 56, '{"constraints":{"max-results":10000,"max-results-bare-rows":2000},"lib/type":"mbql/query","lib/metadata":null,"stages":[{"native":"SELECT\n  *\nFROM\n  `kba_gold`.`gold_product_performance`\nWHERE `periode_bulan` = \nCOALESCE(\n    [[ toStartOfMonth(toDate({{bulan}})) , ]] \n    toStartOfMonth(now())\n  ) AND total_sales > 0\nORDER BY total_sales DESC","lib/type":"mbql.stage/native","template-tags":{"bulan":{"id":"ac3057d7-f18d-4ab0-84a0-f758937158e3","type":"date","name":"bulan","display-name":"Bulan"}}}],"middleware":{"js-int-to-string?":true,"ignore-cached-results?":false,"process-viz-settings?":false,"userland-query?":true},"cache-strategy":null,"viz-settings":{"graph.y_axis.title_text":"Nilai","graph.show_values":true,"graph.series_order_dimension":null,"graph.x_axis.title_text":"Nama Produk","graph.y_axis.auto_split":false,"graph.metrics":["total_sales"],"graph.label_value_formatting":"compact","graph.series_order":null,"column_settings":{"[\"name\",\"total_sales\"]":{"number_separators":", ","prefix":"$"}},"series_settings":{"dead_stock":{"color":"#F7C41F"},"frequent_small":{"color":"#689636"},"awaiting_more_sales":{"color":"#EF8C8C"},"Total Sales":{"color":"#227FD2"},"total_sales":{"color":"#227FD2"},"(empty)":{"color":"#DCDFE0"},"balanced_regular":{"color":"#227FD2"},"rare_bulk":{"color":"#F2A86F"}},"graph.x_axis.scale":"ordinal","graph.dimensions":["nama_produk","demand_segment"],"stackable.stack_type":"stacked"},"database":2,"parameters":[{"id":"ac3057d7-f18d-4ab0-84a0-f758937158e3","type":"date/single","target":["variable",["template-tag","bulan"]],"value":"2026-04-28"}]}');
INSERT INTO public.query VALUES ('\xd7de7f431762cd17df98755b4d3a9464c7778cdebe709dc6ee7bfbdd50cfb4ba', 55, '{"constraints":{"max-results":10000,"max-results-bare-rows":2000},"lib/type":"mbql/query","lib/metadata":null,"stages":[{"lib/type":"mbql.stage/native","native":"SELECT\n  -- `kba_gold`.`gold_sales_achievement_conversion`.`periode_bulan` AS `periode_bulan`,\n  -- `kba_gold`.`gold_sales_achievement_conversion`.`conversion_rate` AS `conversion_rate`\n  *\nFROM\n  `kba_gold`.`gold_sales_achievement_conversion`\nWHERE `periode_bulan` <= \nCOALESCE(\n    [[ toStartOfMonth(toDate({{bulan}})) , ]] \n    toStartOfMonth(now())\n  )\nORDER BY `periode_bulan` ASC","template-tags":{"bulan":{"id":"d1e5b910-38b6-466c-b3b0-4c34d31f346a","type":"date","name":"bulan","display-name":"Bulan"}}}],"middleware":{"js-int-to-string?":true,"ignore-cached-results?":false,"userland-query?":true},"cache-strategy":null,"viz-settings":{"progress.goal":70,"progress.color":"#689636","scalar.field":"conversion_rate","scalar.comparisons":[{"id":"a9dd4d47-179a-6adf-2403-8e3ff0deabf0","type":"staticNumber","label":"Target Conversion","value":70},{"id":"0ece0d52-a3b5-4928-dc43-ac4737c7e883","type":"previousValue"}],"column_settings":{"[\"name\",\"conversion_rate\"]":{"suffix":"%"}},"click_behavior":{"parameterMapping":{"29b9c635":{"source":{"type":"parameter","id":"695f1b78","name":"Bulan"},"target":{"type":"parameter","id":"29b9c635"},"id":"29b9c635"}},"targetId":3,"linkType":"dashboard","type":"link"}},"database":2,"parameters":[{"type":"date/single","value":"2026-05-30","id":"695f1b78","target":["variable",["template-tag","bulan"]]}]}');
INSERT INTO public.query VALUES ('\x1f921d08cf6eb20c6da07de19b5c0496bbbec5ed05acdb5ace089e2061d2e0cd', 45, '{"constraints":{"max-results":10000,"max-results-bare-rows":2000},"lib/type":"mbql/query","lib/metadata":null,"stages":[{"native":"SELECT\n  -- `periode_bulan` AS `periode_bulan`,\n  -- `vendor_otd_pct` AS `vendor_otd_pct`\n  *\nFROM\n  `kba_gold`.`gold_budget_adherence_vendor_otd`\n-- WHERE {{bulan}}\nWHERE `periode_bulan` <= \nCOALESCE(\n    [[ toStartOfMonth(toDate({{bulan}})) , ]] \n    toStartOfMonth(now())\n  ) \n  AND (\n    SELECT count(*) \n    FROM `kba_gold`.`gold_budget_adherence_vendor_otd` \n    WHERE `periode_bulan` = \n\tCOALESCE(\n    [[ toStartOfMonth(toDate({{bulan}})) , ]] \n    toStartOfMonth(now())\n  ) \n  ) > 0\nORDER BY `periode_bulan` ASC\n\n-- select date(now())","lib/type":"mbql.stage/native","template-tags":{"bulan":{"name":"bulan","id":"24ad855b-b71e-4c8c-835d-45291c9163f9","type":"date","display-name":"Bulan","default":null}}}],"middleware":{"js-int-to-string?":true,"ignore-cached-results?":false,"userland-query?":true},"cache-strategy":null,"viz-settings":{"scalar.comparisons":[{"id":"7dcd18ad-52db-979e-bde0-08256e452ac9","type":"staticNumber","label":"Target Vendor OTD","value":90},{"id":"bbcc1092-784c-0f5d-96e0-d282b9413c1c","type":"previousPeriod"}],"click_behavior":{"parameterMapping":{"47291403":{"source":{"type":"parameter","id":"695f1b78","name":"Bulan"},"target":{"type":"parameter","id":"47291403"},"id":"47291403"}},"targetId":6,"linkType":"dashboard","type":"link"},"table.cell_column":"vendor_otd_pct","progress.color":"#689636","gauge.segments":[{"min":0,"max":50,"color":"#E3595E","label":"Jauh dari Target"},{"min":50,"max":90,"color":"#E8B921","label":"Hampir Tercapai"},{"min":90,"max":100,"color":"#689735","label":"Target Tercapai"}],"progress.goal":90,"scalar.field":"vendor_otd_pct","table.pivot_column":"periode_bulan","column_settings":{"[\"name\",\"vendor_otd_pct\"]":{"suffix":"%"}}},"database":2,"parameters":[{"type":"date/single","value":"2026-05-30","id":"695f1b78","target":["variable",["template-tag","bulan"]]}]}');
INSERT INTO public.query VALUES ('\xb5e76a265dbb3d5ef0af2f39fe4b68e3f8ea6190927bea69dde1f6ee2808f91f', 57, '{"constraints":{"max-results":10000,"max-results-bare-rows":2000},"lib/type":"mbql/query","lib/metadata":null,"stages":[{"lib/type":"mbql.stage/native","native":"SELECT\n  `periode_bulanan`,\n  SUM(CASE WHEN is_slow_moving = 1 THEN nilai_stok ELSE 0 END) AS total_stok_slow_moving,\n  SUM(nilai_stok) AS total_seluruh_stok,\n  SUM(CASE WHEN is_slow_moving = 1 THEN nilai_stok ELSE 0 END) * 100 / SUM(nilai_stok) AS rasio_slow_moving\nFROM\n  `kba_gold`.`gold_slow_moving`\nWHERE `periode_bulanan` = \nCOALESCE(\n    [[ toStartOfMonth(toDate({{bulan}})) , ]] \n    toStartOfMonth(now())\n  ) AND `snapshot_type` IN ({{snapshot}})\nGROUP BY `periode_bulanan`","template-tags":{"bulan":{"id":"17b918c5-2395-47b8-a273-7014a43feaa5","type":"date","name":"bulan","display-name":"Bulan"},"snapshot":{"display-name":"Snapshot","name":"snapshot","id":"2b52cf5b-9904-4c59-9114-009887121740","default":["Historical"],"type":"text","required":true}}}],"middleware":{"js-int-to-string?":true,"ignore-cached-results?":false,"userland-query?":true},"cache-strategy":null,"viz-settings":{"scalar.field":"rasio_slow_moving","scalar.segments":[{"min":0,"max":24,"color":"#689735","label":"Aman"},{"min":25,"max":59,"color":"#E8B921","label":"Waspada"},{"min":60,"max":100,"color":"#E3595E","label":"Kritis"}],"column_settings":{"[\"name\",\"rasio_slow_moving\"]":{"suffix":"%"}},"click_behavior":{"type":"link","linkType":"dashboard","targetId":7,"parameterMapping":{"b560239f":{"source":{"type":"parameter","id":"695f1b78","name":"Bulan"},"target":{"type":"parameter","id":"b560239f"},"id":"b560239f"},"8524b4ff":{"source":{"type":"parameter","id":"695f1b78","name":"Bulan"},"target":{"type":"parameter","id":"8524b4ff"},"id":"8524b4ff"}}}},"database":2,"parameters":[{"type":"date/single","value":"2026-05-30","id":"695f1b78","target":["variable",["template-tag","bulan"]]}]}');
INSERT INTO public.query VALUES ('\x74b155a426775e5858822dbfddec31b4495547b16d9daed038f33bb3a8cea87c', 53, '{"constraints":{"max-results":10000,"max-results-bare-rows":2000},"lib/type":"mbql/query","lib/metadata":null,"stages":[{"lib/type":"mbql.stage/native","native":"SELECT\n  -- `kba_gold`.`gold_sales_achievement_conversion`.`periode_bulan` AS `periode_bulan`,\n  -- `kba_gold`.`gold_sales_achievement_conversion`.`achievement_rate` AS `achievement_rate`\n  *\nFROM\n  `kba_gold`.`gold_sales_achievement_conversion`\nWHERE `periode_bulan` <= \nCOALESCE(\n    [[ toStartOfMonth(toDate({{bulan}})) , ]] \n    toStartOfMonth(now())\n  )\nORDER BY `periode_bulan` ASC","template-tags":{"bulan":{"display-name":"Bulan","type":"date","name":"bulan","id":"854961b7-4308-4671-9734-0569ba410d9e","default":null}}}],"middleware":{"js-int-to-string?":true,"ignore-cached-results?":false,"userland-query?":true},"cache-strategy":null,"viz-settings":{"progress.goal":100,"progress.color":"#689636","scalar.comparisons":[{"id":"cf85ad35-41ce-9ab7-85ef-9a43f7c84e28","type":"staticNumber","label":"Target Achievement","value":100},{"id":"bfdb6456-28a7-b6d3-b747-d34a1c693d9a","type":"previousValue"}],"scalar.switch_positive_negative":false,"scalar.compact_primary_number":true,"scalar.field":"achievement_rate","column_settings":{"[\"name\",\"achievement_rate\"]":{"suffix":"%","number_separators":", "}},"click_behavior":{"parameterMapping":{"a0d3ccfe":{"source":{"type":"parameter","id":"695f1b78","name":"Bulan"},"target":{"type":"parameter","id":"a0d3ccfe"},"id":"a0d3ccfe"}},"targetId":4,"linkType":"dashboard","type":"link"}},"database":2,"parameters":[{"type":"date/single","value":"2026-05-30","id":"695f1b78","target":["variable",["template-tag","bulan"]]}]}');
INSERT INTO public.query VALUES ('\x53836241e1aca8abdf34e56277231efe76351a425fc98e732539d111d1e53105', 65, '{"constraints":{"max-results":10000,"max-results-bare-rows":2000},"lib/type":"mbql/query","lib/metadata":null,"stages":[{"lib/type":"mbql.stage/native","native":"SELECT\n  `periode_bulanan`,\n  `snapshot_type`,\n  `source`.`is_slow_moving` AS `is_slow_moving`,\n  `source`.`count` AS `count`,\n  `source`.`count` AS `Jumlah Produk`\nFROM\n  (\n    SELECT\n\t  `periode_bulanan`,\n\t  `snapshot_type`,\n      FLOOR(\n        (\n          `kba_gold`.`gold_slow_moving`.`is_slow_moving` / 0.125\n        )\n      ) * 0.125 AS `is_slow_moving`,\n      COUNT(*) AS `count`\n    FROM\n      `kba_gold`.`gold_slow_moving`\n    GROUP BY\n\t  `periode_bulanan`,\n\t  `snapshot_type`,\n      FLOOR(\n        (\n          `kba_gold`.`gold_slow_moving`.`is_slow_moving` / 0.125\n        )\n      ) * 0.125\n    ORDER BY\n      FLOOR(\n        (\n          `kba_gold`.`gold_slow_moving`.`is_slow_moving` / 0.125\n        )\n      ) * 0.125 ASC\n  ) AS `source`\nWHERE `periode_bulanan` = \nCOALESCE(\n    [[ toStartOfMonth(toDate({{bulan}})) , ]] \n    toStartOfMonth(now())\n  ) AND `snapshot_type` = ''Historical''","template-tags":{"bulan":{"name":"bulan","id":"48db9bbd-7275-44f0-8540-56ef79f4ea38","type":"date","display-name":"Bulan","default":null}}}],"middleware":{"js-int-to-string?":true,"ignore-cached-results?":false,"userland-query?":true},"cache-strategy":null,"viz-settings":{"pie.rows":[{"key":"1","name":"Slow Moving","originalName":"1","color":"#F7C41F","defaultColor":false,"enabled":true,"hidden":false,"isOther":false},{"key":"0","name":"Non Slow Moving","originalName":"0","color":"#227FD2","defaultColor":false,"enabled":true,"hidden":false,"isOther":false},{"isOther":false,"hidden":true,"enabled":false,"defaultColor":true,"color":"#509EE3","originalName":"Three-Seat Sofa","name":"Three-Seat Sofa","key":"Three-Seat Sofa"},{"key":"Office Chair","name":"Office Chair","originalNam