INSERT INTO public.query VALUES ('\xc7ddfc10ce9926548c134af2159894e1f22a61bf38baca6e5817defce47596d0', 40, '{"constraints":{"max-results":10000,"max-results-bare-rows":2000},"lib/type":"mbql/query","lib/metadata":null,"stages":[{"native":"SELECT\n  `kba_gold`.`gold_slow_moving`.`periode_bulanan` AS `Periode Bulan`,\n  `kba_gold`.`gold_slow_moving`.`id_produk` AS `ID Produk`,\n  `kba_gold`.`gold_slow_moving`.`snapshot_type` AS `Tipe Snapshot`,\n  `kba_gold`.`gold_slow_moving`.`nama_produk` AS `Nama Produk`,\n  `kba_gold`.`gold_slow_moving`.`nilai_stok` AS `Nilai Stok`,\n  `kba_gold`.`gold_slow_moving`.`demand_segment` AS `demand_segment`,\n  `kba_gold`.`gold_slow_moving`.`is_slow_moving` AS `is_slow_moving`,\n  `kba_gold`.`gold_slow_moving`.`slow_moving_reason` AS `slow_moving_reason`\nFROM\n  `kba_gold`.`gold_slow_moving`\nWHERE `periode_bulanan` = \nCOALESCE(\n    [[ toStartOfMonth(toDate({{bulan}})) , ]] \n    toStartOfMonth(now())\n  ) AND `is_slow_moving` IN ({{Kategori}})\n  AND `snapshot_type` IN ({{Snapshot}})\nORDER BY nilai_stok desc","lib/type":"mbql.stage/native","template-tags":{"bulan":{"id":"bdf2f4c2-d859-4583-8964-3eda0a430770","type":"date","name":"bulan","display-name":"Bulan"},"Kategori":{"name":"Kategori","id":"602bff62-d74c-4905-8389-6ffc2d7ccc2a","default":["1"],"type":"text","display-name":"Kategori","required":true},"Snapshot":{"id":"50e13fca-c7df-4123-bac4-165c3a4221cc","type":"text","display-name":"Snapshot","name":"Snapshot","default":["Real-time"]}}}],"middleware":{"js-int-to-string?":true,"ignore-cached-results?":false,"userland-query?":true},"cache-strategy":null,"viz-settings":{"graph.show_values":true,"table.cell_column":"id_produk","graph.series_order_dimension":null,"graph.metrics":["Nilai Stok"],"graph.label_value_formatting":"compact","graph.series_order":null,"table.pivot_column":"periode_bulanan","column_settings":{"[\"name\",\"Nilai Stok\"]":{"number_separators":", ","prefix":"$"}},"series_settings":{"awaiting_more_sales":{"colo