INSERT INTO public.report_card VALUES (40, '2026-04-27 02:34:28.180631+00', '2026-04-27 03:00:46.861599+00', 'Vendor Otd Rate', 'Vendor Otd, Filtered by P.periode Bulan is in the previous 30 days', 'progress', '{"lib/type":"mbql/query","stages":[{"lib/type":"mbql.stage/native","native":"SELECT\n  `kba_gold`.`gold_budget_adherence_vendor_otd`.`p.periode_bulan` AS `p.periode_bulan`,\n  `kba_gold`.`gold_budget_adherence_vendor_otd`.`vendor_otd_pct` AS `vendor_otd_pct`\nFROM\n  `kba_gold`.`gold_budget_adherence_vendor_otd`\nWHERE\n  `kba_gold`.`gold_budget_adherence_vendor_otd`.`p.periode_bulan` {{bulan}}","template-tags":{"bulan":{"display-name":"Bulan","default":"2026-04","name":"bulan","dimension":["field",{"lib/uuid":"57f1ab0a-f31b-47dc-9780-db17c1c51e89"},411],"id":"5ea7f3e0-f9c8-4725-beb7-506cbc079000","widget-type":"date/month-year","type":"dimension","required":true}}}],"database":2}', '{"progress.goal":90,"progress.color":"#689636","column_settings":{"[\"name\",\"vendor_otd_pct\"]":{"prefix":"","suffix":"%"}}}', 1, 2, 22, 'native', true, 4, NULL, NULL, false, NULL, NULL, '[{"name":"v_0","database_type":"Nothing","base_type":"type/*","display_name":"v_0","field_ref":["field","v_0",{"base-type":"type/*"}]},{"name":"v_1","database_type":"Nothing","base_type":"type/*","display_name":"v_1","field_ref":["field","v_1",{"base-type":"type/*"}]}]', NULL, 'tJ4ebUPKQK7eF_Xg3O18V', '[{"id":"5ea7f3e0-f9c8-4725-beb7-506cbc079000","type":"date/month-year","target":["dimension",["template-tag","bulan"]],"name":"Bulan","slug":"bulan","default":"2026-04","required":true,"isMultiSelect":true}]', '[]', true, 'v0.59.4 (d4fb593)', 'question', NULL, '2026-04-27 03:00:46.862897+00', '2026-04-27 03:00:38.708957+00', 9, true, NULL, NULL, NULL, 23, NULL, 0, NULL, NULL);
INSERT INTO public.report_card VALUES (106, '2026-04-28 13:12:35.891206+00', '2026-04-28 13:12:35.891206+00', 'Slow Moving Composition', 'Jumlah produk dengan kategori stok slow moving dan non slow moving', 'pie', '{"lib/type":"mbql/query","database":2,"stages":[{"native":"SELECT\n  `periode_bulanan`,\n  `source`.`is_slow_moving` AS `is_slow_moving`,\n  `source`.`count` AS `count`,\n  `source`.`count` AS `Jumlah Produk`\nFROM\n  (\n    SELECT\n\t  `periode_bulanan`,\n      FLOOR(\n        (\n          `kba_gold`.`gold_slow_moving`.`is_slow_moving` / 0.125\n        )\n      ) * 0.125 AS `is_slow_moving`,\n      COUNT(*) AS `count`\n    FROM\n      `kba_gold`.`gold_slow_moving`\n    GROUP BY\n\t  `periode_bulanan`,\n      FLOOR(\n        (\n          `kba_gold`.`gold_slow_moving`.`is_slow_moving` / 0.125\n        )\n      ) * 0.125\n    ORDER BY\n      FLOOR(\n        (\n          `kba_gold`.`gold_slow_moving`.`is_slow_moving` / 0.125\n        )\n      ) * 0.125 ASC\n  ) AS `source`\nWHERE `periode_bulanan` = \nCOALESCE(\n    [[ toStartOfMonth(toDate({{bulan}})) , ]] \n    toStartOfMonth(now())\n  )","lib/type":"mbql.stage/native","template-tags":{"bulan":{"id":"48db9bbd-7275-44f0-8540-56ef79f4ea38","type":"date","display-name":"Bulan","name":"bulan","default":null}}}]}', '{"pie.rows":[{"key":"1","name":"Slow Moving","originalName":"1","color":"#F7C41F","defaultColor":false,"enabled":true,"hidden":false,"isOther":false},{"key":"0","name":"Non Slow Moving","originalName":"0","color":"#227FD2","defaultColor":false,"enabled":true,"hidden":false,"isOther":false},{"isOther":false,"hidden":true,"enabled":false,"defaultColor":true,"color":"#509EE3","originalName":"Three-Seat Sofa","name":"Three-Seat Sofa","key":"Three-Seat Sofa"},{"key":"Office Chair","name":"Office Chair","originalName":"Office Chair","color":"#87BCEC","defaultColor":true,"enabled":true,"hidden":true,"isOther":false},{"key":"Office Lamp","name":"Office Lamp","originalName":"Office Lamp","color":"#227FD2","d