INSERT INTO public.report_card VALUES (115, '2026-04-28 13:13:14.889176+00', '2026-04-28 13:13:14.889176+00', 'Product Sales and Inventory Value', 'Nilai stok dan total sales produk, diurutkan berdasarkan total sales tertinggi', 'row', '{"lib/type":"mbql/query","database":2,"stages":[{"lib/type":"mbql.stage/native","native":"SELECT\n  `periode_bulan`,\n  `source`.`nama_produk` AS `nama_produk`,\n  `source`.`sum` AS `sum`,\n  `source`.`sum_2` AS `sum_2`,\n  `source`.`sum` AS `Total Sales`,\n  `source`.`sum_2` AS `Total Nilai Stok`\nFROM\n  (\n    SELECT\n\t  `periode_bulan`,\n      `kba_gold`.`gold_product_performance`.`nama_produk` AS `nama_produk`,\n      SUM(\n        `kba_gold`.`gold_product_performance`.`total_sales`\n      ) AS `sum`,\n      SUM(\n        `kba_gold`.`gold_product_performance`.`nilai_stok`\n      ) AS `sum_2`\n    FROM\n      `kba_gold`.`gold_product_performance`\n\t  WHERE `periode_bulan` = \nCOALESCE(\n    [[ toStartOfMonth(toDate({{bulan}})) , ]] \n    toStartOfMonth(now())\n  ) \n    GROUP BY\n\t  `periode_bulan`,\n      `kba_gold`.`gold_product_performance`.`nama_produk`\n    ORDER BY\n      `kba_gold`.`gold_product_performance`.`nama_produk` ASC\n  ) AS `source`\nORDER BY\n  `source`.`sum` DESC\n\n","template-tags":{"bulan":{"id":"f4fe689f-e31c-456d-a46d-9f0c6e4d30b2","type":"date","name":"bulan","display-name":"Bulan"}}}]}', '{"graph.y_axis.title_text":"Nilai","graph.show_values":true,"graph.x_axis.title_text":"Nama Produk","graph.y_axis.auto_split":false,"graph.metrics":["Total Sales","Total Nilai Stok"],"graph.label_value_formatting":"compact","column_settings":{"[\"name\",\"sum\"]":{"column_title":"Total Nilai Stok"},"[\"name\",\"Total Sales\"]":{"number_separators":", ","prefix":"$"},"[\"name\",\"Total Nilai Stok\"]":{"number_separators":", ","prefix":"$"}},"series_settings":{"Total Sales":{"color":"#F7C41F","display":"bar"},"Total Nilai Stok":{"color":"#227FD2"}},"graph.x_axis.scale":"ordinal","graph.dimensions":["nama_produk"],"stac