INSERT INTO public.report_card VALUES (72, '2026-04-27 12:01:38.927902+00', '2026-04-28 13:06:15.946226+00', 'Product Sales and Inventory Value', 'Nilai stok dan total sales produk, diurutkan berdasarkan total sales tertinggi', 'row', '{"lib/type":"mbql/query","database":2,"stages":[{"native":"SELECT\n  `periode_bulan`,\n  `source`.`nama_produk` AS `nama_produk`,\n  `source`.`sum` AS `sum`,\n  `source`.`sum_2` AS `sum_2`,\n  `source`.`sum` AS `Total Sales`,\n  `source`.`sum_2` AS `Total Nilai Stok`\nFROM\n  (\n    SELECT\n\t  `periode_bulan`,\n      `kba_gold`.`gold_product_performance`.`nama_produk` AS `nama_produk`,\n      SUM(\n        `kba_gold`.`gold_product_performance`.`total_sales`\n      ) AS `sum`,\n      SUM(\n        `kba_gold`.`gold_product_performance`.`nilai_stok`\n      ) AS `sum_2`\n    FROM\n      `kba_gold`.`gold_product_performance`\n\t  WHERE `periode_bulan` = \nCOALESCE(\n    [[ toStartOfMonth(toDate({{bulan}})) , ]] \n    toStartOfMonth(now())\n  ) \n    GROUP BY\n\t  `periode_bulan`,\n      `kba_gold`.`gold_product_performance`.`nama_produk`\n    ORDER BY\n      `kba_gold`.`gold_product_performance`.`nama_produk` ASC\n  ) AS `source`\nORDER BY\n  `source`.`sum` DESC\n\n","lib/type":"mbql.stage/native","template-tags":{"bulan":{"type":"date","name":"bulan","id":"f4fe689f-e31c-456d-a46d-9f0c6e4d30b2","display-name":"Bulan"}}}]}', '{"graph.y_axis.title_text":"Nilai","graph.show_values":true,"graph.x_axis.title_text":"Nama Produk","graph.y_axis.auto_split":false,"graph.metrics":["Total Sales","Total Nilai Stok"],"graph.label_value_formatting":"compact","column_settings":{"[\"name\",\"sum\"]":{"column_title":"Total Nilai Stok"},"[\"name\",\"Total Sales\"]":{"number_separators":", ","prefix":"$"},"[\"name\",\"Total Nilai Stok\"]":{"number_separators":", ","prefix":"$"}},"series_settings":{"Total Sales":{"color":"#F7C41F","display":"bar"},"Total Nilai Stok":{"color":"#227FD2"}},"graph.x_axis.scale":"ordinal","graph.dimensions":["nama_produk"],"stackable.stack_type":"stacked"}', 1, 2, 42, 'native', false, 4, NULL, NULL, false, NULL, NULL, '[{"database_type":"Date","semantic_type":null,"lib/deduplicated-name":"periode_bulan","lib/original-name":"periode_bulan","name":"periode_bulan","lib/source":"source/native","lib/source-column-alias":"periode_bulan","source":"native","field_ref":["field","periode_bulan",{"base-type":"type/Date"}],"effective_type":"type/Date","lib/desired-column-alias":"periode_bulan","display_name":"periode_bulan","fingerprint":{"global":{"distinct-count":1,"nil%":0.0},"type":{"type/DateTime":{"earliest":"2026-04-01","latest":"2026-04-01"}}},"base_type":"type/Date"},{"database_type":"Nullable(String)","semantic_type":null,"lib/deduplicated-name":"nama_produk","lib/original-name":"nama_produk","name":"nama_produk","lib/source":"source/native","lib/source-column-alias":"nama_produk","source":"native","field_ref":["field","nama_produk",{"base-type":"type/Text"}],"effective_type":"type/Text","lib/desired-column-alias":"nama_produk","display_name":"nama_produk","fingerprint":{"global":{"distinct-count":29,"nil%":0.0},"type":{"type/Text":{"percent-json":0.0,"percent-url":0.0,"percent-email":0.0,"percent-state":0.0,"average-length":13.241379310344827}}},"base_type":"type/Text"},{"database_type":"Float64","semantic_type":null,"lib/deduplicated-name":"sum","lib/original-name":"sum","name":"sum","lib/source":"source/native","lib/source-column-alias":"sum","source":"native","field_ref":["field","sum",{"base-type":"type/Float"}],"effective_type":"type/Float","lib/desired-column-alias":"sum","display_name":"sum","fingerprint":{"global":{"distinct-count":12,"nil%":0.0},"type":{"type/Number":{"min":0.0,"q1":0.0,"q3":2249.5,"max":42200.0,"sd":8205.498269325659,"avg":2979.4827586206898}}},"base_type":"type/Float"},{"database_type":"Float64","semantic_type":null,"lib/deduplicated-name":"sum_2","lib/original-name":"sum_2","name":"sum_2","lib/source":"source/native","lib/source-column-alias":"sum_2","source":"na