INSERT INTO public.report_card VALUES (89, '2026-04-28 08:35:50.195457+00', '2026-05-09 05:09:51.739323+00', 'Slow Moving vs Sales', 'Produk slow moving dipetakan menurut total penjualan dan nilai stoknya. Bubble besar yang berada di bawah adalah stok slow moving dengan nilai inventory tinggi.', 'scatter', '{"lib/type":"mbql/query","database":2,"stages":[{"native":"SELECT\n  `kba_gold`.`gold_product_performance`.`periode_bulan` AS `periode_bulan`,\n  `kba_gold`.`gold_product_performance`.`id_produk` AS `id_produk`,\n  `kba_gold`.`gold_product_performance`.`nama_produk` AS `nama_produk`,\n  `kba_gold`.`gold_product_performance`.`total_sales` AS `total_sales`,\n  `kba_gold`.`gold_product_performance`.`total_qty` AS `total_qty`,\n  `kba_gold`.`gold_product_performance`.`nilai_stok` AS `nilai_stok`,\n  `kba_gold`.`gold_product_performance`.`is_slow_moving_flag` AS `is_slow_moving_flag`\nFROM\n  `kba_gold`.`gold_product_performance`\nwhere `is_slow_moving_flag` IN ({{kategori}})\nAND `periode_bulan` = \nCOALESCE(\n    [[ toStartOfMonth(toDate({{bulan}})) , ]] \n    toStartOfMonth(now())\n  )","lib/type":"mbql.stage/native","template-tags":{"bulan":{"id":"998ddd19-22af-4c09-a5fa-f20f481254d5","type":"date","name":"bulan","display-name":"Bulan"},"kategori":{"required":false,"type":"text","name":"kategori","id":"73f15e6d-6a97-4fbf-9553-ec4bc3de7440","display-name":"Kategori","default":["1"]}}}]}', '{"graph.y_axis.title_text":"Total Penjualan","scatter.bubble":"nilai_stok","graph.series_order_dimension":null,"graph.x_axis.title_text":"Nama Produk","graph.metrics":["total_sales"],"graph.series_order":null,"column_settings":{"[\"name\",\"total_sales\"]":{"number_separators":", ","prefix":"$"}},"series_settings":{"total_sales":{"color":"#227FD2"}},"graph.x_axis.scale":"ordinal","graph.dimensions":["nama_produk"]}', 1, 2, NULL, 'native', false, 4, NULL, NULL, false, NULL, NULL, '[{"database_type":"Date","semantic_type":null,"lib/deduplicated-name":"periode_bulan","lib/original-n