INSERT INTO public.report_card VALUES (62, '2026-04-27 07:58:24.646106+00', '2026-05-06 06:17:53.993797+00', 'Slow Moving Value', 'Nilai/value total stok dengan kategori slow moving', 'scalar', '{"lib/type":"mbql/query","database":2,"stages":[{"native":"SELECT\n  `periode_bulanan`,\n  SUM(CASE WHEN is_slow_moving = 1 THEN nilai_stok ELSE 0 END) AS total_stok_slow_moving,\n  SUM(nilai_stok) AS total_seluruh_stok,\n  SUM(CASE WHEN is_slow_moving = 1 THEN nilai_stok ELSE 0 END) * 100 / SUM(nilai_stok) AS rasio_slow_moving\nFROM\n  `kba_gold`.`gold_slow_moving`\nWHERE `periode_bulanan` = \nCOALESCE(\n    [[ toStartOfMonth(toDate({{bulan}})) , ]] \n    toStartOfMonth(now())\n  ) AND `snapshot_type` IN ({{snapshot}})\nGROUP BY `periode_bulanan`","lib/type":"mbql.stage/native","template-tags":{"bulan":{"type":"date","name":"bulan","id":"17b918c5-2395-47b8-a273-7014a43feaa5","display-name":"Bulan"},"snapshot":{"name":"snapshot","id":"2b52cf5b-9904-4c59-9114-009887121740","default":["Historical"],"type":"text","display-name":"Snapshot","required":true}}}]}', '{"scalar.field":"rasio_slow_moving","scalar.segments":[{"min":0,"max":24,"color":"#689735","label":"Aman"},{"min":25,"max":59,"color":"#E8B921","label":"Waspada"},{"min":60,"max":100,"color":"#E3595E","label":"Kritis"}],"column_settings":{"[\"name\",\"rasio_slow_moving\"]":{"suffix":"%"}}}', 1, 2, NULL, 'native', false, 4, NULL, NULL, false, NULL, NULL, '[{"database_type":"Date","semantic_type":null,"lib/deduplicated-name":"periode_bulanan","lib/original-name":"periode_bulanan","name":"periode_bulanan","lib/source":"source/native","lib/source-column-alias":"periode_bulanan","source":"native","field_ref":["field","periode_bulanan",{"base-type":"type/Date"}],"effective_type":"type/Date","lib/desired-column-alias":"periode_bulanan","display_name":"periode_bulanan","fingerprint":{"global":{"distinct-count":1,"nil%":0.0},"type":{"type/DateTime":{"earliest":"2026-04-01","latest":"2026-04-01"}}},"base_type":"type/Date"},{"data