INSERT INTO public.revision VALUES (216, 'Card', 73, 1, '2026-04-28 00:23:08.085126+00', '{"description":"Top spending bulan ini","archived":false,"collection_position":null,"source_card_id":null,"table_id":null,"embedding_type":null,"dependency_analysis_version":0,"card_schema":23,"database_id":2,"enable_embedding":false,"collection_id":4,"query_type":"native","name":"Top Spending","type":"question","embedding_params":null,"cache_ttl":null,"dataset_query":{"lib/type":"mbql/query","database":2,"stages":[{"native":"SELECT\n  `kba_gold`.`gold_top_spending`.`periode_bulan` AS `periode_bulan`,\n  `kba_gold`.`gold_top_spending`.`rank_pengeluaran` AS `rank_pengeluaran`,\n  `kba_gold`.`gold_top_spending`.`id_produk` AS `id_produk`,\n  `kba_gold`.`gold_top_spending`.`nama_produk` AS `nama_produk`,\n  `kba_gold`.`gold_top_spending`.`total_pengeluaran_produk` AS `total_pengeluaran_produk`\n  \nFROM\n  `kba_gold`.`gold_top_spending`\nWHERE `periode_bulan` = \nCOALESCE(\n    [[ toStartOfMonth(toDate({{bulan}})) , ]] \n    toStartOfMonth(now())\n  )\nORDER BY\n  `kba_gold`.`gold_top_spending`.`rank_pengeluaran` ASC\nLIMIT\n  1048575","lib/type":"mbql.stage/native","template-tags":{"bulan":{"name":"bulan","display-name":"Bulan","id":"ca1860c6-3cb4-4588-a5b6-27fdce33c515","type":"date","required":false}}}]},"parameter_mappings":[],"display":"row","archived_directly":false,"collection_preview":true,"visualization_settings":{"graph.y_axis.title_text":"Total Pengeluaran","graph.show_values":true,"table.cell_column":"id_produk","graph.series_order_dimension":null,"graph.x_axis.title_text":"Nama Produk","graph.metrics":["total_pengeluaran_produk"],"graph.label_value_formatting":"compact","graph.series_order":null,"table.pivot_column":"periode_bulan","column_settings":{"[\"name\",\"rank_pengeluaran\"]":{"column_title":"Rank","number_separators":", "},"[\"name\",\"id_produk\"]":{"column_title":"ID Produk","number_separators":", "},"[\"name\",\"nama_produk\"]":{"column_title":"Nama Produk","text_wrapping":false},"[\"name\",\"total_pengeluaran_produk\"]":{"column_title":"Total Pengeluaran","number_separators":", ","prefix":"$"}},"series_settings":{"total_pengeluaran_produk":{"color":"#227FD2"}},"graph.dimensions":["nama_produk"]},"parameters":[{"id":"ca1860c6-3cb4-4588-a5b6-27fdce33c515","type":"date/single","target":["variable",["template-tag","bulan"]],"name":"Bulan","slug":"bulan","required":false,"isMultiSelect":false}],"dashboard_id":null}', false, false, NULL, false, 'v0.59.4 (d4fb593)');
