INSERT INTO public.revision VALUES (186, 'Card', 60, 1, '2026-04-27 12:45:47.981805+00', '{"description":"Vendor OTD Rate","archived":false,"collection_position":null,"source_card_id":null,"table_id":null,"embedding_type":null,"dependency_analysis_version":0,"card_schema":23,"database_id":2,"enable_embedding":false,"collection_id":4,"query_type":"native","name":"Vendor OTD Rate","type":"question","embedding_params":null,"cache_ttl":null,"dataset_query":{"lib/type":"mbql/query","database":2,"stages":[{"native":"-- SELECT\n--   `periode_bulan` AS `periode_bulan`,\n--   `vendor_otd_pct` AS `vendor_otd_pct`\n-- FROM\n--   `kba_gold`.`gold_budget_adherence_vendor_otd`\n-- WHERE\n--   (\n--     `periode_bulan` >= `toStartOfMonth`((`now64`(9) + INTERVAL -1 month))\n--   )\n\n\nSELECT\n  -- `periode_bulan` AS `periode_bulan`,\n  -- `vendor_otd_pct` AS `vendor_otd_pct`\n  *\nFROM\n  `kba_gold`.`gold_budget_adherence_vendor_otd`\n-- WHERE {{bulan}}\nWHERE `periode_bulan` <= \nCOALESCE(\n    [[ toStartOfMonth(toDate({{bulan}})) , ]] \n    toStartOfMonth(now())\n  )\nORDER BY `periode_bulan` ASC\n\n-- select date(now())","lib/type":"mbql.stage/native","template-tags":{"bulan":{"id":"24ad855b-b71e-4c8c-835d-45291c9163f9","type":"date","name":"bulan","display-name":"Bulan"}}}]},"parameter_mappings":[],"display":"smartscalar","archived_directly":false,"collection_preview":true,"visualization_settings":{"table.pivot_column":"periode_bulan","table.cell_column":"vendor_otd_pct","progress.goal":90,"progress.color":"#689636","gauge.segments":[{"min":0,"max":50,"color":"#E3595E","label":"Jauh dari Target"},{"min":50,"max":90,"color":"#E8B921","label":"Hampir Tercapai"},{"min":90,"max":100,"color":"#689735","label":"Target Tercapai"}],"scalar.field":"vendor_otd_pct","scalar.comparisons":[{"id":"7dcd18ad-52db-979e-bde0-08256e452ac9","type":"staticNumber","label":"Target Vendor OTD","value":90},{"id":"bbcc1092-784c-0f5d-96e0-d282b9413c1c","type":"previousPeriod"}],"column_settings":{"[\"na