INSERT INTO public.revision VALUES (204, 'Card', 73, 1, '2026-04-28 00:10:16.502628+00', '{"description":"Top spending bulan ini","archived":false,"collection_position":null,"source_card_id":null,"table_id":null,"embedding_type":null,"dependency_analysis_version":0,"card_schema":23,"database_id":2,"enable_embedding":false,"collection_id":4,"query_type":"native","name":"Top Spending","type":"question","embedding_params":null,"cache_ttl":null,"dataset_query":{"lib/type":"mbql/query","database":2,"stages":[{"lib/type":"mbql.stage/native","native":"SELECT\n  `kba_gold`.`gold_top_spending`.`periode_bulan` AS `periode_bulan`,\n  `kba_gold`.`gold_top_spending`.`id_produk` AS `id_produk`,\n  `kba_gold`.`gold_top_spending`.`nama_produk` AS `nama_produk`,\n  `kba_gold`.`gold_top_spending`.`total_pengeluaran_produk` AS `total_pengeluaran_produk`,\n  `kba_gold`.`gold_top_spending`.`rank_pengeluaran` AS `rank_pengeluaran`\nFROM\n  `kba_gold`.`gold_top_spending`\nWHERE\n  (\n    `kba_gold`.`gold_top_spending`.`periode_bulan` = `toStartOfMonth`({{bulan}})\n  )\nORDER BY\n  `kba_gold`.`gold_top_spending`.`rank_pengeluaran` ASC\nLIMIT\n  1048575","template-tags":{"bulan":{"display-name":"Bulan","id":"ca1860c6-3cb4-4588-a5b6-27fdce33c515","type":"date","name":"bulan","required":false}}}]},"parameter_mappings":[],"display":"table","archived_directly":false,"collection_preview":true,"visualization_settings":{"table.pivot_column":"periode_bulan","table.cell_column":"id_produk"},"parameters":[{"id":"ca1860c6-3cb4-4588-a5b6-27fdce33c515","type":"date/single","target":["variable",["template-tag","bulan"]],"name":"Bulan","slug":"bulan","required":false,"isMultiSelect":false}],"dashboard_id":null}', false, true, NULL, false, 'v0.59.4 (d4fb593)');
