INSERT INTO public.revision VALUES (120, 'Card', 64, 1, '2026-04-27 10:46:57.277714+00', '{"description":null,"archived":false,"collection_position":null,"source_card_id":null,"table_id":null,"embedding_type":null,"dependency_analysis_version":0,"card_schema":23,"database_id":2,"enable_embedding":false,"collection_id":4,"query_type":"native","name":"Sales Conversion Rate - Tren","type":"question","embedding_params":null,"cache_ttl":null,"dataset_query":{"lib/type":"mbql/query","database":2,"stages":[{"lib/type":"mbql.stage/native","native":"SELECT\n  `kba_gold`.`gold_sales_achievement_conversion`.`periode_bulan` AS `periode_bulan`,\n  `kba_gold`.`gold_sales_achievement_conversion`.`conversion_rate` AS `conversion_rate`\nFROM\n  `kba_gold`.`gold_sales_achievement_conversion`\n-- WHERE {{bulan}}\nORDER BY `periode_bulan` ASC"}]},"parameter_mappings":[],"display":"line","archived_directly":false,"collection_preview":true,"visualization_settings":{"scalar.comparisons":[{"id":"a9dd4d47-179a-6adf-2403-8e3ff0deabf0","type":"staticNumber","label":"Target Conversion","value":70},{"id":"0ece0d52-a3b5-4928-dc43-ac4737c7e883","type":"previousValue"}],"graph.y_axis.title_text":"Value","progress.color":"#689636","graph.x_axis.title_text":"Periode","progress.goal":70,"graph.metrics":["conversion_rate"],"scalar.field":"conversion_rate","column_settings":{"[\"name\",\"conversion_rate\"]":{"suffix":"%"}},"series_settings":{"conversion_rate":{"color":"#227FD2"}},"graph.x_axis.scale":"timeseries","graph.dimensions":["periode_bulan"]},"parameters":[],"dashboard_id":null}', false, true, NULL, false, 'v0.59.4 (d4fb593)');
INSERT INTO public.revision VALUES (275, 'Card', 71, 1, '2026-04-28 04:27:57.921926+00', '{"description":"Jumlah produk dengan kategori stok slow moving dan non slow moving","archived":false,"collection_position":null,"source_card_id":null,"table_id":37,"embedding_type":null,"dependency_analysis_version":0,"card_schema":23,"database_id":2,"enable_embedding":false,"collection_id":4,"query_type":"native","name":"Slow Moving Composition","type":"question","embedding_params":null,"cache_ttl":null,"dataset_query":{"lib/type":"mbql/query","database":2,"stages":[{"lib/type":"mbql.stage/native","native":"SELECT\n  `periode_bulanan`,\n  `source`.`is_slow_moving` AS `is_slow_moving`,\n  `source`.`count` AS `count`,\n  `source`.`count` AS `Jumlah Produk`\nFROM\n  (\n    SELECT\n\t  `periode_bulanan`,\n      FLOOR(\n        (\n          `kba_gold`.`gold_slow_moving`.`is_slow_moving` / 0.125\n        )\n      ) * 0.125 AS `is_slow_moving`,\n      COUNT(*) AS `count`\n    FROM\n      `kba_gold`.`gold_slow_moving`\n    GROUP BY\n\t  `periode_bulanan`,\n      FLOOR(\n        (\n          `kba_gold`.`gold_slow_moving`.`is_slow_moving` / 0.125\n        )\n      ) * 0.125\n    ORDER BY\n      FLOOR(\n        (\n          `kba_gold`.`gold_slow_moving`.`is_slow_moving` / 0.125\n        )\n      ) * 0.125 ASC\n  ) AS `source`\nWHERE `periode_bulanan` = \nCOALESCE(\n    [[ toStartOfMonth(toDate({{bulan}})) , ]] \n    toStartOfMonth(now())\n  )","template-tags":{"bulan":{"id":"48db9bbd-7275-44f0-8540-56ef79f4ea38","type":"date","display-name":"Bulan","name":"bulan","default":"2026-03-30"}}}]},"parameter_mappings":[],"display":"pie","archived_directly":false,"collection_preview":true,"visualization_settings":{"pie.rows":[{"key":"1","name":"Slow Moving","originalName":"1","color":"#F7C41F","defaultColor":false,"enabled":true,"hidden":false,"isOther":false},{"key":"0","name":"Non Slow Moving","originalName":"0","color":"#227FD2","defaultColor":false,"enabled":true,"hidden":false,"isOther":fal