INSERT INTO public.revision VALUES (334, 'Card', 72, 1, '2026-04-28 06:22:02.558052+00', '{"description":"Perbandingan nilai stok dan sales produk, diurutkan berdasarkan total nilai stok tertinggi","archived":false,"collection_position":null,"source_card_id":null,"table_id":42,"embedding_type":null,"dependency_analysis_version":0,"card_schema":23,"database_id":2,"enable_embedding":false,"collection_id":4,"query_type":"native","name":"Product Sales and Inventory Value","type":"question","embedding_params":null,"cache_ttl":null,"dataset_query":{"lib/type":"mbql/query","database":2,"stages":[{"native":"SELECT\n  `source`.`nama_produk` AS `nama_produk`,\n  `source`.`sum` AS `sum`,\n  `source`.`sum_2` AS `sum_2`,\n  `source`.`sum` AS `Total Sales`,\n  `source`.`sum_2` AS `Total Nilai Stok`\nFROM\n  (\n    SELECT\n      `kba_gold`.`gold_product_performance`.`nama_produk` AS `nama_produk`,\n      SUM(\n        `kba_gold`.`gold_product_performance`.`total_sales`\n      ) AS `sum`,\n      SUM(\n        `kba_gold`.`gold_product_performance`.`nilai_stok`\n      ) AS `sum_2`\n    FROM\n      `kba_gold`.`gold_product_performance`\n    GROUP BY\n      `kba_gold`.`gold_product_performance`.`nama_produk`\n    ORDER BY\n      `kba_gold`.`gold_product_performance`.`nama_produk` ASC\n  ) AS `source`\nORDER BY\n  `source`.`sum` DESC\n","lib/type":"mbql.stage/native"}]},"parameter_mappings":[],"display":"row","archived_directly":false,"collection_preview":true,"visualization_settings":{"graph.y_axis.title_text":"Nilai","graph.show_values":true,"graph.y_axis.auto_split":false,"graph.metrics":["Total Sales","Total Nilai Stok"],"graph.label_value_formatting":"compact","column_settings":{"[\"name\",\"sum\"]":{"column_title":"Total Nilai Stok"},"[\"name\",\"Total Sales\"]":{"number_separators":", ","prefix":"$"},"[\"name\",\"Total Nilai Stok\"]":{"number_separators":", ","prefix":"$"}},"series_settings":{"Total Sales":{"color":"#F7C41F","display":"bar"}},"graph.x_axis.scale":"ordinal","graph.dimensions":["nama_produk"],"stackable.stack_type":"stacked"},"parameters":[],"dashboard_id":null}', false, false, NULL, false, 'v0.59.4 (d4fb593)');
