.metrics":["total_nilai_aktual"]},"parameters":[{"id":"18d927c5-4010-4c2b-97c3-626c14160100","type":"date/single","target":["variable",["template-tag","bulan"]],"name":"Bulan","slug":"bulan","isMultiSelect":false}],"dashboard_id":null}', false, false, NULL, false, 'v0.59.4 (d4fb593)');
