INSERT INTO public.revision VALUES (414, 'Card', 89, 1, '2026-04-28 08:38:13.800532+00', '{"description":"Produk slow moving dipetakan menurut total penjualan dan nilai stoknya. Bubble besar yang berada di bawah adalah stok slow moving dengan nilai tinggi.","archived":false,"collection_position":null,"source_card_id":null,"table_id":null,"embedding_type":null,"dependency_analysis_version":0,"card_schema":23,"database_id":2,"enable_embedding":false,"collection_id":4,"query_type":"native","name":"Slow Moving vs Sales","type":"question","embedding_params":null,"cache_ttl":null,"dataset_query":{"lib/type":"mbql/query","database":2,"stages":[{"lib/type":"mbql.stage/native","native":"SELECT\n  `kba_gold`.`gold_product_performance`.`periode_bulan` AS `periode_bulan`,\n  `kba_gold`.`gold_product_performance`.`id_produk` AS `id_produk`,\n  `kba_gold`.`gold_product_performance`.`nama_produk` AS `nama_produk`,\n  `kba_gold`.`gold_product_performance`.`total_sales` AS `total_sales`,\n  `kba_gold`.`gold_product_performance`.`total_qty` AS `total_qty`,\n  `kba_gold`.`gold_product_performance`.`nilai_stok` AS `nilai_stok`,\n  `kba_gold`.`gold_product_performance`.`is_slow_moving_flag` AS `is_slow_moving_flag`\nFROM\n  `kba_gold`.`gold_product_performance`\nwhere `is_slow_moving_flag` = 1"}]},"parameter_mappings":[],"display":"scatter","archived_directly":false,"collection_preview":true,"visualization_settings":{"graph.y_axis.title_text":"Total Penjualan","scatter.bubble":"nilai_stok","graph.series_order_dimension":null,"graph.x_axis.title_text":"Nama Produk","graph.metrics":["total_sales"],"graph.series_order":null,"column_settings":{"[\"name\",\"total_sales\"]":{"number_separators":", ","prefix":"$"}},"series_settings":{"total_sales":{"color":"#227FD2"}},"graph.x_axis.scale":"ordinal","graph.dimensions":["nama_produk"]},"parameters":[],"dashboard_id":null}', false, false, NULL, false, 'v0.59.4 (d4fb593)');
