INSERT INTO public.revision VALUES (479, 'Card', 81, 1, '2026-04-28 13:06:15.964025+00', '{"description":null,"archived":false,"collection_position":null,"source_card_id":null,"table_id":37,"embedding_type":null,"dependency_analysis_version":0,"card_schema":23,"database_id":2,"enable_embedding":false,"collection_id":4,"query_type":"native","name":"Product Demand Segment Composition","type":"question","embedding_params":null,"cache_ttl":null,"dataset_query":{"lib/type":"mbql/query","database":2,"stages":[{"lib/type":"mbql.stage/native","native":"SELECT\n  `kba_gold`.`gold_slow_moving`.`periode_bulanan` AS `periode_bulanan`,\n  `kba_gold`.`gold_slow_moving`.`id_produk` AS `id_produk`,\n  `kba_gold`.`gold_slow_moving`.`nilai_stok` AS `nilai_stok`,\n  `kba_gold`.`gold_slow_moving`.`is_slow_moving` AS `is_slow_moving`,\n  `kba_gold`.`gold_slow_moving`.`demand_segment` AS `demand_segment`,\n  `kba_gold`.`gold_slow_moving`.`slow_moving_reason` AS `slow_moving_reason`,\n  `kba_gold`.`gold_slow_moving`.`nama_produk` AS `nama_produk`\nFROM\n  `kba_gold`.`gold_slow_moving`\nWHERE `periode_bulanan` = \nCOALESCE(\n    [[ toStartOfMonth(toDate({{bulan}})) , ]] \n    toStartOfMonth(now())\n  )","template-tags":{"bulan":{"name":"bulan","id":"c56bd431-687a-4868-962f-837a2d376c2d","type":"date","display-name":"Bulan"}}}]},"parameter_mappings":[],"display":"pie","archived_directly":false,"collection_preview":true,"visualization_settings":{"pie.metric":"nilai_stok","pie.dimension":["demand_segment"],"pie.rows":[{"key":"dead_stock","name":"Dead Stock","originalName":"dead_stock","color":"#F7C41F","defaultColor":false,"enabled":true,"hidden":false,"isOther":false},{"key":"balanced_regular","name":"Balanced Regular","originalName":"balanced_regular","color":"#227FD2","defaultColor":false,"enabled":true,"hidden":false,"isOther":false},{"key":"frequent_small","name":"Frequent Small","originalName":"frequent_small","color":"#689636","defaultColor":false,"enabled":true,"hidden":false,"isOther