INSERT INTO public.revision VALUES (490, 'Card', 99, 1, '2026-04-28 13:12:36.07579+00', '{"description":"Daftar produk slow moving, diurutkan berdasarkan nilai stok tertinggi","archived":false,"collection_position":null,"source_card_id":null,"table_id":null,"embedding_type":null,"dependency_analysis_version":0,"card_schema":23,"database_id":2,"enable_embedding":false,"collection_id":6,"query_type":"native","name":"Top Slow Moving","type":"question","embedding_params":null,"cache_ttl":null,"dataset_query":{"lib/type":"mbql/query","database":2,"stages":[{"native":"SELECT\n  `kba_gold`.`gold_slow_moving`.`periode_bulanan` AS `Periode Bulan`,\n  `kba_gold`.`gold_slow_moving`.`id_produk` AS `ID Produk`,\n  `kba_gold`.`gold_slow_moving`.`nama_produk` AS `Nama Produk`,\n  `kba_gold`.`gold_slow_moving`.`nilai_stok` AS `Nilai Stok`,\n  `kba_gold`.`gold_slow_moving`.`demand_segment` AS `demand_segment`,\n  `kba_gold`.`gold_slow_moving`.`is_slow_moving` AS `is_slow_moving`,\n  `kba_gold`.`gold_slow_moving`.`slow_moving_reason` AS `slow_moving_reason`\nFROM\n  `kba_gold`.`gold_slow_moving`\nWHERE `periode_bulanan` = \nCOALESCE(\n    [[ toStartOfMonth(toDate({{bulan}})) , ]] \n    toStartOfMonth(now())\n  ) AND `is_slow_moving` = 1\nORDER BY nilai_stok desc","lib/type":"mbql.stage/native","template-tags":{"bulan":{"type":"date","name":"bulan","id":"1fd9c625-2306-44ff-8e1d-3e60000472f0","display-name":"Bulan","default":"2026-04-02"}}}]},"parameter_mappings":[],"display":"row","archived_directly":false,"collection_preview":true,"visualization_settings":{"graph.show_values":true,"table.cell_column":"id_produk","graph.series_order_dimension":null,"graph.metrics":["Nilai Stok"],"graph.label_value_formatting":"compact","graph.series_order":null,"table.pivot_column":"periode_bulanan","column_settings":{"[\"name\",\"Nilai Stok\"]":{"number_separators":", ","prefix":"$"}},"series_settings":{"Nilai Stok":{"color":"#227FD2"}},"graph.dimensions":["Nama Produk"]},"parameters":[{"id":"1fd9c62