INSERT INTO public.revision VALUES (507, 'Card', 114, 1, '2026-04-28 13:13:15.014395+00', '{"description":null,"archived":false,"collection_position":null,"source_card_id":null,"table_id":null,"embedding_type":null,"dependency_analysis_version":0,"card_schema":23,"database_id":2,"enable_embedding":false,"collection_id":6,"query_type":"native","name":"Sales Achievement Rate","type":"question","embedding_params":null,"cache_ttl":null,"dataset_query":{"lib/type":"mbql/query","database":2,"stages":[{"native":"SELECT\n  -- `kba_gold`.`gold_sales_achievement_conversion`.`periode_bulan` AS `periode_bulan`,\n  -- `kba_gold`.`gold_sales_achievement_conversion`.`achievement_rate` AS `achievement_rate`\n  *\nFROM\n  `kba_gold`.`gold_sales_achievement_conversion`\nWHERE `periode_bulan` <= \nCOALESCE(\n    [[ toStartOfMonth(toDate({{bulan}})) , ]] \n    toStartOfMonth(now())\n  )\nORDER BY `periode_bulan` ASC","lib/type":"mbql.stage/native","template-tags":{"bulan":{"id":"854961b7-4308-4671-9734-0569ba410d9e","display-name":"Bulan","type":"date","name":"bulan","default":null}}}]},"parameter_mappings":[],"display":"smartscalar","archived_directly":false,"collection_preview":true,"visualization_settings":{"progress.goal":100,"progress.color":"#689636","scalar.comparisons":[{"id":"cf85ad35-41ce-9ab7-85ef-9a43f7c84e28","type":"staticNumber","label":"Target Achievement","value":100},{"id":"bfdb6456-28a7-b6d3-b747-d34a1c693d9a","type":"previousValue"}],"scalar.switch_positive_negative":false,"scalar.compact_primary_number":true,"scalar.field":"achievement_rate","column_settings":{"[\"name\",\"achievement_rate\"]":{"suffix":"%","number_separators":", "}}},"parameters":[{"id":"854961b7-4308-4671-9734-0569ba410d9e","type":"date/single","target":["variable",["template-tag","bulan"]],"name":"Bulan","slug":"bulan","default":null,"isMultiSelect":false}],"dashboard_id":null}', false, true, NULL, true, 'v0.59.4 (d4fb593)');
INSERT INTO public.revision VALUES (508, 'Card', 115, 1, '2026-04-28 13:13:15.04425+00', '{"description":"Nilai stok dan total sales produk, diurutkan berdasarkan total sales tertinggi","archived":false,"collection_position":null,"source_card_id":null,"table_id":null,"embedding_type":null,"dependency_analysis_version":0,"card_schema":23,"database_id":2,"enable_embedding":false,"collection_id":6,"query_type":"native","name":"Product Sales and Inventory Value","type":"question","embedding_params":null,"cache_ttl":null,"dataset_query":{"lib/type":"mbql/query","database":2,"stages":[{"native":"SELECT\n  `periode_bulan`,\n  `source`.`nama_produk` AS `nama_produk`,\n  `source`.`sum` AS `sum`,\n  `source`.`sum_2` AS `sum_2`,\n  `source`.`sum` AS `Total Sales`,\n  `source`.`sum_2` AS `Total Nilai Stok`\nFROM\n  (\n    SELECT\n\t  `periode_bulan`,\n      `kba_gold`.`gold_product_performance`.`nama_produk` AS `nama_produk`,\n      SUM(\n        `kba_gold`.`gold_product_performance`.`total_sales`\n      ) AS `sum`,\n      SUM(\n        `kba_gold`.`gold_product_performance`.`nilai_stok`\n      ) AS `sum_2`\n    FROM\n      `kba_gold`.`gold_product_performance`\n\t  WHERE `periode_bulan` = \nCOALESCE(\n    [[ toStartOfMonth(toDate({{bulan}})) , ]] \n    toStartOfMonth(now())\n  ) \n    GROUP BY\n\t  `periode_bulan`,\n      `kba_gold`.`gold_product_performance`.`nama_produk`\n    ORDER BY\n      `kba_gold`.`gold_product_performance`.`nama_produk` ASC\n  ) AS `source`\nORDER BY\n  `source`.`sum` DESC\n\n","lib/type":"mbql.stage/native","template-tags":{"bulan":{"name":"bulan","id":"f4fe689f-e31c-456d-a46d-9f0c6e4d30b2","type":"date","display-name":"Bulan"}}}]},"parameter_mappings":[],"display":"row","archived_directly":false,"collection_preview":true,"visualization_settings":{"graph.y_axis.title_text":"Nilai","graph.show_values":true,"graph.x_axis.title_text":"Nama Produk","graph.y_axis.auto_split":false,"graph.metrics":["Total Sales","Total Nilai Stok"],"graph.label_value_formatting":"compact","column_settings":{"[\"name\",\"sum\"]":{"column_title":"Total Nilai Stok"},"[\"name\",\"Total Sales\"]":{"number_separators":", ","prefix":"$"},"[\"name\",\"Total Nilai Stok\"]":{"number_separators":", ","prefix":"$"}},"series_settings":{"Total Sales":{"color":"#F7C41F","display":"bar"},"Total Nilai Stok":{"color":"#227FD2"}},"graph.x_axis.scale":"ordinal","graph.dimensions":["nama_produk"],"stackable.stack_type":"stacked"},"parameters":[{"id":"f4fe689f-e31c-456d-a46d-9f0c6e4d30b2","type":"date/single","target":["variable",["template-tag","bulan"]],"name":"Bulan","slug":"bulan","isMultiSelect":false}],"dashboard_id":null}', false, true, NULL, true, 'v0.59.4 (d4fb593)');
INSERT INTO public.revision VALUES (509, 'Card', 116, 1, '2026-04-28 13:13:15.053859+00', '{"description":null,"archived":false,"collection_position":null,"source_card_id":null,"table_id":null,"embedding_type":null,"dependency_analysis_version":0,"card_schema":23,"database_id":2,"enable_embedding":false,"collection_id":6,"query_type":"native","name":"Sales Achievement Rate - Tren","type":"question","embedding_params":null,"cache_ttl":null,"dataset_query":{"lib/type":"mbql/query","database":2,"stages":[{"native":"SELECT\n  `kba_gold`.`gold_sales_achievement_conversion`.`periode_bulan` AS `Periode Bulan`,\n  `target_penjualan` as `Target Penjualan`,\n  `aktual_penjualan` as `Penjualan Aktual`,\n  `kba_gold`.`gold_sales_achievement_conversion`.`achievement_rate` AS `Achievement Rate`\nFROM\n  `kba_gold`.`gold_sales_achievement_conversion`\n-- WHERE {{bulan}}\nORDER BY `periode_bulan` ASC","lib/type":"mbql.stage/native"}]},"parameter_mappings":[],"display":"line","archived_directly":false,"collection_preview":true,"visualization_settings":{"scalar.comparisons":[{"id":"cf85ad35-41ce-9ab7-85ef-9a43f7c84e28","type":"staticNumber","label":"Target Achievement","value":100},{"id":"bfdb6456-28a7-b6d3-b747-d34a1c693d9a","type":"previousValue"}],"graph.y_axis.title_text":"Nilai","graph.show_values":true,"progress.color":"#689636","graph.x_axis.title_text":"Periode","progress.goal":100,"graph.y_axis.labels_enabled":false,"scalar.compact_primary_number":true,"graph.metrics":["Achievement Rate"],"graph.y_axis.unpin_from_zero":false,"graph.label_value_formatting":"compact","scalar.field":"achievement_rate","scalar.switch_positive_negative":false,"column_settings":{"[\"name\",\"Target Penjualan\"]":{"number_separators":", ","prefix":"$"},"[\"name\",\"Penjualan Aktual\"]":{"number_separators":", ","prefix":"$"},"[\"name\",\"Achievement Rate\"]":{"number_separators":", ","suffix":"%"}},"series_settings":{"Target Penjualan":{"color":"#87BCEC","display":"bar"},"Penjualan Aktual":{"display":"bar","color":"#F9D45C"},"Achievement Rate":{"color":"#227FD2","line.size":"L"}},"graph.x_axis.scale":"timeseries","graph.dimensions":["Periode Bulan"]},"parameters":[],"dashboard_id":null}', false, true, NULL, true, 'v0.59.4 (d4fb593)');
INSERT INTO public.revision VALUES (513, 'Card', 119, 1, '2026-04-28 13:13:28.96209+00', '{"description":null,"archived":false,"collection_position":null,"source_card_id":null,"table_id":null,"embedding_type":null,"dependency_analysis_version":0,"card_schema":23,"database_id":2,"enable_embedding":false,"collection_id":6,"query_type":"native","name":"Sales Conversion Rate","type":"question","embedding_params":null,"cache_ttl":null,"dataset_query":{"lib/type":"mbql/query","database":2,"stages":[{"native":"SELECT\n  -- `kba_gold`.`gold_sales_achievement_conversion`.`periode_bulan` AS `periode_bulan`,\n  -- `kba_gold`.`gold_sales_achievement_conversion`.`conversion_rate` AS `conversion_rate`\n  *\nFROM\n  `kba_gold`.`gold_sales_achievement_conversion`\nWHERE `periode_bulan` <= \nCOALESCE(\n    [[ toStartOfMonth(toDate({{bulan}})) , ]] \n    toStartOfMonth(now())\n  )\nORDER BY `periode_bulan` ASC","lib/type":"mbql.stage/native","template-tags":{"bulan":{"name":"bulan","id":"d1e5b910-38b6-466c-b3b0-4c34d31f346a","type":"date","display-name":"Bulan"}}}]},"parameter_mappings":[],"display":"smartscalar","archived_directly":false,"collection_preview":true,"visualization_settings":{"progress.goal":70,"progress.color":"#689636","scalar.field":"conversion_rate","scalar.comparisons":[{"id":"a9dd4d47-179a-6adf-2403-8e3ff0deabf0","type":"staticNumber","label":"Target Conversion","value":70},{"id":"0ece0d52-a3b5-4928-dc43-ac4737c7e883","type":"previousValue"}],"column_settings":{"[\"name\",\"conversion_rate\"]":{"suffix":"%"}}},"parameters":[{"id":"d1e5b910-38b6-466c-b3b0-4c34d31f346a","type":"date/single","target":["variable",["template-tag","bulan"]],"name":"Bulan","slug":"bulan","isMultiSelect":false}],"dashboard_id":null}', false, true, NULL, true, 'v0.59.4 (d4fb593)');
INSERT INTO public.revision VALUES (516, 'Card', 122, 1, '2026-04-28 13:13:28.98896+00', '{"description":null,"archived":false,"collection_position":null,"source_card_id":null,"table_id":null,"embedding_type":null,"dependency_analysis_version":0,"card_schema":23,"database_id":2,"enable_embedding":false,"collection_id":6,"query_type":"native","name":"Product Conversion Rate vs Sales Value","type":"question","embedding_params":null,"cache_ttl":null,"dataset_query":{"lib/type":"mbql/query","database":2,"stages":[{"native":"SELECT\n  -- `kba_gold`.`gold_product_conversion_rate`.`periode_bulan` AS `periode_bulan`,\n  -- `kba_gold`.`gold_product_conversion_rate`.`id_produk` AS `id_produk`,\n  -- `kba_gold`.`gold_product_conversion_rate`.`nama_produk` AS `nama_produk`,\n  -- `kba_gold`.`gold_product_conversion_rate`.`total_qty_quotation` AS `total_qty_quotation`,\n  -- `kba_gold`.`gold_product_conversion_rate`.`total_qty_aktual` AS `total_qty_aktual`,\n  -- `kba_gold`.`gold_product_conversion_rate`.`conversion_rate_value` AS `conversion_rate_value`\n  *\nFROM\n  `kba_gold`.`gold_product_conversion_rate`\nWHERE `periode_bulan` = \nCOALESCE(\n    [[ toStartOfMonth(toDate({{bulan}})) ,]]\n    toStartOfMonth(now())\n  )\n\n  order by `conversion_rate_value` desc, `total_qty_aktual` desc","lib/type":"mbql.stage/native","template-tags":{"bulan":{"type":"date","name":"bulan","id":"21054f1c-c129-436b-9387-0c1c60b5177f","display-name":"Bulan"}}}]},"parameter_mappings":[],"display":"row","archived_directly":false,"collection_preview":true,"visualization_settings":{"stackable.stack_type":null,"graph.show_values":true,"series_settings":{"conversion_rate_value":{"color":"#227FD2"},"total_nilai_aktual":{"color":"#227FD2"}},"graph.dimensions":["nama_produk"],"graph.series_order_dimension":null,"graph.series_order":null,"column_settings":{"[\"name\",\"total_nilai_aktual\"]":{"number_separators":", ","prefix":"$"},"[\"name\",\"conversion_rate_value\"]":{"number_separators":", ","suffix":"%"}},"graph.metrics":["total_nilai_aktual"]},"parameters":[{"id":"21054f1c-c129-436b-9387-0c1c60b5177f","type":"date/single","target":["variable",["template-tag","bulan"]],"name":"Bulan","slug":"bulan","isMultiSelect":false}],"dashboard_id":null}', false, true, NULL, true, 'v0.59.4 (d4fb593)');
INSERT INTO public.revision VALUES (520, 'Card', 125, 1, '2026-04-28 13:13:42.685502+00', '{"description":"Nilai/value total stok dengan kategori slow moving","archived":false,"collection_position":null,"source_card_id":null,"table_id":null,"embedding_type":null,"dependency_analysis_version":0,"card_schema":23,"database_id":2,"enable_embedding":false,"collection_id":6,"query_type":"native","name":"Slow Moving Value","type":"question","embedding_params":null,"cache_ttl":null,"dataset_query":{"lib/type":"mbql/query","database":2,"stages":[{"lib/type":"mbql.stage/native","native":"SELECT\n  `periode_bulanan`,\n  SUM(CASE WHEN is_slow_moving = 1 THEN nilai_stok ELSE 0 END) AS total_stok_slow_moving,\n  SUM(nilai_stok) AS total_seluruh_stok,\n  SUM(CASE WHEN is_slow_moving = 1 THEN nilai_stok ELSE 0 END) * 100 / SUM(nilai_stok) AS rasio_slow_moving\nFROM\n  `kba_gold`.`gold_slow_moving`\nWHERE `periode_bulanan` <= \nCOALESCE(\n    [[ toStartOfMonth(toDate({{bulan}})) , ]] \n    toStartOfMonth(now())\n  )\nGROUP BY `periode_bulanan`","template-tags":{"bulan":{"type":"date","display-name":"Bulan","name":"bulan","id":"c27cea3d-ca3b-40f7-8533-8182000603b8","default":null}}}]},"parameter_mappings":[],"display":"scalar","archived_directly":false,"collection_preview":true,"visualization_settings":{"scalar.field":"rasio_slow_moving","scalar.segments":[{"min":0,"max":24,"color":"#689735","label":"Aman"},{"min":25,"max":59,"color":"#E8B921","label":"Waspada"},{"min":60,"max":100,"color":"#E3595E","label":"Kritis"}],"column_settings":{"[\"name\",\"rasio_slow_moving\"]":{"suffix":"%"}}},"parameters":[{"id":"c27cea3d-ca3b-40f7-8533-8182000603b8","type":"date/single","target":["variable",["template-tag","bulan"]],"name":"Bulan","slug":"bulan","default":null,"isMultiSelect":false}],"dashboard_id":null}', false, true, NULL, true, 'v0.59.4 (d4fb593)');
INSERT INTO public.revision VALUES (521, 'Card', 126, 1, '2026-04-28 13:13:42.692662+00', '{"description":"Produk slow moving dipetakan menurut total penjualan dan nilai stoknya. Bubble besar yang berada di bawah adalah stok slow moving dengan nilai inventory tinggi.","archived":false,"collection_position":null,"source_card_id":null,"table_id":null,"embedding_type":null,"dependency_analysis_version":0,"card_schema":23,"database_id":2,"enable_embedding":false,"collection_id":6,"query_type":"native","name":"Slow Moving vs Sales","type":"question","embedding_params":null,"cache_ttl":null,"dataset_query":{"lib/type":"mbql/query","database":2,"stages":[{"lib/type":"mbql.stage/native","native":"SELECT\n  `kba_gold`.`gold_product_performance`.`periode_bulan` AS `periode_bulan`,\n  `kba_gold`.`gold_product_performance`.`id_produk` AS `id_produk`,\n  `kba_gold`.`gold_product_performance`.`nama_produk` AS `nama_produk`,\n  `kba_gold`.`gold_product_performance`.`total_sales` AS `total_sales`,\n  `kba_gold`.`gold_product_performance`.`total_qty` AS `total_qty`,\n  `kba_gold`.`gold_product_performance`.`nilai_stok` AS `nilai_stok`,\n  `kba_gold`.`gold_product_performance`.`is_slow_moving_flag` AS `is_slow_moving_flag`\nFROM\n  `kba_gold`.`gold_product_performance`\nwhere `is_slow_moving_flag` = 1"}]},"parameter_mappings":[],"display":"scatter","archived_directly":false,"collection_preview":true,"visualization_settings":{"graph.y_axis.title_text":"Total Penjualan","scatter.bubble":"nilai_stok","graph.series_order_dimension":null,"graph.x_axis.title_text":"Nama Produk","graph.metrics":["total_sales"],"graph.series_order":null,"column_settings":{"[\"name\",\"total_sales\"]":{"number_separators":", ","prefix":"$"}},"series_settings":{"total_sales":{"color":"#227FD2"}},"graph.x_axis.scale":"ordinal","graph.dimensions":["nama_produk"]},"parameters":[],"dashboard_id":null}', false, true, NULL, true, 'v0.59.4 (d4fb593)');
INSERT INTO public.revision VALUES (523, 'Card', 127, 1, '2026-04-28 13:13:55.981038+00', '{"description":"Rata-rata persentase On Time Delivery Vendor, diurutkan berdasarkan performance terbaik","archived":false,"collection_position":null,"source_card_id":null,"table_id":null,"embedding_type":null,"dependency_analysis_version":0,"card_schema":23,"database_id":2,"enable_embedding":false,"collection_id":6,"query_type":"native","name":"Vendor Performance","type":"question","embedding_params":null,"cache_ttl":null,"dataset_query":{"lib/type":"mbql/query","database":2,"stages":[{"lib/type":"mbql.stage/native","native":"SELECT\n  `kba_gold`.`gold_vendor`.`periode_bulan` AS `periode_bulan`,\n  `kba_gold`.`gold_vendor`.`id_vendor` AS `id_vendor`,\n  `kba_gold`.`gold_vendor`.`nama_vendor` AS `nama_vendor`,\n  `kba_gold`.`gold_vendor`.`total_pengiriman` AS `total_pengiriman`,\n  `kba_gold`.`gold_vendor`.`tepat_waktu` AS `tepat_waktu`,\n  `kba_gold`.`gold_vendor`.`otd_pct` AS `otd_pct`\nFROM\n  `kba_gold`.`gold_vendor`\nWHERE `periode_bulan` = \nCOALESCE(\n    [[ toStartOfMonth(toDate({{bulan}})) , ]] \n    toStartOfMonth(now())\n  )\norder by otd_pct desc","template-tags":{"bulan":{"name":"bulan","display-name":"Bulan","id":"fd5402b5-cb4a-4a5f-9f24-2ed362ee20f3","type":"date","default":"2026-04-02"}}}]},"parameter_mappings":[],"display":"row","archived_directly":false,"collection_preview":true,"visualization_settings":{"graph.y_axis.title_text":"Rata-rata OTD Rate (%)","graph.show_values":true,"graph.x_axis.title_text":"Nama Vendor","graph.label_value_frequency":"all","graph.metrics":["otd_pct"],"graph.label_value_formatting":"full","column_settings":{"[\"name\",\"otd_pct\"]":{"suffix":"%","number_separators":", "}},"series_settings":{"avg":{"color":"#227FD2"},"otd_pct":{"color":"#227FD2"}},"graph.x_axis.scale":"ordinal","graph.dimensions":["nama_vendor"]},"parameters":[{"id":"fd5402b5-cb4a-4a5f-9f24-2ed362ee20f3","type":"date/single","target":["variable",["template-tag","bulan"]],"name":"Bulan","slug":"bulan","default":"2026-04-02","isMultiSelect":false}],"dashboard_id":null}', false, true, NULL, true, 'v0.59.4 (d4fb593)');
