INSERT INTO public.revision VALUES (525, 'Card', 129, 1, '2026-04-28 13:13:56.000485+00', '{"description":null,"archived":false,"collection_position":null,"source_card_id":null,"table_id":null,"embedding_type":null,"dependency_analysis_version":0,"card_schema":23,"database_id":2,"enable_embedding":false,"collection_id":6,"query_type":"native","name":"Vendor Risk Matrix","type":"question","embedding_params":null,"cache_ttl":null,"dataset_query":{"lib/type":"mbql/query","database":2,"stages":[{"native":"SELECT\n  `kba_gold`.`gold_vendor`.`id_vendor` AS `id_vendor`,\n  `kba_gold`.`gold_vendor`.`nama_vendor` AS `nama_vendor`,\n  `kba_gold`.`gold_vendor`.`periode_bulan` AS `periode_bulan`,\n  `kba_gold`.`gold_vendor`.`total_pengiriman` AS `total_pengiriman`,\n  `kba_gold`.`gold_vendor`.`tepat_waktu` AS `tepat_waktu`,\n  `kba_gold`.`gold_vendor`.`terlambat` AS `terlambat`,\n  `kba_gold`.`gold_vendor`.`otd_pct` AS `otd_pct`,\n  `kba_gold`.`gold_vendor`.`avg_delay_days` AS `avg_delay_days`,\n  `kba_gold`.`gold_vendor`.`max_delay_days` AS `max_delay_days`,\n  `kba_gold`.`gold_vendor`.`internal_scheduling_gap` AS `internal_scheduling_gap`\nFROM\n  `kba_gold`.`gold_vendor`\nWHERE `periode_bulan` = \nCOALESCE(\n    [[ toStartOfMonth(toDate({{bulan}})) , ]] \n    toStartOfMonth(now())\n  )","lib/type":"mbql.stage/native","template-tags":{"bulan":{"type":"date","display-name":"Bulan","name":"bulan","id":"95bbe1ac-580d-4a03-b034-5fddaa5daba7","default":null}}}]},"parameter_mappings":[],"display":"scatter","archived_directly":false,"collection_preview":true,"visualization_settings":{"graph.show_goal":true,"graph.show_trendline":false,"graph.y_axis.title_text":"avg OTD Rate","scatter.bubble":"total_pengiriman","graph.goal_label":"Target OTD","graph.series_order_dimension":null,"graph.goal_value":90,"graph.metrics":["otd_pct"],"graph.series_order":null,"column_settings":{"[\"name\",\"otd_pct\"]":{"number_separators":", ","suffix":"%","decimals":1},"[\"name\",\"avg_delay_days\"]":{"nu