INSERT INTO public.revision VALUES (229, 'Card', 62, 1, '2026-04-28 00:50:47.546288+00', '{"description":"Nilai/value total stok dengan kategori slow moving","archived":false,"collection_position":null,"source_card_id":null,"table_id":null,"embedding_type":null,"dependency_analysis_version":0,"card_schema":23,"database_id":2,"enable_embedding":false,"collection_id":4,"query_type":"native","name":"Slow Moving Value","type":"question","embedding_params":null,"cache_ttl":null,"dataset_query":{"lib/type":"mbql/query","database":2,"stages":[{"native":"SELECT\n  `periode_bulanan`,\n  SUM(CASE WHEN is_slow_moving = 1 THEN nilai_stok ELSE 0 END) AS total_stok_slow_moving,\n  SUM(nilai_stok) AS total_seluruh_stok,\n  SUM(CASE WHEN is_slow_moving = 1 THEN nilai_stok ELSE 0 END) * 100 / SUM(nilai_stok) AS rasio_slow_moving\nFROM\n  `kba_gold`.`gold_slow_moving`\nWHERE `periode_bulanan` <= \nCOALESCE(\n    [[ toStartOfMonth(toDate({{bulan}})) , ]] \n    toStartOfMonth(now())\n  )\nGROUP BY `periode_bulanan`","lib/type":"mbql.stage/native","template-tags":{"bulan":{"display-name":"Bulan","name":"bulan","id":"c27cea3d-ca3b-40f7-8533-8182000603b8","type":"date","default":null}}}]},"parameter_mappings":[],"display":"scalar","archived_directly":false,"collection_preview":true,"visualization_settings":{"scalar.field":"rasio_slow_moving","scalar.segments":[{"min":0,"max":24,"color":"#689735","label":"Aman"},{"min":25,"max":59,"color":"#E8B921","label":"Waspada"},{"min":60,"max":100,"color":"#E3595E","label":"Kritis"}],"column_settings":{"[\"name\",\"rasio_slow_moving\"]":{"suffix":"%"}}},"parameters":[{"id":"c27cea3d-ca3b-40f7-8533-8182000603b8","type":"date/single","target":["variable",["template-tag","bulan"]],"name":"Bulan","slug":"bulan","default":null,"isMultiSelect":false}],"dashboard_id":null}', false, false, NULL, false, 'v0.59.4 (d4fb593)');
