INSERT INTO public.revision VALUES (415, 'Card', 89, 1, '2026-04-28 08:38:39.868859+00', '{"description":"Produk slow moving dipetakan menurut total penjualan dan nilai stoknya. Bubble besar yang berada di bawah adalah stok slow moving dengan nilai inventory tinggi.","archived":false,"collection_position":null,"source_card_id":null,"table_id":null,"embedding_type":null,"dependency_analysis_version":0,"card_schema":23,"database_id":2,"enable_embedding":false,"collection_id":4,"query_type":"native","name":"Slow Moving vs Sales","type":"question","embedding_params":null,"cache_ttl":null,"dataset_query":{"lib/type":"mbql/query","database":2,"stages":[{"lib/type":"mbql.stage/native","native":"SELECT\n  `kba_gold`.`gold_product_performance`.`periode_bulan` AS `periode_bulan`,\n  `kba_gold`.`gold_product_performance`.`id_produk` AS `id_produk`,\n  `kba_gold`.`gold_product_performance`.`nama_produk` AS `nama_produk`,\n  `kba_gold`.`gold_product_performance`.`total_sales` AS `total_sales`,\n  `kba_gold`.`gold_product_performance`.`total_qty` AS `total_qty`,\n  `kba_gold`.`gold_product_performance`.`nilai_stok` AS `nilai_stok`,\n  `kba_gold`.`gold_product_performance`.`is_slow_moving_flag` AS `is_slow_moving_flag`\nFROM\n  `kba_gold`.`gold_product_performance`\nwhere `is_slow_moving_flag` = 1"}]},"parameter_mappings":[],"display":"scatter","archived_directly":false,"collection_preview":true,"visualization_settings":{"graph.y_axis.title_text":"Total Penjualan","scatter.bubble":"nilai_stok","graph.series_order_dimension":null,"graph.x_axis.title_text":"Nama Produk","graph.metrics":["total_sales"],"graph.series_order":null,"column_settings":{"[\"name\",\"total_sales\"]":{"number_separators":", ","prefix":"$"}},"series_settings":{"total_sales":{"color":"#227FD2"}},"graph.x_axis.scale":"ordinal","graph.dimensions":["nama_produk"]},"parameters":[],"dashboard_id":null}', false, false, NULL, false, 'v0.59.4 (d4fb593)');
INSERT INTO public.revision VALUES (568, 'Card', 62, 1, '2026-05-02 09:16:34.674343+00', '{"description":"Nilai/value total stok dengan kategori slow moving","archived":false,"collection_position":null,"source_card_id":null,"table_id":null,"embedding_type":null,"dependency_analysis_version":0,"card_schema":23,"database_id":2,"enable_embedding":false,"collection_id":4,"query_type":"native","name":"Slow Moving Value","type":"question","embedding_params":null,"cache_ttl":null,"dataset_query":{"lib/type":"mbql/query","database":2,"stages":[{"native":"SELECT\n  `periode_bulanan`,\n  SUM(CASE WHEN is_slow_moving = 1 THEN nilai_stok ELSE 0 END) AS total_stok_slow_moving,\n  SUM(nilai_stok) AS total_seluruh_stok,\n  SUM(CASE WHEN is_slow_moving = 1 THEN nilai_stok ELSE 0 END) * 100 / SUM(nilai_stok) AS rasio_slow_moving\nFROM\n  `kba_gold`.`gold_slow_moving`\nWHERE `periode_bulanan` <= \nCOALESCE(\n    [[ toStartOfMonth(toDate({{bulan}})) , ]] \n    toStartOfMonth(now())\n  )\nGROUP BY `periode_bulanan`","lib/type":"mbql.stage/native","template-tags":{"bulan":{"name":"bulan","id":"17b918c5-2395-47b8-a273-7014a43feaa5","type":"text","display-name":"Bulan"}}}]},"parameter_mappings":[],"display":"scalar","archived_directly":false,"collection_preview":true,"visualization_settings":{"scalar.field":"rasio_slow_moving","scalar.segments":[{"min":0,"max":24,"color":"#689735","label":"Aman"},{"min":25,"max":59,"color":"#E8B921","label":"Waspada"},{"min":60,"max":100,"color":"#E3595E","label":"Kritis"}],"column_settings":{"[\"name\",\"rasio_slow_moving\"]":{"suffix":"%"}}},"parameters":[{"id":"17b918c5-2395-47b8-a273-7014a43feaa5","type":"string/=","target":["variable",["template-tag","bulan"]],"name":"Bulan","slug":"bulan","isMultiSelect":false}],"dashboard_id":null}', false, false, NULL, false, 'v0.59.4 (d4fb593)');
