INSERT INTO public.revision VALUES (592, 'Card', 135, 1, '2026-05-02 11:54:32.571832+00', '{"description":"Daftar produk slow moving, diurutkan berdasarkan nilai stok tertinggi","archived":false,"collection_position":null,"source_card_id":null,"table_id":null,"embedding_type":null,"dependency_analysis_version":0,"card_schema":23,"database_id":2,"enable_embedding":false,"collection_id":4,"query_type":"native","name":"Top Slow Moving","type":"question","embedding_params":null,"cache_ttl":null,"dataset_query":{"lib/type":"mbql/query","database":2,"stages":[{"native":"SELECT\n  `kba_gold`.`gold_slow_moving`.`periode_bulanan` AS `Periode Bulan`,\n  `kba_gold`.`gold_slow_moving`.`id_produk` AS `ID Produk`,\n  `kba_gold`.`gold_slow_moving`.`nama_produk` AS `Nama Produk`,\n  `kba_gold`.`gold_slow_moving`.`nilai_stok` AS `Nilai Stok`,\n  `kba_gold`.`gold_slow_moving`.`demand_segment` AS `demand_segment`,\n  `kba_gold`.`gold_slow_moving`.`is_slow_moving` AS `is_slow_moving`,\n  `kba_gold`.`gold_slow_moving`.`slow_moving_reason` AS `slow_moving_reason`\nFROM\n  `kba_gold`.`gold_slow_moving`\nWHERE `periode_bulanan` = \nCOALESCE(\n    [[ toStartOfMonth(toDate({{bulan}})) , ]] \n    toStartOfMonth(now())\n  ) AND `is_slow_moving` IN ({{Kategori}})\nORDER BY nilai_stok desc","lib/type":"mbql.stage/native","template-tags":{"bulan":{"type":"date","name":"bulan","id":"bdf2f4c2-d859-4583-8964-3eda0a430770","display-name":"Bulan"},"Kategori":{"name":"Kategori","id":"602bff62-d74c-4905-8389-6ffc2d7ccc2a","default":["1"],"type":"text","display-name":"Kategori","required":true}}}]},"parameter_mappings":[],"display":"row","archived_directly":false,"collection_preview":true,"visualization_settings":{"graph.show_values":true,"table.cell_column":"id_produk","graph.series_order_dimension":null,"graph.metrics":["Nilai Stok"],"graph.label_value_formatting":"compact","graph.series_order":null,"table.pivot_column":"periode_bulanan","column_settings":{"[\"name\",\"Nilai Stok\"]":{"number_separator