INSERT INTO public.revision VALUES (650, 'Card', 137, 1, '2026-05-09 03:52:06.838152+00', '{"description":null,"archived":false,"collection_position":null,"source_card_id":null,"table_id":null,"embedding_type":null,"dependency_analysis_version":0,"card_schema":23,"database_id":2,"enable_embedding":false,"collection_id":4,"query_type":"native","name":"Tabel Produk - slow movng & demand segment","type":"question","embedding_params":null,"cache_ttl":null,"dataset_query":{"lib/type":"mbql/query","database":2,"stages":[{"native":"SELECT\n  `kba_gold`.`gold_slow_moving`.`periode_bulanan` AS `Periode Bulanan`,\n  `kba_gold`.`gold_slow_moving`.`snapshot_type` AS `Snapshot Type`,\n  `kba_gold`.`gold_slow_moving`.`nama_produk` AS `Nama Produk`,\n  -- `kba_gold`.`gold_slow_moving`.`id_produk` AS `id_produk`,\n  `kba_gold`.`gold_slow_moving`.`nilai_stok` AS `Nilai Stok`,\n  CASE  \n  WHEN `kba_gold`.`gold_slow_moving`.`is_slow_moving` = 1 THEN ''Slow Moving''\n  WHEN `kba_gold`.`gold_slow_moving`.`is_slow_moving` = 0 THEN ''Non Slow Moving''\n  ELSE ''Unknown''\n  END AS `Status Slow Moving`,\n  `kba_gold`.`gold_slow_moving`.`demand_segment` AS `Demand Segment`,\n  `kba_gold`.`gold_slow_moving`.`slow_moving_reason` AS `slow_moving_reason`\n  \nFROM\n  `kba_gold`.`gold_slow_moving`\nWHERE `periode_bulanan` = \nCOALESCE(\n    [[ toStartOfMonth(toDate({{bulan}})) , ]] \n    toStartOfMonth(now())\n  ) AND `is_slow_moving` IN ({{Kategori}})\n  AND `snapshot_type` IN ({{Snapshot}})","lib/type":"mbql.stage/native","template-tags":{"bulan":{"id":"e1752801-f2fc-497e-b209-dbd3f6d3608f","display-name":"Bulan","required":false,"type":"date","name":"bulan","default":null},"Kategori":{"display-name":"Kategori","default":["1"],"name":"Kategori","id":"7387fc39-351e-4b7e-b826-6498be688002","type":"text","required":true},"Snapshot":{"name":"Snapshot","id":"53e8bd26-df0f-4517-a755-f32eec51dc92","default":["Historical"],"type":"text","display-name":"Snapshot","required":true}}}]},"parameter_mappin