INSERT INTO public.search_index__649xe8gv_kmwojy1rz4bs VALUES (207, '''composit'':3A,6B ''composition'':20 ''dan'':14B,28 ''dengan'':9B,23 ''jumlah'':7B,21 ''kategori'':10B,24 ''move'':2A,5B,13B,17B ''moving'':19,27,31 ''non'':15B,29 ''produk'':8B,22 ''slow'':1A,4B,12B,16B,18,26,30 ''stok'':11B,25', '''0.125'':55B,56B,85B,86B,98B,99B ''asc'':100B ''bulan'':109B ''bulanan'':20B,43B,73B,105B ''coalesc'':106B ''composit'':3A,6B ''composition'':118 ''count'':32B,34B,36B,61B,63B ''dan'':14B,126 ''dengan'':9B,121 ''floor'':46B,76B,89B ''gold'':48B,49B,66B,67B,78B,79B,91B,92B ''group'':70B ''histor'':115B ''jumlah'':7B,38B,119 ''kategori'':10B,122 ''kba'':47B,65B,77B,90B ''move'':2A,5B,13B,17B,26B,30B,51B,54B,60B,69B,81B,84B,94B,97B ''moving'':117,125,129 ''non'':15B,127 ''order'':87B ''period'':19B,42B,72B,104B ''produk'':8B,39B,120 ''select'':18B,41B ''slow'':1A,4B,12B,16B,25B,29B,50B,53B,59B,68B,80B,83B,93B,96B,116,124,128 ''snapshot'':21B,44B,74B,113B ''sourc'':23B,31B,35B,102B ''stok'':11B,123 ''todat'':108B ''tostartofmonth'':107B,110B ''type'':22B,45B,75B,114B', 'card', '{"name":"Slow Moving Composition","description":"Jumlah produk dengan kategori stok slow moving dan non slow moving","collection_name":"Admin KBA7''s Personal Collection"}', '{"description":"Jumlah produk dengan kategori stok slow moving dan non slow moving","archived":false,"display_type":"pie","collection_position":null,"database_id":2,"collection_id":4,"official_collection":null,"name":"Slow Moving Composition","collection_name":"Admin KBA7''s Personal Collection","collection_authority_level":null,"creator_id":1,"updated_at":"2026-05-09T05:22:20.987289Z","moderated_status":null,"dataset_query":"{\"lib/type\":\"mbql/query\",\"database\":2,\"stages\":[{\"native\":\"SELECT\\n  `periode_bulanan`,\\n  `snapshot_type`,\\n  `source`.`is_slow_moving` AS `is_slow_moving`,\\n  `source`.`count` AS `count`,\\n  `source`.`count` AS `Jumlah Produk`\\nFROM\\n  (\\n    SELECT\\n\\t  `periode_bulanan`,\\n\\t  `snapshot_type`,\\n      FLOOR(\\n        (\\n          `kba_gold`.`gold_slow_moving`.`is_slow_moving` / 0.125\\n        )\\n      ) * 0.125 AS `is_slow_moving`,\\n      COUNT(*) AS `count`\\n    FROM\\n      `kba_gold`.`gold_slow_moving`\\n    GROUP BY\\n\\t  `periode_bulanan`,\\n\\t  `snapshot_type`,\\n      FLOOR(\\n        (\\n          `kba_gold`.`gold_slow_moving`.`is_slow_moving` / 0.125\\n        )\\n      ) * 0.125\\n    ORDER BY\\n      FLOOR(\\n        (\\n          `kba_gold`.`gold_slow_moving`.`is_slow_moving` / 0.125\\n        )\\n      ) * 0.125 ASC\\n  ) AS `source`\\nWHERE `periode_bulanan` = \\nCOALESCE(\\n    [[ toStartOfMonth(toDate({{bulan}})) , ]] \\n    toStartOfMonth(now())\\n  ) AND `snapshot_type` = ''Historical''\",\"lib/type\":\"mbql.stage/native\",\"template-tags\":{\"bulan\":{\"id\":\"48db9bbd-7275-44f0-8540-56ef79f4ea38\",\"type\":\"date\",\"display-name\":\"Bulan\",\"name\":\"bulan\",\"default\":null}}}]}","last_editor_id":1,"collection_location":"/","id":71,"last_edited_at":"2026-05-09T05:22:21.040395Z","dashboardcard_count":1,"collection_type":null,"display":"pie","archived_directly":false,"verified":null,"dashboard_id":null,"created_at":"2026-04-27T11:46:35.113477Z","model":"card"}', '2026-05-09 11:57:28.854215+00', '2026-05-10 03:02:17.637699+00', false, '2026-05-09 05:22:20.987289+00', NULL, false, 4, NULL, 'Slow Moving Composition', NULL, false, '2026-05-09 05:22:21.040395+00', 1, '[]', NULL, 1, '71', 'pie', '2026-05-10 03:01:26.472858+00', 2, 1, 389, '2026-04-27 11:46:35.113477+00', NULL);
