ce`.`nama_produk` AS `nama_produk`,\\n  `source`.`sum` AS `sum`,\\n  `source`.`sum_2` AS `sum_2`,\\n  `source`.`sum` AS `Total Sales`,\\n  `source`.`sum_2` AS `Total Nilai Stok`\\nFROM\\n  (\\n    SELECT\\n\\t  `periode_bulan`,\\n      `kba_gold`.`gold_product_performance`.`nama_produk` AS `nama_produk`,\\n      SUM(\\n        `kba_gold`.`gold_product_performance`.`total_sales`\\n      ) AS `sum`,\\n      SUM(\\n        `kba_gold`.`gold_product_performance`.`nilai_stok`\\n      ) AS `sum_2`\\n    FROM\\n      `kba_gold`.`gold_product_performance`\\n\\t  WHERE `periode_bulan` = \\nCOALESCE(\\n    [[ toStartOfMonth(toDate({{bulan}})) , ]] \\n    toStartOfMonth(now())\\n  ) \\n    GROUP BY\\n\\t  `periode_bulan`,\\n      `kba_gold`.`gold_product_performance`.`nama_produk`\\n    ORDER BY\\n      `kba_gold`.`gold_product_performance`.`nama_produk` ASC\\n  ) AS `source`\\nORDER BY\\n  `source`.`sum` DESC\\n\\n\",\"template-tags\":{\"bulan\":{\"id\":\"f4fe689f-e31c-456d-a46d-9f0c6e4d30b2\",\"type\":\"date\",\"name\":\"bulan\",\"display-name\":\"Bulan\"}}}]}","last_editor_id":1,"collection_location":"/","id":115,"last_edited_at":"2026-04-28T13:13:15.04425Z","dashboardcard_count":1,"collection_type":null,"display":"row","archived_directly":false,"verified":null,"dashboard_id":null,"created_at":"2026-04-28T13:13:14.889176Z","model":"card"}', '2026-05-09 10:13:01.34051+00', '2026-05-09 10:13:01.34051+00', false, '2026-04-28 13:13:14.889176+00', NULL, false, 6, NULL, 'Product Sales and Inventory Value', NULL, false, '2026-04-28 13:13:15.04425+00', 1, '[]', NULL, 1, '115', 'row', '2026-04-28 13:28:41.317169+00', 2, 1, 11, '2026-04-28 13:13:14.889176+00', NULL);
